INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$6116eaa3-5967-5f27-9dde-e506df76ac6a$ml$::uuid, $ml$web3$ml$, 1, 1, $ml${"id": "web3-d1-c1", "title": "Blocks kept coming, but nothing was final", "lessonTitle": "How a blockchain works", "slot": 1, "type": "apply", "brief": {"headline": "On May 11 and 12, 2023, Ethereum stopped finalizing blocks twice, for about 25 minutes and then over an hour. Blocks were still proposed. The network had not yet agreed they were permanent.", "kicker": "Apply day 1: consensus is agreement, not just new blocks.", "fullText": "Ethereum uses proof of stake. Validators propose blocks and vote on them. When enough of them agree, a checkpoint becomes final, and changing it would cost attackers a huge amount of staked ETH.\n\nIn May 2023, high load on some consensus clients knocked many validators offline. Blocks kept being proposed, EtherWorld reported, but they could not be finalized. The first stall lasted about 25 minutes and the second over an hour, according to The Block. Prysm and Teku shipped patches, and finality returned once clients caught up.\n\nThrough the day 1 lens: a block is a proposal. Consensus is what makes it part of the agreed history.", "sources": [{"url": "https://www.theblock.co/post/230723", "label": "The Block, Ethereum developers patch beacon chain finality issues, May 2023"}, {"url": "https://etherworld.co/non-finality-inactivity-leak-but-ethereum-didnt-stop", "label": "EtherWorld, non-finality and inactivity leak, but Ethereum didn't stop"}, {"url": "https://ethereum.org/staking/", "label": "ethereum.org, staking"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the May 2023 stall. Tap it.", "statements": ["New blocks were still being proposed.", "Blocks could not be finalized for a while.", "Ethereum had switched back to proof of work."], "fakeIndex": 2, "explanation": "Ethereum stayed on proof of stake. Blocks kept coming, but validators could not reach finality until clients recovered."}, "numbers": {"kind": "numberSense", "prompt": "The first loss of finality lasted about how many minutes?", "min": 0, "max": 120, "value": 25, "explanation": "About 25 minutes. The second stall lasted over an hour before patched clients restored finality.", "unit": "min"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview for a node operations role at a staking firm. They ask what the May 2023 stall showed.", "prompt": "Which answer lands best?", "options": ["Ethereum lost every transaction from those days", "Validators stopped producing any blocks at all", "Blocks kept coming, but agreement on them stalled"], "correctIndex": 2, "consequences": ["Users kept transacting; the chain did not lose history.", "Blocks were still proposed throughout the stall.", "You separate block production from finality, which is the real lesson."], "explanation": "Finality is the agreement step. Naming it shows you understand how proof of stake actually settles."}, "proReasoning": "Operators watch finality, not just block production. A chain can look busy while its agreement is stuck.", "commonMistake": "Treating any stream of new blocks as proof the chain is healthy.", "mentalModel": "Production is not agreement."}, "invest": {"call": {"kind": "theCall", "situation": "You hold ETH and read that the network briefly could not finalize blocks.", "prompt": "What is the key question for you?", "options": ["How diverse the client software is", "Whether ETH traded lower that afternoon", "Nothing, since blocks kept coming"], "correctIndex": 0, "consequences": ["Patched clients fixed it; a single shared bug is the deeper risk.", "Price moves fade; the cause tells you more.", "Finality is what makes payments safe to rely on."], "explanation": "The stall came from load on some clients. A network running many different clients recovers faster."}, "proReasoning": "Investors ask what breaks consensus and how fast it heals. Client diversity is part of the answer.", "commonMistake": "Ignoring a finality stall because the price barely moved.", "mentalModel": "Ask how agreement recovers."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app credits user deposits on Ethereum. A finality stall like May 2023 starts.", "prompt": "What do you do with new deposits?", "options": ["Refund every deposit during the stall", "Credit them only once their block is final", "Credit them the moment they appear"], "correctIndex": 1, "consequences": ["Refunds create work and confusion for a short stall.", "Final blocks are the ones that cannot be cheaply undone.", "A block that is not final can still be reorganized."], "explanation": "Finality is the safety line for large credits. Waiting a little protects you during a stall."}, "proReasoning": "Builders tie credits to finality, especially for large amounts. A short wait beats a reversed deposit.", "commonMistake": "Treating a just-proposed block as settled money.", "mentalModel": "Credit what is final."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a blockchain can keep making blocks but still not be \"done\".", "prompt": "What's the best answer?", "options": ["The blocks were fake and later deleted", "Ethereum pauses new blocks on weekends", "Validators must also agree to lock blocks in"], "correctIndex": 2, "consequences": ["The blocks were real; agreement just lagged.", "The chain runs all the time, every day.", "Proposing a block and agreeing on it are two separate steps."], "explanation": "Consensus is the agreement step. Without enough votes, blocks wait to become final."}, "proReasoning": "Split a blockchain into making blocks and agreeing on them. Most surprises live in between.", "commonMistake": "Assuming a new block is permanent the instant it appears.", "mentalModel": "A block is a proposal first."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b2793184a844$ml$]::text[]),
($ml$79825f42-6825-5bd1-9cd3-4fbf90627d38$ml$::uuid, $ml$web3$ml$, 1, 2, $ml${"id": "web3-d1-c2", "title": "Why a hash makes history hard to change", "lessonTitle": "How a blockchain works", "slot": 2, "type": "connect", "brief": {"headline": "Each Bitcoin block stores the previous block's hash. Change one old transaction and that block's hash changes, which breaks every block after it.", "kicker": "Connect two day 1 ideas: hashes and consensus.", "fullText": "Day 1 had two ideas that work together. First, every block's header includes the hash of the block before it, a fingerprint of its data. Second, the network agrees on new blocks through consensus: miners spend computing power in proof of work, while validators lock up coins in proof of stake.\n\nPut them together. Editing an old block changes its hash, so every later block no longer points to it. An attacker would have to redo all those blocks and win consensus again, faster than everyone else. That is why the past is hard to rewrite.", "sources": [{"url": "https://glossary.blockstream.com/block", "label": "Blockstream glossary, block"}, {"url": "https://ethereum.org/roadmap/merge", "label": "ethereum.org, The Merge"}, {"url": "https://ethereum.org/staking/", "label": "ethereum.org, staking"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow what happens if someone edits an old block.", "steps": ["They change one old transaction", "That block's hash changes", "The next block no longer points to it", "Every later block must be redone", "The network must agree to the new version"], "explanation": "The hash link makes one edit spread forward. Consensus makes redoing it all very costly."}, "numbers": {"kind": "numberSense", "prompt": "Bitcoin adds a block about every how many minutes?", "min": 0, "max": 60, "value": 10, "explanation": "About every 10 minutes. Each new block adds another layer an attacker would have to redo.", "unit": "min"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a junior analyst asked why blockchain records are hard to tamper with.", "prompt": "What do you say?", "options": ["Edits break the hash links, and redoing them costs a lot", "Records are encrypted, so nobody can ever read them", "A central company checks every record daily"], "correctIndex": 0, "consequences": ["You name both the hash links and the cost of consensus.", "Most blockchain data is public, not secret.", "No single company runs Bitcoin or checks its records."], "explanation": "Hash links spread an edit forward, and consensus makes rewriting them expensive. That is the core answer."}, "proReasoning": "Strong analysts explain tamper resistance with hashes plus consensus. Encryption is a different idea.", "commonMistake": "Saying blockchains are secure because the data is encrypted.", "mentalModel": "Links plus cost."}, "invest": {"call": {"kind": "theCall", "situation": "Two coins claim strong security. One has far less computing power or stake behind it.", "prompt": "What does day 1 say about the weaker one?", "options": ["Its blocks are always larger", "Its history is cheaper to rewrite", "Its hashes are easier to read"], "correctIndex": 1, "consequences": ["Block size has little to do with rewrite cost.", "Less work or stake means redoing blocks costs an attacker less.", "Hashes are public on both; readability is not the issue."], "explanation": "Tamper resistance comes from the cost of redoing blocks. Less security spending means a cheaper attack."}, "proReasoning": "Investors compare what it would cost to rewrite a chain. The hash design is the same; the budget differs.", "commonMistake": "Assuming every blockchain is equally hard to tamper with.", "mentalModel": "Security has a price tag."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants a tamper-evident record of shipping documents.", "prompt": "What gives you that property?", "options": ["Storing records in one secret spreadsheet", "Letting staff edit old records freely", "Linking each record to the hash of the last"], "correctIndex": 2, "consequences": ["One secret file can be changed without anyone noticing.", "Free edits are exactly what you want to detect.", "Any later edit breaks the chain of hashes and shows up."], "explanation": "Hash links make edits visible. Wider agreement on the records makes them hard to undo."}, "proReasoning": "Founders borrow the hash link idea even off-chain. It turns silent edits into visible breaks.", "commonMistake": "Calling a database tamper-proof without any hash links.", "mentalModel": "Chain the records."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why nobody can just quietly edit an old Bitcoin payment.", "prompt": "What's the best answer?", "options": ["It breaks every later block, and the network notices", "Old payments get deleted after about a year", "Bitcoin keeps all its records on one main server"], "correctIndex": 0, "consequences": ["Each block points to the last, so edits break the chain.", "Bitcoin keeps its full history.", "Thousands of computers keep copies."], "explanation": "Changing one block changes its hash, which every later block depends on. Redoing them all is too costly."}, "proReasoning": "Think of each block as sealing the one before it. Breaking one seal breaks them all.", "commonMistake": "Picturing a blockchain as a document anyone can quietly edit.", "mentalModel": "Each block seals the last."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6bffbd3b42b9$ml$]::text[]),
($ml$52699487-c34a-52a5-985b-deca326026f9$ml$::uuid, $ml$web3$ml$, 1, 3, $ml${"id": "web3-d1-c3", "title": "Proof of work or proof of stake for your app?", "lessonTitle": "How a blockchain works", "slot": 3, "type": "decide", "brief": {"headline": "You're choosing a chain for a loyalty points app. Bitcoin secures blocks with computing power; Ethereum has used staked coins as collateral since 2022.", "kicker": "Decide what security model your product needs.", "fullText": "Bitcoin uses proof of work. Miners spend computing power, and blocks arrive about every 10 minutes. Ethereum switched to proof of stake in 2022. Validators lock up ETH as collateral and can lose it for cheating.\n\nBoth let a network agree without a central boss. They differ in what they cost to secure, how fast blocks arrive, and what you can build on them. Your choice should follow what your product actually needs.", "sources": [{"url": "https://glossary.blockstream.com/block", "label": "Blockstream glossary, block"}, {"url": "https://ethereum.org/roadmap/merge", "label": "ethereum.org, The Merge"}, {"url": "https://ethereum.org/staking/", "label": "ethereum.org, staking"}]}, "evidence": {"kind": "sortSignal", "prompt": "Proof of work or proof of stake?", "buckets": ["Proof of work", "Proof of stake"], "items": [{"text": "Miners compete with computing power", "bucket": 0}, {"text": "Bitcoin", "bucket": 0}, {"text": "Validators lock coins as collateral", "bucket": 1}, {"text": "Ethereum since 2022", "bucket": 1}, {"text": "Cheaters can lose their stake", "bucket": 1}], "explanation": "Proof of work spends energy; proof of stake puts capital at risk. Both reach consensus."}, "numbers": {"kind": "numberSense", "prompt": "An Ethereum validator must stake at least how many ETH?", "min": 0, "max": 100, "value": 32, "explanation": "At least 32 ETH. That stake is the collateral proof of stake puts at risk.", "unit": "ETH"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a product team picking a chain. Your lead asks what to compare first.", "prompt": "What do you suggest?", "options": ["Whichever chain friends talk about most", "Speed, cost and security model for our use", "Which chain has the most famous founder"], "correctIndex": 1, "consequences": ["Buzz is not a product requirement.", "Those decide what users pay and how safe records are.", "Fame does not decide whether a product works."], "explanation": "Chains differ in speed, cost and security model. The product needs should drive the pick."}, "proReasoning": "Good product people compare chains on fit, not hype. The use case decides.", "commonMistake": "Picking a chain because it is popular this month.", "mentalModel": "Fit beats fame."}, "invest": {"call": {"kind": "theCall", "situation": "You compare a proof of work coin and a proof of stake coin.", "prompt": "What core difference shapes their economics?", "options": ["One has blocks; the other does not", "One is public; the other is private and hidden", "One spends energy; the other locks up capital"], "correctIndex": 2, "consequences": ["Both build chains of blocks.", "Both are public networks.", "That decides who earns rewards and what security costs."], "explanation": "Proof of work pays miners for energy spent. Proof of stake pays validators for capital at risk."}, "proReasoning": "Investors trace where security spending goes. Energy and staked capital create different costs and rewards.", "commonMistake": "Assuming both models cost the same to run.", "mentalModel": "Follow the security spending."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your loyalty app needs fast, cheap updates many times a day.", "prompt": "Which choice fits best?", "options": ["A chain whose speed and fees match that load", "Bitcoin's base layer, since it is the oldest", "Any chain, since they are all the same"], "correctIndex": 0, "consequences": ["Fees and confirmation time decide whether frequent updates work.", "Ten-minute blocks and fees suit large payments better.", "Chains differ a lot in speed and cost."], "explanation": "Pick the chain for the job. Frequent small updates need low fees and quick confirmation."}, "proReasoning": "Founders match the chain to the load. The oldest chain is not always the right one.", "commonMistake": "Choosing the most secure chain even when users cannot afford its fees.", "mentalModel": "Pick the chain for the job."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how strangers online can agree on one record with no boss.", "prompt": "What's the best answer?", "options": ["Whoever joined first decides everything", "They follow rules that make cheating costly", "A bank secretly approves every block"], "correctIndex": 1, "consequences": ["Rules apply to everyone equally.", "Work or staked coins make lying expensive.", "No bank sits behind Bitcoin or Ethereum."], "explanation": "Consensus rules reward honest blocks and make cheating expensive, through energy or staked coins."}, "proReasoning": "Look for what a cheater would lose. That is what keeps strangers honest.", "commonMistake": "Assuming someone must be in charge for agreement to work.", "mentalModel": "Make cheating costly."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f18eba9d9ecd$ml$]::text[]),
($ml$07ad223e-00af-5e42-bb93-b1b42cb197f6$ml$::uuid, $ml$web3$ml$, 2, 1, $ml${"id": "web3-d2-c1", "title": "The halving block that paid in fees", "lessonTitle": "How blockchains pay their guards", "slot": 1, "type": "apply", "brief": {"headline": "Bitcoin block 840,000, mined on April 20, 2024, paid 37.67 BTC in fees, about $2.4 million, against a new subsidy of just 3.125 BTC.", "kicker": "Apply day 2: when new coins shrink, fees matter more.", "fullText": "Block 840,000 was the 2024 halving block. It cut the subsidy for each new block from 6.25 to 3.125 BTC. ViaBTC mined it, Cointelegraph reported.\n\nThe same day, the Runes protocol launched. Users raced to get their transactions into that exact block, and fees reached 37.67 BTC, just over $2.4 million. With the subsidy, the miner took about 40.7 BTC.\n\nThrough the day 2 lens: a halving cuts the new coins miners earn. Over time, fees users pay must carry more of the cost of security.", "sources": [{"url": "https://cointelegraph.com/news/bitcoin-halving-users-spend-record-millions-block-space-runes-rare-satoshis", "label": "Cointelegraph, users spend record fees on the halving block, Apr 2024"}, {"url": "https://www.benzinga.com/money/what-is-bitcoin-halving", "label": "Benzinga, Bitcoin halving explained"}, {"url": "https://glossary.blockstream.com/block", "label": "Blockstream glossary, block"}]}, "evidence": {"kind": "faceOff", "prompt": "In block 840,000, which paid the miner more?", "left": {"name": "Transaction fees", "note": "37.67 BTC from users"}, "right": {"name": "Block subsidy", "note": "3.125 BTC of new coins"}, "correctIndex": 0, "explanation": "Fees paid about 12 times the subsidy in that one block. Most blocks pay far less in fees."}, "numbers": {"kind": "numberSense", "prompt": "About how many million dollars in fees did block 840,000 collect?", "min": 0, "max": 10, "value": 2.4, "explanation": "Just over $2.4 million, or 37.67 BTC. It was a record for a single block.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a mining company. They ask what the halving block shows about the future.", "prompt": "Which answer lands best?", "options": ["Fees must cover more of security over time", "Miners will soon earn nothing at all", "Halvings make fees disappear for good"], "correctIndex": 0, "consequences": ["Subsidies shrink each halving, so fees carry more weight.", "The subsidy shrinks, but fees and coins still pay miners.", "Fees spiked at the halving, not vanished."], "explanation": "Each halving cuts new coins. Fees have to fill more of the gap to keep miners paid."}, "proReasoning": "Mining people track the fee share of revenue. It is the long-run answer to who pays for security.", "commonMistake": "Saying miners will lose all income after a halving.", "mentalModel": "Fees fill the gap."}, "invest": {"call": {"kind": "theCall", "situation": "A mining stock reports record revenue from one block on halving day.", "prompt": "How should you read it?", "options": ["A sign the subsidy went up", "A one-off spike, not a new normal", "Proof fees will stay that high"], "correctIndex": 1, "consequences": ["The subsidy was cut in half that day.", "A launch-day rush filled that block; most pay far less.", "One rushed block does not set a trend."], "explanation": "Fees spiked from a launch rush. Steady revenue depends on everyday fees plus a shrinking subsidy."}, "proReasoning": "Investors separate one-time spikes from run rates. Halving day was a spike.", "commonMistake": "Extrapolating a record block into a yearly forecast.", "mentalModel": "One block is not a trend."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app sends many small Bitcoin payments. Halving day fees jumped to record highs.", "prompt": "What do you plan for?", "options": ["Fees always staying close to zero", "Halvings making fees cheaper", "Fee spikes, with a way to wait or batch"], "correctIndex": 2, "consequences": ["Block space has a price that can jump fast.", "A halving did not lower fees; demand raised them.", "Batching or waiting avoids paying peak prices."], "explanation": "Users pay fees to get into blocks. When demand spikes, small payments get squeezed."}, "proReasoning": "Founders design for fee spikes. Batching and patience keep small payments workable.", "commonMistake": "Assuming block space will always be cheap.", "mentalModel": "Plan for the spike."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why someone paid millions in fees for one block.", "prompt": "What's the best answer?", "options": ["Many wanted into that historic block at once", "Fees are fixed at that price forever", "The miner charged a special halving tax"], "correctIndex": 0, "consequences": ["Fees are an auction, and demand for that block was huge.", "Fees rise and fall with demand.", "No tax exists; users bid for space."], "explanation": "Block space is limited. When many people want the same block, they bid fees up."}, "proReasoning": "Think of block space as seats at a sold-out show. Prices climb with the crowd.", "commonMistake": "Thinking fees are a fixed charge set by someone.", "mentalModel": "Fees are an auction."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d258506c0395$ml$]::text[]),
($ml$f2757a08-6a0f-588b-bffc-4f0be3be545b$ml$::uuid, $ml$web3$ml$, 2, 2, $ml${"id": "web3-d2-c2", "title": "Who pays the guards on two chains", "lessonTitle": "How blockchains pay their guards", "slot": 2, "type": "connect", "brief": {"headline": "Bitcoin pays miners 3.125 BTC of new coins per block since 2024. Ethereum pays validators who stake at least 32 ETH for proposing and checking blocks.", "kicker": "Connect day 1 and day 2: the security model sets the paycheck.", "fullText": "Day 1 showed two ways to secure a chain: proof of work and proof of stake. Day 2 showed how each one pays.\n\nBitcoin's miners earn a block subsidy, 3.125 BTC since the April 2024 halving, plus fees. The subsidy halves every 210,000 blocks, and supply is capped at 21 million. Ethereum's validators stake at least 32 ETH and earn rewards for honest work. Both pay for security with coins, on rules written in code.", "sources": [{"url": "https://glossary.blockstream.com/block", "label": "Blockstream glossary, block"}, {"url": "https://www.benzinga.com/money/what-is-bitcoin-halving", "label": "Benzinga, Bitcoin halving explained"}, {"url": "https://ethereum.org/staking/", "label": "ethereum.org, staking"}, {"url": "https://ethereum.org/roadmap/merge", "label": "ethereum.org, The Merge"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What must an Ethereum validator lock up to start?", "options": ["At least 32 ETH", "At least 3.125 BTC", "A mining rig"], "correctIndex": 0, "explanation": "At least 32 ETH. The stake is collateral that can be cut for cheating."}, "numbers": {"kind": "numberSense", "prompt": "A Bitcoin halving happens every how many thousand blocks?", "min": 0, "max": 500, "value": 210, "explanation": "Every 210,000 blocks, slightly less than four years.", "unit": "K"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a research team. Your manager asks how two chains fund security.", "prompt": "What is the clearest answer?", "options": ["Government grants paid to node operators", "New coins and fees, paid to miners or stakers", "Ads shown inside crypto wallets"], "correctIndex": 1, "consequences": ["No government funds Bitcoin or Ethereum security.", "Both chains pay security with coins under code rules.", "Wallet ads do not pay for network security."], "explanation": "Miners and validators earn new coins plus fees. The rules for each are written into the protocol."}, "proReasoning": "Researchers start with how security is paid. It explains a chain's costs and incentives.", "commonMistake": "Describing security as free because nobody sends a bill.", "mentalModel": "Security has a paycheck."}, "invest": {"call": {"kind": "theCall", "situation": "You compare issuance on Bitcoin and Ethereum.", "prompt": "What makes Bitcoin's new supply predictable?", "options": ["A committee that votes on it each new year", "Demand from new buyers each and every day", "A fixed schedule that halves every 210,000 blocks"], "correctIndex": 2, "consequences": ["No committee sets Bitcoin issuance.", "Demand affects price, not the issuance schedule.", "The schedule is in code and anyone can check it."], "explanation": "Bitcoin's subsidy halves on a fixed block schedule toward a 21 million cap."}, "proReasoning": "Investors like rules they can verify. Bitcoin's issuance is written in code.", "commonMistake": "Assuming crypto supply changes whenever someone decides.", "mentalModel": "Read the schedule in code."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants to run Ethereum validators for customers.", "prompt": "What is the core cost you take on?", "options": ["Locking 32 ETH per validator as collateral", "Buying racks of power-hungry mining machines", "Paying a license to Ethereum"], "correctIndex": 0, "consequences": ["Stake is the capital at risk in proof of stake.", "Mining rigs belong to proof of work.", "Ethereum charges no license fee."], "explanation": "Proof of stake swaps hardware costs for capital at risk. Each validator needs at least 32 ETH staked."}, "proReasoning": "Founders in staking plan around capital, not machines. The stake is the business.", "commonMistake": "Budgeting for mining hardware on a proof of stake chain.", "mentalModel": "Stake is the cost."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks who pays the people who keep Bitcoin running.", "prompt": "What's the best answer?", "options": ["Banks that hold bitcoin for clients", "The network, with new coins and user fees", "A company that owns Bitcoin"], "correctIndex": 1, "consequences": ["Banks do not pay miners.", "Miners earn the subsidy and fees for each block.", "No company owns Bitcoin."], "explanation": "Each block pays its miner new coins plus fees. The code sets the subsidy."}, "proReasoning": "Picture the network printing its own paychecks, on a shrinking schedule.", "commonMistake": "Thinking someone sends miners a salary.", "mentalModel": "The network pays its guards."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:95cd2ea48052$ml$]::text[]),
($ml$7b948f67-5348-5c64-ba8a-f726d5554da3$ml$::uuid, $ml$web3$ml$, 2, 3, $ml${"id": "web3-d2-c3", "title": "Planning a miner past the next halving", "lessonTitle": "How blockchains pay their guards", "slot": 3, "type": "decide", "brief": {"headline": "You run a small mining firm. The 2024 halving cut the subsidy to 3.125 BTC per block, and the next halving cuts it again in about four years.", "kicker": "Decide how a miner survives each halving.", "fullText": "Bitcoin's block subsidy halves every 210,000 blocks, slightly less than four years. In April 2024 it fell from 6.25 to 3.125 BTC. Supply is capped at 21 million, so new coins keep slowing.\n\nThat means the same work earns half as many new coins after each halving. Miners rely more and more on fees users pay. You have to plan for income that drops on a known date.", "sources": [{"url": "https://www.benzinga.com/money/what-is-bitcoin-halving", "label": "Benzinga, Bitcoin halving explained"}, {"url": "https://glossary.blockstream.com/block", "label": "Blockstream glossary, block"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the halving squeeze in order.", "steps": ["The subsidy halves on schedule", "Each block pays fewer new coins", "Miners earn less for the same work", "Weaker miners shut down or upgrade", "Fees carry more of miner income"], "explanation": "The cut is known in advance. Miners who plan for it survive the squeeze."}, "numbers": {"kind": "numberSense", "prompt": "After the next halving, what share of today's 3.125 BTC subsidy will remain?", "min": 0, "max": 80, "value": 50, "explanation": "Half, or 1.5625 BTC per block. The schedule keeps halving toward the 21 million cap.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a new analyst at a mining firm. Your boss asks what to model for the next halving.", "prompt": "What do you model first?", "options": ["Revenue staying flat after the halving", "A higher subsidy to reward loyalty", "Revenue at half the subsidy, with fees"], "correctIndex": 2, "consequences": ["The subsidy halves, so flat revenue is wrong.", "The code never raises the subsidy.", "The cut is certain; plan for it before it lands."], "explanation": "The halving date and size are known. Modeling half the subsidy keeps the plan honest."}, "proReasoning": "Analysts plan around fixed events. A halving is a cut you can see years ahead.", "commonMistake": "Treating the halving as a surprise.", "mentalModel": "Model the known cut."}, "invest": {"call": {"kind": "theCall", "situation": "You compare two miners before a halving. One has far cheaper power.", "prompt": "Which is better placed?", "options": ["The one with cheaper power", "The one with the bigger logo", "Both, since the cut hits evenly"], "correctIndex": 0, "consequences": ["Lower costs keep a miner profitable after income halves.", "Brand does not pay the power bill.", "The cut is even, but costs are not."], "explanation": "After a halving, the gap between revenue and costs shrinks. Low-cost miners keep a margin."}, "proReasoning": "Investors rank miners by cost per coin. The halving tests that cost.", "commonMistake": "Assuming every miner suffers equally from a halving.", "mentalModel": "Costs decide survival."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your mining startup must cut costs before the next halving.", "prompt": "What is the best first move?", "options": ["Pause planning until fees rise", "Lock in cheaper power and efficient machines", "Buy more old machines while they are cheap"], "correctIndex": 1, "consequences": ["Waiting on fees is hope, not a plan.", "Cheaper power and better machines lift margin per coin.", "Old machines burn more power per unit of work."], "explanation": "With income falling on a known date, cost per coin decides who stays profitable."}, "proReasoning": "Founders in mining fight for cheaper power. It is the one cost they control.", "commonMistake": "Expanding with inefficient machines right before a halving.", "mentalModel": "Cut the cost per coin."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Bitcoin keeps cutting the pay for its miners.", "prompt": "What's the best answer?", "options": ["Because miners asked to be paid less money", "To punish miners who joined late", "To slow new supply toward a 21 million cap"], "correctIndex": 2, "consequences": ["Miners would rather earn more.", "The rule applies to everyone equally.", "Halvings keep new coins arriving more slowly."], "explanation": "Halvings slow issuance so total supply approaches 21 million. Fees are meant to take over."}, "proReasoning": "See the halving as a dimmer switch on new supply. It turns down every four years.", "commonMistake": "Thinking halvings are a penalty on miners.", "mentalModel": "A dimmer on new supply."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1cfbeea4eaf7$ml$]::text[]),
($ml$4bf302f0-18b3-5954-a7c7-9f5aa25d412b$ml$::uuid, $ml$web3$ml$, 3, 1, $ml${"id": "web3-d3-c1", "title": "A pool claims half of Monero", "lessonTitle": "Who holds the power on a blockchain", "slot": 1, "type": "apply", "brief": {"headline": "In August 2025, Qubic's founder said its mining pool had passed half of Monero's hashrate. Researchers pointed to a six-block reorganization.", "kicker": "Apply day 3: power sits with whoever controls blocks.", "fullText": "Monero is a proof of work coin. Qubic, a separate project, paid its users to mine Monero. Its share of Monero's hashrate rose from under 2% in mid-May to above 25% by late July, The Block reported.\n\nIn August, founder Sergey Ivancheglo said Qubic had achieved 51%. Analysts described a six-block-deep reorganization, where recent blocks were replaced. Some disputed whether Qubic truly held a majority of all hashrate.\n\nThrough the day 3 lens: whoever controls most block production can rewrite recent history.", "sources": [{"url": "https://www.theblock.co/post/366535/monero-faces-chain-reorganization-fears-after-qubic-says-it-controls-51-of-hashrate", "label": "The Block, Monero reorg fears after Qubic claims 51%, Aug 2025"}, {"url": "https://www.coindesk.com/de/learn/what-is-a-51-attack", "label": "CoinDesk, what is a 51% attack"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the Qubic episode. Tap it.", "statements": ["Qubic's share rose from under 2% to above 25%.", "Analysts described a six-block reorganization.", "Monero runs on proof of stake."], "fakeIndex": 2, "explanation": "Monero uses proof of work. That is why a pool with enough hashrate could replace recent blocks."}, "numbers": {"kind": "numberSense", "prompt": "How many blocks deep was the reorganization analysts described?", "min": 0, "max": 20, "value": 6, "explanation": "Six blocks. Deeper reorganizations can reverse payments that looked confirmed.", "unit": "blocks"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an exchange. They ask how you would react to news like Qubic's.", "prompt": "Which answer lands best?", "options": ["Delist every proof of work coin today", "Require more confirmations on Monero deposits", "Ignore it, since reorganizations cannot happen"], "correctIndex": 1, "consequences": ["One event does not justify dropping every coin.", "More blocks to wait means a reorg is less likely to reverse a deposit.", "A six-block reorg was reported."], "explanation": "A majority pool can replace recent blocks. Waiting for more confirmations limits the damage."}, "proReasoning": "Risk teams raise confirmation counts when block production concentrates. It is a quick, real defense.", "commonMistake": "Treating a confirmed deposit as final no matter who controls the chain.", "mentalModel": "Wait longer when power concentrates."}, "invest": {"call": {"kind": "theCall", "situation": "You hold a small proof of work coin. One pool now claims most of its hashrate.", "prompt": "What risk matters most?", "options": ["The coin will mine faster for everyone", "Fees will drop to zero", "That pool can reverse recent payments"], "correctIndex": 2, "consequences": ["Speed is set by difficulty, not by one pool.", "Fees are not the issue here.", "Control of blocks is control of recent history."], "explanation": "Concentrated hashrate makes double spends possible. Security depends on that pool behaving."}, "proReasoning": "Investors watch who produces blocks. Concentration is a hidden risk until it is not.", "commonMistake": "Assuming a coin is safe just because it uses proof of work.", "mentalModel": "Concentration is risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app accepts a small proof of work coin for payments.", "prompt": "How do you protect yourself?", "options": ["Wait for more blocks on large payments", "Accept every payment instantly", "Ask the pool to promise good behavior"], "correctIndex": 0, "consequences": ["More blocks make reversing a payment harder.", "Instant credit is easy to double spend.", "A promise does not stop a reorg."], "explanation": "When one pool controls most blocks, recent payments can be undone. More confirmations reduce that risk."}, "proReasoning": "Builders carry block producers' risk. Confirmation rules are their main shield.", "commonMistake": "Crediting large payments after one block on a concentrated chain.", "mentalModel": "Wait for depth."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how one group could \"take over\" a cryptocurrency.", "prompt": "What's the best answer?", "options": ["By hacking every user's phone", "By controlling most of the block making", "By buying the company that owns it"], "correctIndex": 1, "consequences": ["The attack targets block making, not phones.", "Most hashrate lets you replace recent blocks.", "No company owns Monero."], "explanation": "On proof of work chains, power follows hashrate. A majority can rewrite recent blocks."}, "proReasoning": "Ask who makes the blocks. That is where the power is.", "commonMistake": "Thinking a blockchain can be bought like a company.", "mentalModel": "Power follows block making."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e255cfe6d6cd$ml$]::text[]),
($ml$aea84133-748a-5941-84cc-c65432fa6556$ml$::uuid, $ml$web3$ml$, 3, 2, $ml${"id": "web3-d3-c2", "title": "Two pools, most of Bitcoin", "lessonTitle": "Who holds the power on a blockchain", "slot": 2, "type": "connect", "brief": {"headline": "In April 2025, Foundry held about 30% of Bitcoin's hashrate by block tags. Six pools mined more than 95% of blocks.", "kicker": "Connect day 2 and day 3: steady pay pulls miners into pools.", "fullText": "Day 2 showed that miners earn new coins and fees per block. Most miners cannot find a block on their own often enough to pay the bills. So they join pools, which share rewards by contribution and smooth out income.\n\nDay 3 showed the result. An April 2025 analysis by researcher b10c found that six pools mine more than 95% of Bitcoin blocks. Foundry had about 30% and AntPool about 19%. Steady pay is the reason power concentrates.", "sources": [{"url": "https://b10c.me/blog/015-bitcoin-mining-centralization/", "label": "b10c, Bitcoin mining centralization in 2025"}, {"url": "https://bitcointreasuries.net/glossary/mining-pool", "label": "BitcoinTreasuries, mining pool"}, {"url": "https://glossary.blockstream.com/block", "label": "Blockstream glossary, block"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how pay pulls miners into pools.", "steps": ["A small miner rarely finds a block alone", "Income swings from month to month", "The miner joins a pool for steady pay", "Pools grow as more miners join", "A few pools produce most blocks"], "explanation": "Steady payouts are good for miners. Concentration is the side effect."}, "numbers": {"kind": "numberSense", "prompt": "About what share of Bitcoin's hashrate did Foundry hold in April 2025?", "min": 0, "max": 100, "value": 30, "explanation": "About 30%. Six pools together mined more than 95% of blocks.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a mining firm deciding between solo mining and a pool.", "prompt": "What do you recommend?", "options": ["Solo mining, since pools never pay", "Whichever pool is largest, with no other questions", "A pool, for steady income, while tracking its share"], "correctIndex": 2, "consequences": ["Pools pay by contribution.", "The biggest pool adds to concentration.", "Pools smooth pay; watching share keeps risk in view."], "explanation": "Pools reduce income swings. Choosing among them also shapes how concentrated the network becomes."}, "proReasoning": "Mining professionals weigh steady pay against concentration. Both matter for the network.", "commonMistake": "Ignoring which pool you join because they all pay the same.", "mentalModel": "Steady pay, watch the share."}, "invest": {"call": {"kind": "theCall", "situation": "You read that six pools mine over 95% of Bitcoin blocks.", "prompt": "What does it tell you about risk?", "options": ["Security leans on a few pools behaving well", "Bitcoin is secretly run by one company", "Mining is now proof of stake"], "correctIndex": 0, "consequences": ["A few operators decide which transactions get in.", "Pools are many firms, not one owner.", "Bitcoin still uses proof of work."], "explanation": "Concentrated block production is a dependency. The network relies on those pools."}, "proReasoning": "Investors look past decentralization claims to who actually builds blocks.", "commonMistake": "Assuming thousands of miners means thousands of independent decision makers.", "mentalModel": "Count the pools, not the miners."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app depends on Bitcoin transactions getting into blocks fast.", "prompt": "What risk should you note?", "options": ["Every miner includes every transaction", "A few pools choose which transactions get in", "Transactions are added in random order"], "correctIndex": 1, "consequences": ["Miners choose what to include.", "Pools set their own inclusion policies.", "Pools pick transactions, often by fee."], "explanation": "When a few pools build most blocks, their choices shape what reaches the chain."}, "proReasoning": "Builders carry block producers' risk. Know who builds the blocks your users need.", "commonMistake": "Assuming the network will always include your transactions.", "mentalModel": "Know who builds blocks."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Bitcoin miners team up in pools.", "prompt": "What's the best answer?", "options": ["Because the law requires it", "To mine special coins nobody else can", "For steadier pay, shared by contribution"], "correctIndex": 2, "consequences": ["No law forces miners into pools.", "Pools mine the same bitcoin as everyone.", "Pooling smooths out lucky and unlucky months."], "explanation": "A single miner might wait months for a block. A pool pays a little, often."}, "proReasoning": "Pools are like a lottery syndicate. Shared tickets, steadier winnings.", "commonMistake": "Thinking pools are a separate kind of bitcoin.", "mentalModel": "Share the luck."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4eab0a2001a3$ml$]::text[]),
($ml$a13d5f05-eba0-599f-889b-156c0f75ba08$ml$::uuid, $ml$web3$ml$, 3, 3, $ml${"id": "web3-d3-c3", "title": "How long to wait on a big deposit", "lessonTitle": "Who holds the power on a blockchain", "slot": 3, "type": "decide", "brief": {"headline": "You run deposits for a small exchange. Control of over half the hashing power lets an attacker rewrite recent blocks and double-spend.", "kicker": "Decide how many blocks a large deposit needs.", "fullText": "A 51% attack lets whoever controls most of a network's hashing power rewrite recent blocks. A customer could deposit coins, trade them, and then erase the deposit with a longer secret chain.\n\nThe defense is depth. Each new block on top of a deposit makes rewriting it harder and more expensive. Large deposits on chains with concentrated or cheap hashrate need more blocks before you credit them.", "sources": [{"url": "https://www.coindesk.com/de/learn/what-is-a-51-attack", "label": "CoinDesk, what is a 51% attack"}, {"url": "https://b10c.me/blog/015-bitcoin-mining-centralization/", "label": "b10c, Bitcoin mining centralization in 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Raise or keep the confirmations you require?", "buckets": ["Raise", "Keep"], "items": [{"text": "One pool nears half the hashrate", "bucket": 0}, {"text": "The deposit is unusually large", "bucket": 0}, {"text": "The coin has little hashrate behind it", "bucket": 0}, {"text": "A small deposit on Bitcoin", "bucket": 1}, {"text": "Pool shares look spread out", "bucket": 1}], "explanation": "Concentration, size and weak security all argue for more depth."}, "numbers": {"kind": "numberSense", "prompt": "An attacker needs control of more than what share of hashing power?", "min": 0, "max": 80, "value": 51, "explanation": "More than half, often called 51%. Then they can outpace everyone else.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're new on an exchange risk team. A large deposit arrives on a weakly secured coin.", "prompt": "What do you propose?", "options": ["Hold it until many more blocks confirm it", "Credit it now to keep the customer happy", "Reject all deposits of that coin forever"], "correctIndex": 0, "consequences": ["Depth makes a rewrite costly and rare.", "Instant credit invites a double spend.", "A blanket ban goes further than the risk needs."], "explanation": "More blocks on top of a deposit raise the cost of reversing it. Size the wait to the risk."}, "proReasoning": "Risk teams scale confirmations to amount and chain security. It is a calm, standard control.", "commonMistake": "Using the same confirmation rule for every coin and amount.", "mentalModel": "Size the wait to the risk."}, "invest": {"call": {"kind": "theCall", "situation": "An exchange you invest in credits large deposits after one block on small coins.", "prompt": "What does that tell you?", "options": ["It cannot lose money on deposits", "It carries real double-spend risk", "It has the best customer service"], "correctIndex": 1, "consequences": ["Reversed deposits can cost real money.", "One block on a weak chain is easy to rewrite.", "Speed is nice; losses are not."], "explanation": "Shallow confirmation on weak chains is a known attack path. It is a risk to the business."}, "proReasoning": "Investors read confirmation policy as a risk signal. Too generous is too exposed.", "commonMistake": "Praising instant deposits without asking what they cost in risk.", "mentalModel": "Fast credit, real risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build a checkout that accepts several coins.", "prompt": "How do you set confirmations?", "options": ["One block for every coin and amount", "No waiting, since refunds fix everything", "Per coin and amount, stricter on weak chains"], "correctIndex": 2, "consequences": ["Weak chains need more than one block.", "A double spend leaves nothing to refund.", "Matching depth to risk keeps fraud costly."], "explanation": "Different chains have different security. Confirmation rules should reflect that."}, "proReasoning": "Founders set confirmation rules per chain. It is cheap insurance.", "commonMistake": "Treating every chain as equally hard to rewrite.", "mentalModel": "Depth per chain."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why exchanges make you wait before using deposited crypto.", "prompt": "What's the best answer?", "options": ["Extra blocks make the deposit hard to undo", "Exchanges want to earn interest on it", "The coins travel slowly across the internet"], "correctIndex": 0, "consequences": ["Each block on top locks the deposit in further.", "The wait is about safety, not interest.", "The data moves fast; agreement takes blocks."], "explanation": "A deposit could be erased by rewriting recent blocks. Waiting for more blocks makes that very costly."}, "proReasoning": "Think of each new block as another lock on the door.", "commonMistake": "Thinking the delay is the exchange being slow on purpose.", "mentalModel": "Each block adds a lock."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:fe62febb8d2e$ml$]::text[]),
($ml$0918d27b-192f-53ce-b458-fc82958fe9dc$ml$::uuid, $ml$web3$ml$, 4, 1, $ml${"id": "web3-d4-c1", "title": "Twenty million down, one million to go", "lessonTitle": "The numbers that measure a blockchain", "slot": 1, "type": "apply", "brief": {"headline": "By March 2026, Bitcoin's mined supply passed 20 million coins at block 939,999. The final million will take about 114 years.", "kicker": "Apply day 4: the rules are numbers anyone can check.", "fullText": "Bitcoin's code caps supply at 21 million. In March 2026, The Block reported that mined supply passed 20 million, more than 95.2% of the cap, about 17 years after the genesis block in January 2009.\n\nThe last million will arrive far more slowly. Halvings keep cutting the subsidy, so mining the remaining coins should take roughly 114 years, with the final fractions around 2140.\n\nThrough the day 4 lens: you can work this out yourself from block times and the subsidy schedule.", "sources": [{"url": "https://www.theblock.co/news/ecosystems/2026-03-09-bitcoin-mined-supply-hits-20-million-btc-392660", "label": "The Block, Bitcoin's mined supply hits 20 million, Mar 2026"}, {"url": "https://www.benzinga.com/money/what-is-bitcoin-halving", "label": "Benzinga, Bitcoin halving explained"}, {"url": "https://glossary.blockstream.com/block", "label": "Blockstream glossary, block"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why will the last million bitcoin take so long to mine?", "options": ["Halvings keep shrinking new supply", "Miners are leaving the network", "The cap was raised in 2026"], "correctIndex": 0, "explanation": "Each halving cuts new coins in half. The last million arrives slower and slower."}, "numbers": {"kind": "numberSense", "prompt": "About how many years should the final million bitcoin take to mine?", "min": 0, "max": 200, "value": 114, "explanation": "About 114 years, with the last fractions around 2140.", "unit": "yrs"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a crypto research firm. They ask you to explain the 20 million milestone.", "prompt": "Which answer lands best?", "options": ["Bitcoin will completely run out of coins next year", "The cap moves up when demand rises", "95% is mined; halvings stretch the rest to about 2140"], "correctIndex": 2, "consequences": ["Halvings slow issuance for over a century.", "The 21 million cap is fixed in code.", "You tie the milestone to the halving schedule."], "explanation": "Most coins exist already. The schedule stretches the remainder over about 114 years."}, "proReasoning": "Researchers derive milestones from the rules. Showing the math beats repeating headlines.", "commonMistake": "Saying bitcoin is about to run out of new coins.", "mentalModel": "Derive it from the schedule."}, "invest": {"call": {"kind": "theCall", "situation": "You read that over 95% of all bitcoin has now been mined.", "prompt": "What does that mean for new supply?", "options": ["Only a small, shrinking flow of new coins remains", "New supply just doubled", "Holders must sell coins to make any new ones"], "correctIndex": 0, "consequences": ["New coins are now a small trickle that keeps halving.", "Supply growth is slowing, not rising.", "New coins come from mining, not holders."], "explanation": "With most coins mined, issuance is a small and falling share of supply."}, "proReasoning": "Investors track issuance as new supply. It is now a trickle, on a known schedule.", "commonMistake": "Treating the milestone as news that changes the supply rules.", "mentalModel": "Issuance is a trickle."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells a dashboard of on-chain numbers.", "prompt": "Which feature fits the 20 million milestone best?", "options": ["Price predictions for the year 2140", "Live supply versus the 21 million cap", "A guess at who Satoshi is"], "correctIndex": 1, "consequences": ["Forecasts that far out are not verifiable.", "Anyone can verify supply from the chain, so it builds trust.", "Guesses are not data."], "explanation": "On a blockchain, the rules are numbers anyone can check. Show them clearly."}, "proReasoning": "Founders win trust by showing verifiable numbers. Supply against the cap is one.", "commonMistake": "Filling a data product with predictions instead of checkable facts.", "mentalModel": "Show what anyone can check."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if Bitcoin is \"almost finished\" now that 20 million are mined.", "prompt": "What's the best answer?", "options": ["Yes, all mining stops for good next month", "No, the cap keeps rising", "New coins keep coming slowly until about 2140"], "correctIndex": 2, "consequences": ["Mining continues, with fees and a small subsidy.", "The cap stays at 21 million.", "The last million is spread over about 114 years."], "explanation": "Halvings stretch the final million over a century. Mining and fees continue."}, "proReasoning": "Picture a tap that halves its flow every four years. It never quite shuts.", "commonMistake": "Thinking the network ends when the last coin is close.", "mentalModel": "The tap slows, it does not stop."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a5a4720c85db$ml$]::text[]),
($ml$e9a8c3b7-2a6d-5c0c-9a68-52ca2978bdeb$ml$::uuid, $ml$web3$ml$, 4, 2, $ml${"id": "web3-d4-c2", "title": "Doing the daily math on bitcoin", "lessonTitle": "The numbers that measure a blockchain", "slot": 2, "type": "connect", "brief": {"headline": "Blocks arrive about every 10 minutes and pay 3.125 BTC since April 2024. That is about 144 blocks and 450 new bitcoin a day.", "kicker": "Connect day 2 and day 4: pay per block becomes daily supply.", "fullText": "Day 2 showed the subsidy: 3.125 BTC per block since the 2024 halving. Day 4 turned that into daily numbers.\n\nBitcoin adjusts difficulty to keep blocks about 10 minutes apart. That makes about 144 blocks a day. At 3.125 BTC each, the network creates about 450 new bitcoin a day. After the next halving, that drops to about 225.", "sources": [{"url": "https://glossary.blockstream.com/block", "label": "Blockstream glossary, block"}, {"url": "https://www.benzinga.com/money/what-is-bitcoin-halving", "label": "Benzinga, Bitcoin halving explained"}]}, "evidence": {"kind": "buildChain", "prompt": "Build the daily issuance number.", "steps": ["A block every 10 minutes", "Six blocks an hour", "About 144 blocks a day", "3.125 BTC per block", "About 450 new bitcoin a day"], "explanation": "Simple multiplication from the rules gives the daily supply."}, "numbers": {"kind": "numberSense", "prompt": "About how many new bitcoin are created per day after the 2024 halving?", "min": 0, "max": 1000, "value": 450, "explanation": "About 450: 144 blocks a day times 3.125 BTC.", "unit": "BTC"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks how many new bitcoin enter the market each day.", "prompt": "What do you answer?", "options": ["About 450: 144 blocks times 3.125 BTC", "About 10,000, set by the miners", "It changes randomly every hour"], "correctIndex": 0, "consequences": ["You show the derivation, not just the number.", "Miners do not set issuance.", "The schedule is fixed by code."], "explanation": "Deriving 450 from block time and subsidy shows real understanding of the rules."}, "proReasoning": "Interviewers remember candidates who show the math. It proves you understand the system.", "commonMistake": "Quoting a number you cannot derive.", "mentalModel": "Show the math."}, "invest": {"call": {"kind": "theCall", "situation": "A fund manager says new supply puts pressure on bitcoin's price.", "prompt": "What number frames that claim?", "options": ["Zero new coins since 2024", "About 450 new coins a day, falling over time", "Unlimited new coins, whenever they are needed"], "correctIndex": 1, "consequences": ["Issuance continues at a smaller rate.", "That is the daily flow buyers must absorb.", "Supply is capped and scheduled."], "explanation": "New supply is a known daily flow. It halves roughly every four years."}, "proReasoning": "Investors size new supply before blaming it. About 450 a day is the number.", "commonMistake": "Talking about supply pressure without knowing the flow.", "mentalModel": "Size the flow first."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your mining startup projects how many bitcoin the network pays out daily.", "prompt": "What figure do you start from?", "options": ["About 900 BTC a day, from 2020", "Whatever the price chart suggests", "About 450 BTC a day, plus fees"], "correctIndex": 2, "consequences": ["900 was the rate before 2024.", "Price does not change issuance.", "That is the current subsidy flow across all miners."], "explanation": "Current issuance is about 450 BTC a day. Your share depends on your hashrate."}, "proReasoning": "Founders start from the network total, then size their slice by hashrate.", "commonMistake": "Using a pre-halving figure in a new plan.", "mentalModel": "Start from the network total."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how anyone knows how many bitcoin exist.", "prompt": "What's the best answer?", "options": ["The rules are public, so anyone can count", "A company publishes the number yearly", "Nobody knows; it is secret"], "correctIndex": 0, "consequences": ["Block times and subsidies are in open code.", "No company controls the count.", "The ledger is public."], "explanation": "Anyone can run the math or check the chain. That openness is the point."}, "proReasoning": "On a blockchain, you can check the numbers yourself.", "commonMistake": "Assuming crypto supply is hidden like a company secret.", "mentalModel": "Anyone can count."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:76ec67c55be2$ml$]::text[]),
($ml$01bf19bf-db6e-5b82-b7fe-c6626dc281ec$ml$::uuid, $ml$web3$ml$, 4, 3, $ml${"id": "web3-d4-c3", "title": "Answering the energy question", "lessonTitle": "The numbers that measure a blockchain", "slot": 3, "type": "decide", "brief": {"headline": "You pitch a blockchain product to a large company worried about energy. Ethereum's 2022 switch to proof of stake cut its energy use by about 99.95%.", "kicker": "Decide how to answer an energy objection honestly.", "fullText": "Proof of work spends energy to secure blocks. Proof of stake secures them with staked coins instead. When Ethereum switched in 2022, ethereum.org says its energy use fell by about 99.95%.\n\nBitcoin still uses proof of work, with blocks about every 10 minutes. A buyer's energy worries depend on which chain you mean. The honest answer names the chain and its model.", "sources": [{"url": "https://ethereum.org/roadmap/merge", "label": "ethereum.org, The Merge"}, {"url": "https://glossary.blockstream.com/block", "label": "Blockstream glossary, block"}]}, "evidence": {"kind": "faceOff", "prompt": "Which chain uses far less energy today?", "left": {"name": "Ethereum", "note": "Proof of stake since 2022"}, "right": {"name": "Bitcoin", "note": "Proof of work"}, "correctIndex": 0, "explanation": "Ethereum cut energy use by about 99.95% when it moved to proof of stake."}, "numbers": {"kind": "numberSense", "prompt": "Ethereum's energy use fell by more than what percent after the Merge?", "min": 0, "max": 100, "value": 99, "explanation": "More than 99%: about 99.95%. Staked coins replaced energy-hungry mining.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A client tells your consulting team that \"blockchains waste energy\".", "prompt": "How do you respond?", "options": ["Say energy use is not a real question", "It depends on the chain and its security model", "Agree that every blockchain wastes energy"], "correctIndex": 1, "consequences": ["The question is fair; answer it with facts.", "Proof of stake chains use a tiny fraction of the energy.", "That ignores the 2022 switch on Ethereum."], "explanation": "Energy use depends on proof of work or proof of stake. Ethereum cut about 99.95% in 2022."}, "proReasoning": "Consultants answer objections with specifics. Name the chain and the model.", "commonMistake": "Defending or condemning all blockchains with one sentence.", "mentalModel": "Name the chain."}, "invest": {"call": {"kind": "theCall", "situation": "A fund only invests in low-energy technology. You look at crypto.", "prompt": "What distinction matters most?", "options": ["Old coins versus new coins", "Big chains versus small chains", "Proof of stake versus proof of work"], "correctIndex": 2, "consequences": ["Age says little about energy use.", "Size alone does not decide energy use.", "The model drives energy use far more than age or size."], "explanation": "Proof of stake uses a small fraction of the energy of proof of work."}, "proReasoning": "Investors with mandates screen by consensus model. It is the key energy driver.", "commonMistake": "Treating all crypto as one energy profile.", "mentalModel": "Screen by model."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your enterprise buyer worries about energy. Your product runs on a proof of stake chain.", "prompt": "What do you lead with?", "options": ["The chain's model and its measured energy cut", "A promise that energy is simply not an issue", "Changing the subject to price"], "correctIndex": 0, "consequences": ["Specific, sourced numbers answer the worry directly.", "Brushing it off loses trust.", "Dodging makes the worry bigger."], "explanation": "Buyers want facts. A proof of stake chain can point to a measured drop in energy use."}, "proReasoning": "Founders turn objections into proof points with sourced numbers.", "commonMistake": "Dismissing a buyer's concern instead of answering it.", "mentalModel": "Answer with the number."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says all crypto uses as much energy as a country.", "prompt": "What's the best answer?", "options": ["No coin uses any energy at all, ever", "Proof of work does; proof of stake uses little", "Yes, every coin uses that much"], "correctIndex": 1, "consequences": ["Every network uses some energy.", "The two models are very different in energy use.", "Ethereum cut its use by about 99.95%."], "explanation": "Proof of work spends energy on purpose. Proof of stake replaced that with staked coins."}, "proReasoning": "Ask which model a coin uses before judging its energy.", "commonMistake": "Lumping every cryptocurrency into one energy story.", "mentalModel": "Ask which model."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8833527e0bc6$ml$]::text[]),
($ml$8a3b3ab7-d592-54c8-b9b3-7957667798dc$ml$::uuid, $ml$web3$ml$, 5, 1, $ml${"id": "web3-d5-c1", "title": "Four signatures, $230 million gone", "lessonTitle": "The risk every crypto holder carries", "slot": 1, "type": "apply", "brief": {"headline": "In July 2024, attackers drained about $230 million from a WazirX multisig wallet. It needed four of six keys to move funds.", "kicker": "Apply day 5: control of the keys is control of the money.", "fullText": "WazirX, an Indian exchange, kept funds in a multisig wallet with six signing keys: five held by WazirX and one by its custody partner, Liminal. Moving money took four signatures, three from WazirX and one from Liminal.\n\nOn July 18, 2024, attackers changed the wallet's controlling contract and drained it. Analyst Mudit Gupta's leading theory: signers saw an innocent transaction on screen while their devices signed a malicious one. The losses exceeded $230 million, and WazirX shut down withdrawals.\n\nThrough the day 5 lens: whoever gets the signatures controls the funds, however many keys there are.", "sources": [{"url": "https://therecord.media/wazirx-crypto-platform-confirms-230-million-heist", "label": "The Record, WazirX confirms $230 million stolen, Jul 2024"}, {"url": "https://en.wikipedia.org/wiki/2024_WazirX_hack", "label": "Wikipedia, 2024 WazirX hack"}, {"url": "https://mudit.blog/wazirx-liminal-hacked-by-north-koreans/", "label": "Mudit Gupta, WazirX and Liminal hack analysis, Jul 2024"}, {"url": "https://bitpay.com/blog/what-are-public-and-private-keys/", "label": "BitPay, public and private keys"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the WazirX theft in order.", "steps": ["Funds sit in a four-of-six multisig", "Signers see what looks like a routine transaction", "Enough signers approve it", "The wallet's contract is swapped", "Attackers drain about $230 million"], "explanation": "The keys were never stolen outright. The signatures were."}, "numbers": {"kind": "numberSense", "prompt": "About how many million dollars did WazirX lose?", "min": 0, "max": 1000, "value": 230, "explanation": "Over $230 million. WazirX then shut down withdrawals.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview for a security role at an exchange. They ask what WazirX teaches.", "prompt": "Which answer lands best?", "options": ["Signers must verify exactly what they sign", "More keys always make a wallet fully safe", "Hardware devices cannot be fooled"], "correctIndex": 0, "consequences": ["The theory is that screens hid the real transaction.", "Four valid signatures still moved the funds.", "A device signs what it is sent."], "explanation": "Multisig helps only if each signer checks the real transaction. Fooled signers defeat it."}, "proReasoning": "Security teams verify signing data independently. Trusting one screen is the gap attackers use.", "commonMistake": "Treating the number of keys as the whole security story.", "mentalModel": "Verify what you sign."}, "invest": {"call": {"kind": "theCall", "situation": "An exchange you follow lost about half its reported reserves in one hack.", "prompt": "What do you ask first?", "options": ["How many different coins it lists", "How it holds and approves movement of keys", "Whether its app looks modern"], "correctIndex": 1, "consequences": ["Listings do not protect funds.", "Custody design decides whether a hack can happen.", "Design does not protect keys."], "explanation": "Custody risk is the core risk of an exchange. Ask how keys are held and how transfers are approved."}, "proReasoning": "Investors treat key custody as the main risk, not a footnote.", "commonMistake": "Assuming a multisig wallet ends the custody question.", "mentalModel": "Ask how keys move money."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup holds customer crypto in a multisig wallet.", "prompt": "What do you add first?", "options": ["A fifth and a sixth key, and nothing else at all", "One person who approves everything", "Independent checks of every transaction before signing"], "correctIndex": 2, "consequences": ["More keys do not help if signers are fooled.", "One approver is a single point of failure.", "Checking real transaction data stops screen tricks."], "explanation": "Attackers aim at the signing step. Independent verification protects it."}, "proReasoning": "Founders secure the signing process, not just the key count.", "commonMistake": "Adding keys while every signer trusts the same screen.", "mentalModel": "Protect the signing step."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a wallet needing four signatures could still be robbed.", "prompt": "What's the best answer?", "options": ["Signers were likely tricked into approving it", "The wallet had no password", "A bank reversed the money after the fact"], "correctIndex": 0, "consequences": ["The signatures were real; what they approved was not.", "Wallets use keys, not passwords.", "No bank can reverse a crypto transfer."], "explanation": "Multisig needs real signatures. Trick the signers, and the wallet obeys."}, "proReasoning": "A lock with four keys still opens if four people are fooled.", "commonMistake": "Assuming multisig makes theft impossible.", "mentalModel": "Fooled signers open any lock."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4967dacd4165$ml$]::text[]),
($ml$67fe1e42-642b-58ad-bb8a-7bee7172dfbc$ml$::uuid, $ml$web3$ml$, 5, 2, $ml${"id": "web3-d5-c2", "title": "A ledger anyone checks, a key only you hold", "lessonTitle": "The risk every crypto holder carries", "slot": 2, "type": "connect", "brief": {"headline": "Bitcoin's ledger is public and agreed by a whole network. Yet one lost or stolen private key can still mean lost funds.", "kicker": "Connect day 1 and day 5: a secure ledger, a fragile key.", "fullText": "Day 1 showed why a blockchain is hard to change: hash links plus consensus. Day 5 showed where the real weakness sits.\n\nA public key is shared to receive funds. A private key signs every transaction. The network checks signatures, not identities. So if an attacker gets the key, the ledger faithfully records their theft. In February 2025, hackers stole about $1.5 billion from Bybit, and the FBI attributed it to North Korea.", "sources": [{"url": "https://glossary.blockstream.com/block", "label": "Blockstream glossary, block"}, {"url": "https://bitpay.com/blog/what-are-public-and-private-keys/", "label": "BitPay, public and private keys"}, {"url": "https://www.ic3.gov/PSA/2025/PSA250226", "label": "FBI IC3, Bybit theft alert"}]}, "evidence": {"kind": "faceOff", "prompt": "In most thefts, what fails?", "left": {"name": "The ledger", "note": "Hash links and consensus"}, "right": {"name": "The key holder", "note": "Whoever controls the private key"}, "correctIndex": 1, "explanation": "The ledger works as designed. Attackers go after keys and signers."}, "numbers": {"kind": "numberSense", "prompt": "About how many billion dollars were stolen from Bybit in February 2025?", "min": 0, "max": 5, "value": 1.5, "explanation": "About $1.5 billion, attributed by the FBI to North Korea.", "unit": "B"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a wallet company. A colleague says blockchains are unhackable.", "prompt": "How do you put it more precisely?", "options": ["Say the ledger itself gets hacked often", "The ledger is strong; keys are the weak point", "Agree that crypto cannot be stolen"], "correctIndex": 1, "consequences": ["Rewriting the ledger is rare and costly.", "Thefts usually go through keys, not the ledger.", "Billions are stolen through keys every year."], "explanation": "The chain checks signatures. Whoever holds the key can move the funds, including a thief."}, "proReasoning": "Precise people separate ledger security from key security. Products live or die on the second.", "commonMistake": "Calling crypto unhackable because the ledger is hard to change.", "mentalModel": "Strong ledger, weak key."}, "invest": {"call": {"kind": "theCall", "situation": "A platform boasts that it runs on a \"secure blockchain\".", "prompt": "What should you check instead?", "options": ["How old the blockchain is", "How many users the platform has today", "How it stores and protects private keys"], "correctIndex": 2, "consequences": ["Age does not protect keys.", "Size can make it a bigger target.", "Keys are where funds are actually lost."], "explanation": "The blockchain is rarely the weak link. Key custody is."}, "proReasoning": "Investors look past the chain to the custody setup. That is where losses happen.", "commonMistake": "Taking \"built on blockchain\" as a security guarantee.", "mentalModel": "Check the keys."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app lets users hold their own keys.", "prompt": "What must your design make clear?", "options": ["A lost or stolen key cannot be undone", "Support can reset any key by email", "The chain refunds stolen funds"], "correctIndex": 0, "consequences": ["Clear warnings and backups prevent permanent losses.", "A self-custodied key cannot be reset.", "The ledger records the theft as valid."], "explanation": "In self-custody, the user is the bank. Your design must make backups and risks plain."}, "proReasoning": "Founders build backup flows and plain warnings. Trust depends on users keeping their keys.", "commonMistake": "Promising users a reset button that cannot exist.", "mentalModel": "Users are their own bank."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how crypto gets stolen if the blockchain is so secure.", "prompt": "What's the best answer?", "options": ["Banks lose the coins kept in their vaults", "Thieves steal keys, and the chain obeys them", "Thieves edit the blockchain records"], "correctIndex": 1, "consequences": ["Coins live on the chain, not in vaults.", "The chain accepts any valid signature.", "Editing the ledger is far harder than stealing a key."], "explanation": "The ledger checks the signature, not who you are. A stolen key signs like the owner."}, "proReasoning": "Picture an unbreakable vault with a key anyone can copy.", "commonMistake": "Thinking thieves break the blockchain itself.", "mentalModel": "The chain obeys the key."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:706a5d79d7f4$ml$]::text[]),
($ml$cc7c3e52-6429-536b-ad07-52be7d0fb6fa$ml$::uuid, $ml$web3$ml$, 5, 3, $ml${"id": "web3-d5-c3", "title": "Protecting a founder's crypto treasury", "lessonTitle": "The risk every crypto holder carries", "slot": 3, "type": "decide", "brief": {"headline": "You manage $5 million of a startup's crypto. One person holds the only key. A self-custodied private key that is lost usually cannot be reset.", "kicker": "Decide how to split control of the keys.", "fullText": "A private key signs every transaction. If it is lost, self-custodied funds can become unrecoverable. If it is stolen, the thief can move everything.\n\nBybit lost about $1.5 billion in February 2025, and the FBI says stolen funds were split across thousands of addresses on several blockchains within days. A single key in one person's hands is one mistake away from loss.", "sources": [{"url": "https://bitpay.com/blog/what-are-public-and-private-keys/", "label": "BitPay, public and private keys"}, {"url": "https://www.ic3.gov/PSA/2025/PSA250226", "label": "FBI IC3, Bybit theft alert"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this make the treasury safer or riskier?", "buckets": ["Safer", "Riskier"], "items": [{"text": "Requiring several people to approve transfers", "bucket": 0}, {"text": "Backups stored in separate places", "bucket": 0}, {"text": "Checking each transfer on a second device", "bucket": 0}, {"text": "One founder holds the only key", "bucket": 1}, {"text": "The key saved in an email draft", "bucket": 1}], "explanation": "Split control and separate backups remove single points of failure."}, "numbers": {"kind": "numberSense", "prompt": "About how many billion dollars did one exchange lose in February 2025?", "min": 0, "max": 6, "value": 1.5, "explanation": "About $1.5 billion at Bybit. Size makes custody a top risk.", "unit": "B"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the startup's new finance lead. The CEO keeps the only treasury key on a laptop.", "prompt": "What do you propose?", "options": ["Leave it, since the CEO is careful", "Move it all to a public spreadsheet", "Split approval across people and devices"], "correctIndex": 2, "consequences": ["One careful person is still one point of failure.", "Publishing keys hands them to anyone.", "No single loss or theft can drain the funds."], "explanation": "Splitting control means one lost laptop or one fooled person cannot empty the treasury."}, "proReasoning": "Finance leads remove single points of failure. Key control is the first one.", "commonMistake": "Leaving treasury safety to one person's good habits.", "mentalModel": "No single point of failure."}, "invest": {"call": {"kind": "theCall", "situation": "You're about to invest in a startup that holds crypto on its balance sheet.", "prompt": "What do you ask in diligence?", "options": ["Who can move the funds and how approval works", "What color the brand uses", "How many followers the founders have online"], "correctIndex": 0, "consequences": ["Custody setup decides whether the money is safe.", "Branding does not protect assets.", "Followers do not protect keys."], "explanation": "A startup's crypto is only as safe as its key control. Ask who signs and how."}, "proReasoning": "Investors check custody like they check bank accounts. It is basic diligence.", "commonMistake": "Skipping custody questions because the amount seems small.", "mentalModel": "Ask who can sign."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your team picks a treasury setup this week.", "prompt": "Which plan do you choose?", "options": ["Keys shared in the team chat for speed", "Multi-person approval with tested backups", "One hardware wallet in the CEO's desk"], "correctIndex": 1, "consequences": ["Chat history is easy to leak.", "Shared control plus backups survives one loss or theft.", "One device is one point of failure."], "explanation": "Splitting control across people and devices is the standard defense for treasury keys."}, "proReasoning": "Founders test recovery before they need it. A backup nobody has tried is a guess.", "commonMistake": "Optimizing for speed of transfers over safety of the treasury.", "mentalModel": "Split it and test it."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend keeps all their crypto on one phone with no backup.", "prompt": "What's the best advice?", "options": ["Do nothing, phones never break", "Email the private key to themselves for safety", "Make a safe backup and avoid one point of failure"], "correctIndex": 2, "consequences": ["Phones get lost, broken and stolen.", "Email can be hacked and searched.", "A lost phone could mean lost funds forever."], "explanation": "Lose the only key and the funds can be gone. A careful backup prevents that."}, "proReasoning": "In crypto, there is no reset button. Plan for the day the phone is gone.", "commonMistake": "Assuming a crypto company can restore your self-custodied coins.", "mentalModel": "No reset button."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1446d51054c2$ml$]::text[]),
($ml$b5db22bd-179e-5b03-b173-667a4127183a$ml$::uuid, $ml$web3$ml$, 6, 1, $ml${"id": "web3-d6-c1", "title": "The quantum estimate that kept shrinking", "lessonTitle": "Could quantum computers crack Bitcoin?", "slot": 1, "type": "apply", "brief": {"headline": "In May 2025, Google researcher Craig Gidney estimated that breaking RSA-2048 would need fewer than one million noisy qubits. In 2019 he had put it near 20 million.", "kicker": "Apply day 6: security lasts only as long as the math holds.", "fullText": "RSA is a different type of cryptography than Bitcoin's signatures, but it shows how fast the threat estimates move. In 2019, Gidney estimated a quantum computer would need about 20 million qubits to break 2048-bit RSA. His May 2025 paper cut that to fewer than one million noisy qubits, running for less than a week, The Quantum Insider reported.\n\nNo such machine exists yet. But each better estimate shortens the time holders have to move coins to safer address types.\n\nThrough the day 6 lens: the keys are only as safe as the math behind them.", "sources": [{"url": "https://thequantuminsider.com/2025/05/24/google-researcher-lowers-quantum-bar-to-crack-rsa-encryption/", "label": "The Quantum Insider, Google researcher lowers the quantum bar for RSA, May 2025"}, {"url": "https://cointelegraph.com/news/nearly-10-bitcoin-supply-structurally-unsafe-quantum-breakthrough-glassnode", "label": "Cointelegraph, nearly 10% of bitcoin supply structurally unsafe from a quantum breakthrough"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The 2025 estimate was under one million qubits.", "The 2019 estimate was about 20 million qubits.", "A machine that size already runs today."], "fakeIndex": 2, "explanation": "No machine that large exists yet. The estimates keep falling, which is the warning."}, "numbers": {"kind": "numberSense", "prompt": "Gidney's 2025 estimate for breaking RSA-2048 was under how many million noisy qubits?", "min": 0, "max": 5, "value": 1, "explanation": "Under one million, down from about 20 million in 2019.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a custody firm. They ask how quantum research affects their roadmap.", "prompt": "Which answer lands best?", "options": ["Panic and sell all client coins now", "Plan migration early, since estimates keep falling", "Ignore it until a real machine is announced"], "correctIndex": 1, "consequences": ["Clients own the coins; panic helps nobody.", "Moving to safer keys takes years, so starting early matters.", "Migration takes too long to start at the last minute."], "explanation": "Estimates of the needed machine keep shrinking. Migration planning has a long lead time."}, "proReasoning": "Security people plan for threats with long lead times. Quantum is one.", "commonMistake": "Waiting for a working quantum computer before planning a move.", "mentalModel": "Plan before the machine."}, "invest": {"call": {"kind": "theCall", "situation": "You hold bitcoin long term and read that quantum estimates fell twentyfold.", "prompt": "What is the sensible takeaway?", "options": ["Bitcoin will break next month", "The research does not matter at all", "A slow tail risk worth watching"], "correctIndex": 2, "consequences": ["The machine described does not exist yet.", "Falling estimates change timelines.", "No machine exists, but the trend deserves attention."], "explanation": "Shrinking estimates make the risk nearer, not immediate. Watch how wallets and custodians respond."}, "proReasoning": "Investors track slow risks without overreacting. Direction matters as much as distance.", "commonMistake": "Treating every research paper as an emergency or as noise.", "mentalModel": "Watch the trend."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds wallet software.", "prompt": "What do you put on the roadmap?", "options": ["Tools to move coins to safer address types", "A claim that wallets are quantum-proof", "Nothing until a standard is final"], "correctIndex": 0, "consequences": ["Migration tools serve holders as standards change.", "No current wallet can honestly claim that.", "Groundwork can start before a standard is final."], "explanation": "Exposure can shrink as wallets and address standards change. Helping users move is useful work."}, "proReasoning": "Founders build for transitions the market can see coming. Migration is one.", "commonMistake": "Marketing a product as quantum-proof without a standard behind it.", "mentalModel": "Build the migration path."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if quantum computers can steal bitcoin today.", "prompt": "What's the best answer?", "options": ["Never, because the math is perfect forever", "Not yet, but the machines needed are shrinking", "Yes, it happens every day"], "correctIndex": 1, "consequences": ["Math can weaken as computing changes.", "Estimates fell sharply, but no such machine exists.", "No quantum theft has happened."], "explanation": "Today's computers cannot break the keys. Researchers keep lowering the size of machine that might."}, "proReasoning": "Think of it as a clock that keeps getting set earlier.", "commonMistake": "Assuming crypto security is permanent once designed.", "mentalModel": "The clock keeps moving."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:39e144287541$ml$]::text[]),
($ml$3dce0cb5-6951-5ee6-8d39-d82a130a2dda$ml$::uuid, $ml$web3$ml$, 6, 2, $ml${"id": "web3-d6-c2", "title": "Why exposed keys are the weak spot", "lessonTitle": "Could quantum computers crack Bitcoin?", "slot": 2, "type": "connect", "brief": {"headline": "Glassnode estimated in May 2026 that about 9.6% of bitcoin is structurally exposed to a future quantum computer, because those addresses reveal their public key.", "kicker": "Connect day 5 and day 6: whoever gets the key gets the coins.", "fullText": "Day 5 showed that a private key signs every transaction, and control of the key is control of the money. Day 6 showed a new way a key could be taken.\n\nSome address types put the public key on the chain. A large enough quantum computer could, in theory, work backward from a public key to the private key. Glassnode estimated about 1.92 million exposed coins, including about 1.1 million attributed to Satoshi. A proposal called BIP-360 would add an output type without Taproot's exposed key path.", "sources": [{"url": "https://cointelegraph.com/news/nearly-10-bitcoin-supply-structurally-unsafe-quantum-breakthrough-glassnode", "label": "Cointelegraph, nearly 10% of bitcoin supply structurally unsafe from a quantum breakthrough"}, {"url": "https://bitpay.com/blog/what-are-public-and-private-keys/", "label": "BitPay, public and private keys"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What makes some bitcoin more exposed to a quantum attack?", "options": ["They are held on big exchanges", "They were bought recently", "Their public key is visible on-chain"], "correctIndex": 2, "explanation": "A revealed public key is what a quantum attacker would start from."}, "numbers": {"kind": "numberSense", "prompt": "About how many million bitcoin did Glassnode call structurally exposed?", "min": 0, "max": 6, "value": 1.9, "explanation": "About 1.92 million, or 9.6% of supply.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your team at a wallet company debates quantum risk.", "prompt": "What is the key fact to bring?", "options": ["Every bitcoin is equally exposed", "Only coins held on exchanges are exposed", "Coins with revealed public keys are the target"], "correctIndex": 2, "consequences": ["Many addresses do not reveal the key until spending.", "Custody location is not the deciding factor.", "Exposure depends on address type, not where coins sit."], "explanation": "The attack path runs through visible public keys. That tells you which coins to protect first."}, "proReasoning": "Strong engineers locate the exact weak point. Here it is the exposed public key.", "commonMistake": "Describing quantum risk as hitting all coins the same way.", "mentalModel": "Find the exposed keys."}, "invest": {"call": {"kind": "theCall", "situation": "You hear that 1.1 million exposed coins are attributed to Satoshi.", "prompt": "Why does that matter to the market?", "options": ["A large dormant stash could one day move", "Satoshi will sell them next week", "Those coins were already destroyed"], "correctIndex": 0, "consequences": ["If keys were broken, those coins could reach the market.", "Nothing suggests a planned sale.", "They still exist on the chain."], "explanation": "A large exposed holding is a supply risk if the math ever breaks."}, "proReasoning": "Investors note concentrated, exposed holdings. They are a tail risk to supply.", "commonMistake": "Assuming dormant coins can never move again.", "mentalModel": "Dormant is not gone."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers a service to check a user's addresses.", "prompt": "What should it flag first?", "options": ["Addresses created on weekends", "Addresses that have revealed their public key", "Addresses that have the most transactions"], "correctIndex": 1, "consequences": ["Creation day is irrelevant.", "Those are the ones a quantum attacker could target.", "Activity alone does not create exposure."], "explanation": "Exposure comes from revealed keys. That is what users need flagged."}, "proReasoning": "Founders build tools around the real risk factor. Here it is key exposure.", "commonMistake": "Flagging risk by a signal that has nothing to do with the threat.", "mentalModel": "Flag revealed keys."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Satoshi's coins are often mentioned with quantum risk.", "prompt": "What's the best answer?", "options": ["Satoshi used a weak password", "They are stored on one old laptop", "Their old addresses reveal the public key"], "correctIndex": 2, "consequences": ["Bitcoin uses keys, not passwords.", "Nobody knows where Satoshi's keys are.", "Early address types put the key on-chain."], "explanation": "Early address types expose the public key. That is the starting point for a quantum attack."}, "proReasoning": "Old addresses show the key in public. That is the weak spot.", "commonMistake": "Thinking quantum risk is about passwords or devices.", "mentalModel": "Old addresses show the key."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d86a888210b5$ml$]::text[]),
($ml$8ccd3482-4c92-5166-983e-c08c919d77ed$ml$::uuid, $ml$web3$ml$, 6, 3, $ml${"id": "web3-d6-c3", "title": "When should a custodian start moving coins?", "lessonTitle": "Could quantum computers crack Bitcoin?", "slot": 3, "type": "decide", "brief": {"headline": "You run custody for clients. About 9.6% of bitcoin sits in structurally exposed addresses, and a proposed fix, BIP-360, does not yet add quantum-safe signatures.", "kicker": "Decide when to begin a quantum migration plan.", "fullText": "Glassnode estimated in May 2026 that about 9.6% of bitcoin is exposed to a future quantum computer. Ark Invest estimated a break would need about 2,330 logical qubits, a machine that does not yet exist.\n\nBIP-360 proposes a new output type that drops Taproot's exposed key path, but it does not add quantum-safe signatures yet. Moving client coins to safer address types takes time, testing and client communication. The question is when to start.", "sources": [{"url": "https://cointelegraph.com/news/nearly-10-bitcoin-supply-structurally-unsafe-quantum-breakthrough-glassnode", "label": "Cointelegraph, nearly 10% of bitcoin supply structurally unsafe from a quantum breakthrough"}]}, "evidence": {"kind": "sortSignal", "prompt": "Start planning now, or wait for more?", "buckets": ["Start now", "Wait"], "items": [{"text": "Inventory which client addresses expose keys", "bucket": 0}, {"text": "Stop reusing addresses", "bucket": 0}, {"text": "Draft a client communication plan", "bucket": 0}, {"text": "Adopt an unfinished signature standard", "bucket": 1}, {"text": "Move every coin in one rushed day", "bucket": 1}], "explanation": "Cheap, safe steps can start now. Big irreversible moves can wait for standards."}, "numbers": {"kind": "numberSense", "prompt": "Ark Invest estimated a break would need about how many logical qubits?", "min": 0, "max": 5, "value": 2.3, "explanation": "About 2,330 logical qubits. No such machine exists yet.", "unit": "K"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a new risk analyst at a custodian. Your boss asks for a quantum plan.", "prompt": "What do you propose first?", "options": ["Map exposed addresses and stop reusing them", "Wait for a quantum computer to appear", "Move all coins to an untested format"], "correctIndex": 0, "consequences": ["Low-cost steps cut exposure while standards mature.", "By then, migration time may run out.", "An untested format adds new risk."], "explanation": "Start with inventory and hygiene. Save irreversible moves for finished standards."}, "proReasoning": "Risk analysts start with what is cheap and reversible. Big moves follow standards.", "commonMistake": "Making a rushed, irreversible move to look prepared.", "mentalModel": "Cheap steps first."}, "invest": {"call": {"kind": "theCall", "situation": "A custodian you invest in says quantum risk is \"not our problem\".", "prompt": "How do you read that?", "options": ["A reason to buy more of its stock", "A planning gap on a slow but real risk", "A sign of strong security"], "correctIndex": 1, "consequences": ["Dismissal is not a growth story.", "Exposure is measurable today, even if the threat is not.", "Ignoring a risk is not strength."], "explanation": "About 9.6% of supply is exposed. A custodian should at least have a plan."}, "proReasoning": "Investors reward firms that plan for slow risks before they arrive.", "commonMistake": "Mistaking a dismissal for confidence.", "mentalModel": "No plan is a risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your custody startup wants to stand out to clients.", "prompt": "Which offer is most credible?", "options": ["A claim of full quantum immunity today", "A promise to ignore the topic", "A clear, staged plan to reduce key exposure"], "correctIndex": 2, "consequences": ["No standard supports that claim yet.", "Clients will ask; silence loses trust.", "Staged steps are honest and checkable."], "explanation": "Exposure can shrink as wallets and standards change. A staged plan shows you are ready."}, "proReasoning": "Founders win trust by being specific about what they can do now and later.", "commonMistake": "Overpromising protection that does not exist yet.", "mentalModel": "Be specific, not absolute."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend with bitcoin asks if they should worry about quantum computers.", "prompt": "What's the best advice?", "options": ["Avoid reusing addresses and follow wallet updates", "Sell everything today out of fear", "Ignore it; nothing about this will ever change"], "correctIndex": 0, "consequences": ["Simple habits reduce exposure while fixes arrive.", "No machine can break keys yet.", "Standards and wallets are already changing."], "explanation": "The threat is not here yet. Good habits and updated wallets reduce exposure over time."}, "proReasoning": "Small habits now beat panic later.", "commonMistake": "Reacting to quantum headlines with fear instead of steps.", "mentalModel": "Small habits now."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:50092df418b1$ml$]::text[]),
($ml$853a21e9-72d6-553f-96ba-5eb3e2823dfd$ml$::uuid, $ml$web3$ml$, 7, 1, $ml${"id": "web3-d7-c1", "title": "10,000 bitcoin for two pizzas", "lessonTitle": "The nine pages that started Bitcoin", "slot": 1, "type": "apply", "brief": {"headline": "On May 22, 2010, programmer Laszlo Hanyecz paid 10,000 BTC for two large pizzas, worth about $41 at the time. It is remembered as Bitcoin's first well-known purchase.", "kicker": "Apply day 7: peer-to-peer cash, used for something real.", "fullText": "Hanyecz posted his offer on the Bitcointalk forum on May 18, 2010. A 19-year-old, Jeremy Sturdivant, took it and had two Papa John's pizzas delivered. Hanyecz sent him 10,000 BTC, worth about $41, CoinDesk reports.\n\nNo bank or card network sat between them. One person sent coins straight to another, and the network recorded it.\n\nThrough the day 7 lens: the white paper described payments between people with no financial institution in the middle. The pizza trade was that idea in action, about 17 months after the genesis block.", "sources": [{"url": "https://www.coindesk.com/learn/what-is-bitcoin-pizza-day/", "label": "CoinDesk, what is Bitcoin Pizza Day"}, {"url": "https://blockworks.co/news/bitcoin-anniversary-satoshi-nakamoto", "label": "Blockworks, Bitcoin white paper turns 15 years old"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the pizza trade in order.", "steps": ["Hanyecz offers bitcoin for pizza on a forum", "Sturdivant accepts the offer", "Two pizzas are delivered", "Hanyecz sends 10,000 BTC directly", "The network records the payment"], "explanation": "No bank approved anything. The network recorded a payment between two people."}, "numbers": {"kind": "numberSense", "prompt": "About how many dollars were the 10,000 BTC worth at the time?", "min": 0, "max": 200, "value": 41, "explanation": "About $41. The trade mattered for what it showed, not what it cost.", "unit": "$"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a payments company. They ask what the pizza trade proved.", "prompt": "Which answer lands best?", "options": ["Bitcoin was already worth a fortune then", "Pizza chains accepted bitcoin directly", "Two people could trade with no bank in between"], "correctIndex": 2, "consequences": ["It was worth about $41 at the time.", "The buyer paid a person, who ordered the pizzas.", "That is the white paper idea, working in practice."], "explanation": "The trade showed peer-to-peer payment working for a real good. That was the paper's promise."}, "proReasoning": "Payments people focus on who sits in the middle. Here, nobody did.", "commonMistake": "Retelling the trade only as a story about lost fortunes.", "mentalModel": "No one in the middle."}, "invest": {"call": {"kind": "theCall", "situation": "You hear the pizza story used to argue bitcoin always goes up.", "prompt": "What is the sounder lesson?", "options": ["It showed a working payment, not a price rule", "Every coin will rise just like this one did", "Selling early is always the wrong choice"], "correctIndex": 0, "consequences": ["The point was a peer-to-peer trade between strangers.", "One coin's history does not predict others.", "Hindsight is not a strategy."], "explanation": "The trade proved a mechanism. Using it as a price prediction misreads it."}, "proReasoning": "Investors separate a good story from a good thesis.", "commonMistake": "Turning one famous trade into a rule about future prices.", "mentalModel": "A story is not a thesis."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup lets people pay each other directly in crypto.", "prompt": "What does the pizza trade say about adoption?", "options": ["Adoption needs a bank to approve trades", "People adopt when they can buy something real", "Users only care about prices going up"], "correctIndex": 1, "consequences": ["The point was no bank at all.", "A real purchase made the idea concrete.", "The first trade was about using the coin, not price."], "explanation": "Payments catch on when they buy real things. The pizza trade was that moment."}, "proReasoning": "Founders look for the first real use. Abstract features rarely drive adoption.", "commonMistake": "Pitching a payment product with no real thing to buy.", "mentalModel": "Real use drives adoption."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why people celebrate \"Bitcoin Pizza Day\".", "prompt": "What's the best answer?", "options": ["Bitcoin itself was invented on that exact day", "Pizza shops gave away free pizza", "It marks an early real purchase with bitcoin"], "correctIndex": 2, "consequences": ["The white paper came out in 2008.", "The pizzas were paid for in bitcoin.", "10,000 BTC bought two pizzas in May 2010."], "explanation": "The trade showed bitcoin working as money between two people."}, "proReasoning": "It is the day a white paper idea bought dinner.", "commonMistake": "Thinking the day marks Bitcoin's launch.", "mentalModel": "The idea bought dinner."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:069b8fa1d252$ml$]::text[]),
($ml$288f2cf8-40b0-5dc3-9768-c566809d905c$ml$::uuid, $ml$web3$ml$, 7, 2, $ml${"id": "web3-d7-c2", "title": "From a nine-page paper to a halving schedule", "lessonTitle": "The nine pages that started Bitcoin", "slot": 2, "type": "connect", "brief": {"headline": "Satoshi Nakamoto published Bitcoin's nine-page white paper on October 31, 2008. The genesis block followed on January 3, 2009, and its rules still pay miners on a fixed schedule.", "kicker": "Connect day 2 and day 7: the design set who pays the guards.", "fullText": "Day 7 showed the white paper: payments sent directly between people, with the network replacing the bank. Day 2 showed how that network is paid for: block rewards that halve every 210,000 blocks, toward a 21 million cap.\n\nThe two fit together. With no bank to run the ledger, someone has to be paid to secure it. Bitcoin pays miners new coins and fees, under rules written in code from the start.", "sources": [{"url": "https://blockworks.co/news/bitcoin-anniversary-satoshi-nakamoto", "label": "Blockworks, Bitcoin white paper turns 15 years old"}, {"url": "https://www.benzinga.com/money/what-is-bitcoin-halving", "label": "Benzinga, Bitcoin halving explained"}]}, "evidence": {"kind": "faceOff", "prompt": "Which came first?", "left": {"name": "The white paper", "note": "October 31, 2008"}, "right": {"name": "The genesis block", "note": "January 3, 2009"}, "correctIndex": 0, "explanation": "The paper came first, about two months before the first block."}, "numbers": {"kind": "numberSense", "prompt": "How many pages long was the Bitcoin white paper?", "min": 0, "max": 40, "value": 9, "explanation": "Nine pages. It described the system before it was built.", "unit": "pages"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview why Bitcoin needs miners at all.", "prompt": "What is the clearest answer?", "options": ["No bank runs the ledger, so the network pays guards", "Miners print new coins on behalf of the government", "Miners approve who may use Bitcoin"], "correctIndex": 0, "consequences": ["Replacing the bank means paying someone to secure records.", "No government role exists in mining.", "Anyone may use Bitcoin without approval."], "explanation": "The white paper removed the middleman. Miners, paid in coins and fees, do the securing instead."}, "proReasoning": "Strong candidates link the design goal to the incentive. That shows real understanding.", "commonMistake": "Describing miners as gatekeepers who approve users.", "mentalModel": "Someone must guard the ledger."}, "invest": {"call": {"kind": "theCall", "situation": "You read Bitcoin's supply schedule has not changed since launch.", "prompt": "Why might investors value that?", "options": ["It guarantees miners stay profitable", "The rules are predictable and checkable", "It means the price is fixed forever"], "correctIndex": 1, "consequences": ["Profit depends on costs and price too.", "Investors can model supply years ahead.", "Price moves freely; supply is what is fixed."], "explanation": "Fixed, public rules make supply predictable. That is a feature many investors value."}, "proReasoning": "Investors prize rules they can read and verify, especially on supply.", "commonMistake": "Confusing a fixed supply schedule with a fixed price.", "mentalModel": "Predictable supply, not price."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup writes a white paper for a new protocol.", "prompt": "What should it make clear early?", "options": ["How famous the founding team is", "A promise that the token price will keep rising", "Who secures the system and how they are paid"], "correctIndex": 2, "consequences": ["Fame does not secure a network.", "Price promises invite legal trouble.", "Incentives decide whether the system survives."], "explanation": "Bitcoin's paper paired a goal with a way to pay for security. Yours should too."}, "proReasoning": "Founders who explain incentives earn technical trust. It is the hardest question.", "commonMistake": "Writing a white paper that never says who keeps the system honest.", "mentalModel": "Explain the incentives."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks who decided how many bitcoin there would be.", "prompt": "What's the best answer?", "options": ["The rules set at launch, still enforced by code", "A vote held by bitcoin owners every single year", "The US Treasury, after 2009"], "correctIndex": 0, "consequences": ["Supply and halvings were in the design from the start.", "No yearly vote sets supply.", "No government sets bitcoin supply."], "explanation": "Satoshi's design set the schedule. The network enforces it every block."}, "proReasoning": "The rules were written once, and every computer checks them.", "commonMistake": "Thinking someone can change bitcoin supply at will.", "mentalModel": "Written once, checked always."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a822ea3bbc29$ml$]::text[]),
($ml$bdccff09-e108-5e75-86cf-e26e5e6495d9$ml$::uuid, $ml$web3$ml$, 7, 3, $ml${"id": "web3-d7-c3", "title": "Explaining Bitcoin in one minute", "lessonTitle": "The nine pages that started Bitcoin", "slot": 3, "type": "decide", "brief": {"headline": "You present Bitcoin to your company's finance team. The white paper's idea: payments sent directly between people, with no financial institution in the middle.", "kicker": "Decide how to explain the core idea without hype.", "fullText": "The white paper, published October 31, 2008, ran just nine pages. It described a peer-to-peer electronic cash system. Payments go straight between users, and a network of computers replaces the bank that would normally keep the ledger.\n\nYour audience knows banks well. The clearest explanation starts from what Bitcoin removes and what does that job instead.", "sources": [{"url": "https://blockworks.co/news/bitcoin-anniversary-satoshi-nakamoto", "label": "Blockworks, Bitcoin white paper turns 15 years old"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did the white paper propose to remove from payments?", "options": ["The need for any kind of record at all", "Fees paid to anyone", "The financial institution in the middle"], "correctIndex": 2, "explanation": "It removed the trusted middleman. The network keeps the record instead."}, "numbers": {"kind": "numberSense", "prompt": "In which month of 2008 was the white paper published?", "min": 0, "max": 12, "value": 10, "explanation": "October 2008, on October 31."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You present to the finance team. Someone asks \"so what is Bitcoin, really?\"", "prompt": "Which answer works best?", "options": ["A secret bank account in another country", "A shared ledger kept by a network, not a bank", "A stock that tech companies issue"], "correctIndex": 1, "consequences": ["Bitcoin is a public network, not an account.", "It ties the idea to what they already know: ledgers.", "Bitcoin is not issued by any company."], "explanation": "Start from the ledger finance people know. Then say who keeps it: a network."}, "proReasoning": "Good explainers start from what the audience already knows.", "commonMistake": "Opening with price charts instead of the idea.", "mentalModel": "Start from the ledger."}, "invest": {"call": {"kind": "theCall", "situation": "A colleague asks if Bitcoin is \"just speculation\".", "prompt": "What is the fairest answer?", "options": ["Yes, it has no real function of any kind at all", "No, its price can only go up", "It is a payment network; price is a separate question"], "correctIndex": 2, "consequences": ["It does move payments without a bank.", "Prices fall as well as rise.", "You separate what it does from what it trades at."], "explanation": "The network has a function described in the paper. Its price is a separate matter."}, "proReasoning": "Investors separate the asset's function from its price story.", "commonMistake": "Answering a question about function with a price prediction.", "mentalModel": "Function first, price second."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup pitches a Bitcoin payment tool to merchants.", "prompt": "What do you emphasize?", "options": ["Direct payment, with no card network in between", "Bitcoin's price might rise after they sell", "That nobody will ever see any fees"], "correctIndex": 0, "consequences": ["Removing the middleman is the core benefit.", "Merchants want sales, not price bets.", "Network fees still apply."], "explanation": "The paper's promise is peer-to-peer payment. That is what a merchant tool should sell."}, "proReasoning": "Founders pitch the job a product does. For Bitcoin payments, that is skipping the middleman.", "commonMistake": "Selling price speculation to merchants who want sales.", "mentalModel": "Sell the job it does."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks you to explain Bitcoin in one sentence.", "prompt": "What's the best answer?", "options": ["An app made by a big bank", "Money people send directly, recorded by a network", "A coin that a few tech billionaires quietly control"], "correctIndex": 1, "consequences": ["No bank made Bitcoin.", "That is the paper's idea in plain words.", "No single person controls Bitcoin."], "explanation": "Payments between people, with a network instead of a bank keeping the record."}, "proReasoning": "One sentence: money between people, no bank needed.", "commonMistake": "Explaining Bitcoin through who got rich.", "mentalModel": "Money between people."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:540411a75c79$ml$]::text[]),
($ml$e99aa3f1-7a90-5c0b-82d8-e2c74fe8a0d8$ml$::uuid, $ml$web3$ml$, 8, 1, $ml${"id": "web3-d8-c1", "title": "Ether funds debut, and fees decide the flows", "lessonTitle": "Wall Street's bitcoin funds", "slot": 1, "type": "apply", "brief": {"headline": "Spot ether ETFs began trading on July 23, 2024, with over $1 billion in day-one volume. BlackRock took in $266 million while Grayscale's ETHE lost $484 million.", "kicker": "Apply day 8: Wall Street funds now move crypto at scale.", "fullText": "Nine spot ether ETFs launched in the US on July 23, 2024, seven months after bitcoin ETFs. Day-one trading topped $1.019 billion, The Block reported.\n\nThe flows split sharply. BlackRock's fund drew $266 million. Grayscale's Ethereum Trust, converted from an older trust, saw $484 million leave. ETHE charged 2.5% a year, while rivals charged 0.25% or less, Fortune reported. Net inflows were $107 million.\n\nThrough the day 8 lens: funds give investors exposure without a wallet, and they compete on cost like any other fund.", "sources": [{"url": "https://www.theblock.co/post/307063/spot-ethereum-etfs-generate-over-1-billion-in-trading-volume-on-first-day", "label": "The Block, spot Ethereum ETFs top $1 billion volume on day one, Jul 2024"}, {"url": "https://fortune.com/crypto/2024/07/24/ethereum-etf-launch-a-success-as-blackrock-pulls-in-266-million-while-grayscale-sees-massive-outflow/", "label": "Fortune, Ethereum ETF launch: BlackRock pulls in $266 million, Jul 2024"}, {"url": "https://www.theblock.co/amp/post/361525/blackrocks-spot-bitcoin-etf-ibit-surpasses-700000-btc-assets-under-management", "label": "The Block, BlackRock's IBIT surpasses 700,000 BTC"}]}, "evidence": {"kind": "faceOff", "prompt": "On day one, which ether fund lost money to outflows?", "left": {"name": "Grayscale ETHE", "note": "Charged 2.5% a year"}, "right": {"name": "BlackRock's fund", "note": "Charged 0.25% or less"}, "correctIndex": 0, "explanation": "ETHE lost $484 million. High fees pushed holders to cheaper funds."}, "numbers": {"kind": "numberSense", "prompt": "About how many million dollars flowed out of Grayscale's ETHE on day one?", "min": 0, "max": 1200, "value": 484, "explanation": "About $484 million, while BlackRock's fund took in $266 million.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join an ETF desk. Your manager asks why ETHE lost money on launch day.", "prompt": "Which answer lands best?", "options": ["Its 2.5% fee was ten times its rivals'", "Ether stopped trading that afternoon", "Investors did not want ether exposure"], "correctIndex": 0, "consequences": ["Holders moved to cheaper funds holding the same asset.", "Ether traded normally that day.", "Net inflows were still positive."], "explanation": "Funds holding the same asset compete on fees. ETHE's high fee pushed money out."}, "proReasoning": "ETF professionals look at fees first when flows split. Same asset, different price.", "commonMistake": "Reading outflows from one fund as a verdict on ether itself.", "mentalModel": "Same asset, cheaper wrapper."}, "invest": {"call": {"kind": "theCall", "situation": "You want ether exposure through a fund. Several hold the same coin.", "prompt": "What should decide your pick first?", "options": ["Whichever fund is the oldest", "The yearly fee, since the holdings match", "Which fund had the most volume day one"], "correctIndex": 1, "consequences": ["Age raised costs here, not quality.", "Identical holdings make cost the main difference.", "Volume measures trading, not your cost."], "explanation": "When funds hold the same asset, fees compound against you every year."}, "proReasoning": "Investors compare fees on identical products. Small gaps add up.", "commonMistake": "Picking a fund by brand or volume instead of cost.", "mentalModel": "Fees compound."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup plans a crypto fund product.", "prompt": "What did the ether ETF launch teach you?", "options": ["Charge more, since the asset is new and exciting", "Fees do not matter to fund buyers", "Price competitively; investors switch fast"], "correctIndex": 2, "consequences": ["ETHE charged more and lost money.", "Flows followed fees on day one.", "$484 million left the high-fee fund in a day."], "explanation": "Identical exposure turns fees into the battleground. Launch priced to compete."}, "proReasoning": "Founders entering crowded products price for switching. Investors move to cheaper wrappers.", "commonMistake": "Assuming early investors are too loyal to switch.", "mentalModel": "Price for switching."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what an ether ETF actually is.", "prompt": "What's the best answer?", "options": ["A fund holding ether that trades like a stock", "A new coin issued by BlackRock", "A savings account that pays interest in ether"], "correctIndex": 0, "consequences": ["You get ether exposure through a brokerage account.", "The fund holds ether; it is not a new coin.", "It is a fund share, not a bank account."], "explanation": "An ETF holds the asset and trades on an exchange. No wallet needed."}, "proReasoning": "Think of it as ether in a stock-shaped box.", "commonMistake": "Thinking an ETF creates its own cryptocurrency.", "mentalModel": "Ether in a stock-shaped box."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:afef8b93949c$ml$]::text[]),
($ml$8810e0d1-a6ec-5803-a7c2-ea6d669ef6b4$ml$::uuid, $ml$web3$ml$, 8, 2, $ml${"id": "web3-d8-c2", "title": "Funds holding a slice of a fixed supply", "lessonTitle": "Wall Street's bitcoin funds", "slot": 2, "type": "connect", "brief": {"headline": "US spot bitcoin ETFs held about 1.25 million bitcoin in July 2025, nearly 6% of the 21 million that will ever exist. BlackRock's IBIT alone held over 700,000.", "kicker": "Connect day 4 and day 8: big holders inside a capped supply.", "fullText": "Day 4 showed Bitcoin's fixed numbers: a 21 million cap and about 450 new coins a day after the 2024 halving. Day 8 showed who is buying.\n\nBy July 2025, US spot bitcoin ETFs held about 1.25 million bitcoin, The Block reported, nearly 6% of all supply. IBIT held over 700,000 of those, about 56% of US spot bitcoin ETF assets. Net inflows had passed $50 billion. Funds buying a fixed supply is a new force in the market.", "sources": [{"url": "https://www.theblock.co/amp/post/361525/blackrocks-spot-bitcoin-etf-ibit-surpasses-700000-btc-assets-under-management", "label": "The Block, BlackRock's IBIT surpasses 700,000 BTC"}, {"url": "https://www.benzinga.com/money/what-is-bitcoin-halving", "label": "Benzinga, Bitcoin halving explained"}]}, "evidence": {"kind": "multipleChoice", "prompt": "About what share of bitcoin's 21 million supply did US spot ETFs hold in July 2025?", "options": ["Nearly 6%", "About 30%", "Under 1%"], "correctIndex": 0, "explanation": "About 1.25 million bitcoin, nearly 6% of the cap."}, "numbers": {"kind": "numberSense", "prompt": "About how many thousand bitcoin did IBIT hold in July 2025?", "min": 0, "max": 1500, "value": 700, "explanation": "Over 700,000. That made it the biggest US spot bitcoin ETF.", "unit": "K"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks how ETFs changed bitcoin's market.", "prompt": "Which answer lands best?", "options": ["They replaced the miners who secure the whole network", "They became some of the largest holders of a fixed supply", "They raised bitcoin's supply cap to 25 million"], "correctIndex": 1, "consequences": ["ETFs hold coins; miners still secure the chain.", "About 6% of all supply sat in US ETFs by July 2025.", "The 21 million cap did not change."], "explanation": "Funds holding a large share of a capped supply is a structural change in who owns bitcoin."}, "proReasoning": "Strong answers tie holders to supply numbers. Six percent is the figure to know.", "commonMistake": "Saying ETFs changed how bitcoin works technically.", "mentalModel": "New holders, same cap."}, "invest": {"call": {"kind": "theCall", "situation": "You compare daily new bitcoin supply to ETF buying.", "prompt": "Why does that comparison matter?", "options": ["ETFs create brand new coins whenever they buy", "Issuance rises to match ETF demand", "Strong fund demand can exceed new issuance"], "correctIndex": 2, "consequences": ["ETFs buy existing coins.", "Issuance is fixed by code, not demand.", "About 450 coins a day are mined; funds can buy more."], "explanation": "Issuance is fixed at about 450 a day. Demand from funds comes on top of that."}, "proReasoning": "Investors weigh fixed new supply against new demand. Funds are part of that demand.", "commonMistake": "Assuming supply adjusts to demand as it would for a company's shares.", "mentalModel": "Demand meets a fixed flow."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds tools for advisers who use bitcoin ETFs.", "prompt": "What data would advisers value most?", "options": ["Fund holdings compared with total supply", "A daily guess at Satoshi's real identity", "Daily memes about bitcoin"], "correctIndex": 0, "consequences": ["Holdings against supply show the funds' footprint.", "Speculation is not data.", "Memes do not inform decisions."], "explanation": "Advisers want to know how big the funds are relative to the asset. Supply makes that clear."}, "proReasoning": "Founders serving advisers deliver context they can repeat to clients.", "commonMistake": "Building adviser tools around noise instead of numbers.", "mentalModel": "Give context they can repeat."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why it matters that funds own so much bitcoin.", "prompt": "What's the best answer?", "options": ["It means bitcoin is now a stock", "A few large funds now hold a big share", "They can print more bitcoin when needed"], "correctIndex": 1, "consequences": ["Bitcoin is still a coin; the funds trade like stocks.", "Nearly 6% of all bitcoin sat in US ETFs.", "No one can print bitcoin."], "explanation": "Funds buying a capped supply gives them weight in the market."}, "proReasoning": "When a few buyers hold a big slice, their choices move the market.", "commonMistake": "Thinking funds can change how many bitcoin exist.", "mentalModel": "Big buyers, fixed supply."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6ba527f1a492$ml$]::text[]),
($ml$8ec61ed9-1813-5916-95a4-f7fb45c49c29$ml$::uuid, $ml$web3$ml$, 8, 3, $ml${"id": "web3-d8-c3", "title": "An adviser's client wants bitcoin, not a wallet", "lessonTitle": "Wall Street's bitcoin funds", "slot": 3, "type": "decide", "brief": {"headline": "You advise a client who wants bitcoin exposure but not a wallet. IBIT held over 700,000 bitcoin and ranked as BlackRock's third-highest revenue ETF out of 1,197.", "kicker": "Decide between a fund and holding coins directly.", "fullText": "A spot bitcoin ETF holds real bitcoin and trades on a stock exchange. Investors get exposure without managing keys. By July 2025, IBIT held over 700,000 bitcoin and was BlackRock's third-highest revenue ETF out of 1,197 funds, The Block reported.\n\nHolding coins directly means controlling your own keys, with no fund fee but full responsibility. The right choice depends on the client.", "sources": [{"url": "https://www.theblock.co/amp/post/361525/blackrocks-spot-bitcoin-etf-ibit-surpasses-700000-btc-assets-under-management", "label": "The Block, BlackRock's IBIT surpasses 700,000 BTC"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this point to a fund or holding coins directly?", "buckets": ["Fund", "Direct"], "items": [{"text": "Wants it in an existing brokerage account", "bucket": 0}, {"text": "Does not want to manage keys", "bucket": 0}, {"text": "Wants to send bitcoin to others", "bucket": 1}, {"text": "Wants no fund fee at all", "bucket": 1}, {"text": "Comfortable running a hardware wallet", "bucket": 1}], "explanation": "Funds suit hands-off exposure. Direct holding suits people who will use and guard the coins."}, "numbers": {"kind": "numberSense", "prompt": "IBIT ranked as BlackRock's top what, by revenue, among its ETFs?", "min": 0, "max": 20, "value": 3, "explanation": "Third, out of 1,197 BlackRock funds."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a junior adviser. A retired client wants bitcoin but fears losing keys.", "prompt": "What do you suggest?", "options": ["A hardware wallet with a paper backup", "A crypto app recommended by a friend", "A spot ETF in their brokerage account"], "correctIndex": 2, "consequences": ["Self-custody is the burden they fear.", "An unvetted app adds unknown risk.", "They get exposure without key risk."], "explanation": "ETFs give exposure without key management. That fits a client afraid of losing keys."}, "proReasoning": "Advisers match the vehicle to the client's comfort with custody.", "commonMistake": "Pushing self-custody on a client who fears it.", "mentalModel": "Match the vehicle to the client."}, "invest": {"call": {"kind": "theCall", "situation": "You weigh an ETF against holding bitcoin yourself.", "prompt": "What is the main trade-off?", "options": ["A yearly fee versus managing your own keys", "More coins versus fewer coins", "Legal exposure versus illegal exposure"], "correctIndex": 0, "consequences": ["Funds charge fees; self-custody needs care and skill.", "Both track the same asset.", "Both are legal ways to hold it."], "explanation": "You pay a fund to handle custody, or you handle it yourself for free."}, "proReasoning": "Investors price custody. A fund fee is the cost of not holding keys.", "commonMistake": "Ignoring the custody burden when comparing costs.", "mentalModel": "Fee or responsibility."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your fintech wants to offer bitcoin to customers.", "prompt": "Which path is simplest to launch?", "options": ["Ask customers to email you their private keys", "Offer spot ETF shares through your brokerage", "Build your own custody from scratch"], "correctIndex": 1, "consequences": ["Never handle customer keys by email.", "ETFs plug into existing brokerage rails.", "Custody is hard and heavily regulated."], "explanation": "ETFs turn bitcoin into a security your brokerage already supports."}, "proReasoning": "Founders use existing rails before building custody. It is faster and safer.", "commonMistake": "Building in-house custody before proving customers want the product.", "mentalModel": "Use existing rails first."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if buying a bitcoin ETF means owning bitcoin.", "prompt": "What's the best answer?", "options": ["Yes, the coins go into your wallet", "No, ETFs hold no bitcoin at all", "You own fund shares backed by bitcoin"], "correctIndex": 2, "consequences": ["You never get the coins themselves.", "Spot ETFs hold real bitcoin.", "The fund holds the coins; you hold shares."], "explanation": "You own shares of a fund that holds the bitcoin for you."}, "proReasoning": "You own a slice of a box of bitcoin, not the coins.", "commonMistake": "Thinking ETF shares can be sent like bitcoin.", "mentalModel": "A slice of the box."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9f5f7a82bb53$ml$]::text[]),
($ml$32f3b118-d5f2-57fc-b514-f7daa4d18228$ml$::uuid, $ml$web3$ml$, 9, 1, $ml${"id": "web3-d9-c1", "title": "Metaplanet races to 30,000 bitcoin", "lessonTitle": "The company that owns 4% of bitcoin", "slot": 1, "type": "apply", "brief": {"headline": "On October 1, 2025, Tokyo-listed Metaplanet bought 5,268 BTC for about $616 million, lifting its holdings to 30,823 BTC. Its target was 210,000 BTC by 2027.", "kicker": "Apply day 9: treasury companies raise money to buy bitcoin.", "fullText": "Metaplanet paid an average of $116,870 per coin in that purchase, Bitcoin Magazine reported, and $107,912 per coin across all its holdings. The buy made it the fourth-largest public bitcoin holder.\n\nIts stated goal was 1% of bitcoin's supply, about 210,000 BTC, by 2027. It had raised over ¥500 billion and planned preferred shares to fund future buying.\n\nThrough the day 9 lens: a treasury company turns investor money into bitcoin. Its average cost decides whether its holdings show a gain or a loss.", "sources": [{"url": "https://bitcoinmagazine.com/news/metaplanet-4th-largest-bitcoin-holder-30823-btc", "label": "Bitcoin Magazine, Metaplanet becomes 4th largest bitcoin holder, Oct 2025"}, {"url": "https://theblock.co/news/business/2026-08-10-michael-saylor-strategy-bitcoin-treasury-411237", "label": "The Block, Strategy sells another 1,690 BTC"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about Metaplanet. Tap it.", "statements": ["It held 30,823 BTC after the October purchase.", "Its average cost was about $107,912 per coin.", "It mined all its bitcoin itself."], "fakeIndex": 2, "explanation": "Metaplanet bought its bitcoin with money raised from investors. It is not a miner."}, "numbers": {"kind": "numberSense", "prompt": "Metaplanet aimed to hold about how many thousand BTC by 2027?", "min": 0, "max": 300, "value": 210, "explanation": "About 210,000 BTC, or 1% of supply.", "unit": "K"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at an equity research firm. They ask how to value a bitcoin treasury company.", "prompt": "Which answer lands best?", "options": ["Ignore bitcoin; focus on the logo", "Start from holdings, cost basis and funding plans", "Value it exactly like a bitcoin mining company"], "correctIndex": 1, "consequences": ["The bitcoin is the main asset.", "Those decide gains, losses and dilution.", "It buys coins; it does not mine them."], "explanation": "Holdings, average cost and how purchases are funded drive the story."}, "proReasoning": "Analysts break treasury firms into coins held, cost and funding. Everything else follows.", "commonMistake": "Valuing a treasury company without its average cost per coin.", "mentalModel": "Coins, cost, funding."}, "invest": {"call": {"kind": "theCall", "situation": "You consider buying shares in a bitcoin treasury company.", "prompt": "What risk deserves the most attention?", "options": ["The company's office location", "How often its team posts on social media", "Buying near highs with borrowed or new money"], "correctIndex": 2, "consequences": ["Location matters little here.", "Posts are not a financial risk.", "A high average cost can turn into losses fast."], "explanation": "Metaplanet paid $116,870 per coin in one buy. If bitcoin falls below cost, losses appear."}, "proReasoning": "Investors check the price paid and how it was funded. Those set the downside.", "commonMistake": "Assuming a treasury company always gains when it buys more.", "mentalModel": "Check the price paid."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your company considers putting some cash into bitcoin.", "prompt": "What do you settle first?", "options": ["How much loss the business could absorb", "How fast you can match Metaplanet", "Which logo to put on the announcement"], "correctIndex": 0, "consequences": ["Treasury risk must fit what the business can survive.", "Copying a bigger firm ignores your own limits.", "Marketing comes after risk."], "explanation": "A treasury bet should never threaten operations. Size it to what you can lose."}, "proReasoning": "Founders size treasury bets to their runway, not to headlines.", "commonMistake": "Copying a dedicated treasury company's strategy.", "mentalModel": "Size it to survive."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a hotel company in Japan buys bitcoin.", "prompt": "What's the best answer?", "options": ["It needs bitcoin to pay its hotel staff wages", "It chose to hold bitcoin as its main strategy", "The government ordered it to buy"], "correctIndex": 1, "consequences": ["It pays staff normally.", "It raises money from investors to buy bitcoin.", "No government order is involved."], "explanation": "Metaplanet turned itself into a bitcoin treasury company, buying with investor money."}, "proReasoning": "Some companies become wrappers around a bitcoin stash.", "commonMistake": "Thinking companies buy bitcoin to run daily operations.", "mentalModel": "A company as a bitcoin wrapper."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:148acc483808$ml$]::text[]),
($ml$336ee921-1bc2-59f8-afad-66695ac34a58$ml$::uuid, $ml$web3$ml$, 9, 2, $ml${"id": "web3-d9-c2", "title": "Treasury company or ETF?", "lessonTitle": "The company that owns 4% of bitcoin", "slot": 2, "type": "connect", "brief": {"headline": "In August 2026, Strategy held 840,447 bitcoin, about 4% of supply, at an average cost of $75,385. US spot ETFs held nearly 6% by July 2025.", "kicker": "Connect day 8 and day 9: two ways Wall Street holds bitcoin.", "fullText": "Day 8 showed ETFs: funds that hold bitcoin for investors and charge a fee. Day 9 showed treasury companies: firms that raise money and buy bitcoin for their own balance sheet.\n\nStrategy held 840,447 bitcoin in August 2026 and faced paper losses of about $8.7 billion with bitcoin below its cost. It began selling some coins to fund dividends, interest and buybacks. An ETF must hold the coins its shares represent. A company can borrow, sell or buy as its strategy demands.", "sources": [{"url": "https://theblock.co/news/business/2026-08-10-michael-saylor-strategy-bitcoin-treasury-411237", "label": "The Block, Strategy sells another 1,690 BTC"}, {"url": "https://www.theblock.co/amp/post/361525/blackrocks-spot-bitcoin-etf-ibit-surpasses-700000-btc-assets-under-management", "label": "The Block, BlackRock's IBIT surpasses 700,000 BTC"}]}, "evidence": {"kind": "faceOff", "prompt": "Which one can borrow money to buy more bitcoin?", "left": {"name": "A treasury company", "note": "Like Strategy"}, "right": {"name": "A spot bitcoin ETF", "note": "Like IBIT"}, "correctIndex": 0, "explanation": "Companies can raise debt and equity. Spot ETFs simply hold the coins behind their shares."}, "numbers": {"kind": "numberSense", "prompt": "About what share of all bitcoin did Strategy hold in August 2026?", "min": 0, "max": 20, "value": 4, "explanation": "About 4%, or 840,447 coins.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A hiring manager asks you to compare Strategy and IBIT.", "prompt": "Which answer lands best?", "options": ["Two identical ways to hold the very same bitcoin", "A miner versus an exchange", "A company that borrows versus a fund holding coins"], "correctIndex": 2, "consequences": ["Their risks are very different.", "Neither mines or runs an exchange.", "One borrows and sells by choice; the other just holds."], "explanation": "Treasury companies add corporate choices like debt. ETFs track the coins they hold."}, "proReasoning": "Good answers name the structural difference: borrowing and choices versus a simple holder.", "commonMistake": "Treating every bitcoin holder as the same kind of investment.", "mentalModel": "Borrowing versus holding."}, "invest": {"call": {"kind": "theCall", "situation": "Bitcoin trades below Strategy's average cost of $75,385.", "prompt": "What risk shows up that an ETF does not have?", "options": ["Pressure to sell coins to meet payouts", "A higher annual management fee", "Losing the coins to a quantum attack"], "correctIndex": 0, "consequences": ["Strategy began selling coins to fund dividends and interest.", "Fees are an ETF feature.", "That risk applies to all holders."], "explanation": "A company with payouts to meet may have to sell. An ETF has no dividends to fund."}, "proReasoning": "Investors watch obligations. Payouts can force sales at bad prices.", "commonMistake": "Assuming a treasury company never has to sell.", "mentalModel": "Obligations force sales."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants to hold bitcoin as a treasury asset.", "prompt": "What does Strategy's 2026 position warn you about?", "options": ["Large holders never face losses", "Fixed payouts can force sales in a downturn", "Buying bitcoin always guarantees profits"], "correctIndex": 1, "consequences": ["Size did not prevent losses.", "Strategy sold coins to fund dividends and interest.", "It faced about $8.7 billion in paper losses."], "explanation": "Funding bitcoin with obligations creates pressure when prices fall."}, "proReasoning": "Founders avoid tying a volatile asset to fixed payments.", "commonMistake": "Promising investors payouts backed by a volatile asset.", "mentalModel": "Avoid fixed payouts on volatile assets."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Strategy started selling some bitcoin.", "prompt": "What's the best answer?", "options": ["Because bitcoin stopped working", "Because the government ordered it to", "To fund dividends, interest and buybacks"], "correctIndex": 2, "consequences": ["The network kept running normally.", "No order forced the sales.", "It had payments to make with bitcoin below its cost."], "explanation": "Strategy has obligations to investors. Selling coins helped pay them."}, "proReasoning": "Big holders have bills too. Sometimes coins pay them.", "commonMistake": "Reading a holder's sale as a flaw in bitcoin.", "mentalModel": "Big holders have bills."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1be3f1076aa6$ml$]::text[]),
($ml$640307fd-d4cc-50b2-97ce-7ca90d0585ab$ml$::uuid, $ml$web3$ml$, 9, 3, $ml${"id": "web3-d9-c3", "title": "Your board asks about a bitcoin treasury", "lessonTitle": "The company that owns 4% of bitcoin", "slot": 3, "type": "decide", "brief": {"headline": "You're the CFO of a profitable software company. Strategy paid about $75,385 per bitcoin on average and later showed paper losses of about $8.7 billion.", "kicker": "Decide how much, if any, to put in bitcoin.", "fullText": "A bitcoin treasury company raises money to buy and hold bitcoin. Strategy is the biggest example, with 840,447 coins in August 2026. It paid about $63.4 billion in total.\n\nWith bitcoin well below its cost, it faced paper losses of about $8.7 billion and began selling some coins. Your board wants to know if a small allocation makes sense, and how to size it.", "sources": [{"url": "https://theblock.co/news/business/2026-08-10-michael-saylor-strategy-bitcoin-treasury-411237", "label": "The Block, Strategy sells another 1,690 BTC"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this support a small allocation or argue against it?", "buckets": ["Supports", "Against"], "items": [{"text": "Cash needs for two years are already covered", "bucket": 0}, {"text": "The board accepts large price swings", "bucket": 0}, {"text": "Payroll depends on the same cash", "bucket": 1}, {"text": "The plan needs borrowing to buy", "bucket": 1}, {"text": "No one can explain custody yet", "bucket": 1}], "explanation": "Only spare cash, a clear risk appetite and a custody plan support it."}, "numbers": {"kind": "numberSense", "prompt": "About how many billion dollars in paper losses did Strategy face in August 2026?", "min": 0, "max": 20, "value": 8.7, "explanation": "About $8.7 billion, with bitcoin below its average cost.", "unit": "B"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a finance analyst asked to draft the treasury proposal.", "prompt": "What do you put first?", "options": ["A cap sized to cash the business can spare", "A plan to buy as much as Strategy", "A forecast that bitcoin will double soon"], "correctIndex": 0, "consequences": ["It protects operations from price swings.", "Strategy's scale brought large paper losses.", "Forecasts are not a risk plan."], "explanation": "Size first, upside second. The business must survive the worst case."}, "proReasoning": "Analysts lead with downside limits. Boards approve plans that protect operations.", "commonMistake": "Leading a treasury proposal with a price target.", "mentalModel": "Downside first."}, "invest": {"call": {"kind": "theCall", "situation": "A board member argues bitcoin will protect the company's value.", "prompt": "What is the balanced reply?", "options": ["It always beats cash", "It can swing below cost, as Strategy showed", "It can never lose value over any period"], "correctIndex": 1, "consequences": ["Cash is stable; bitcoin is not.", "Strategy faced $8.7 billion in paper losses.", "Prices fall as well as rise."], "explanation": "Bitcoin's price can fall far below what you paid. Plan for that."}, "proReasoning": "Investors present both sides to a board. Losses are part of the record.", "commonMistake": "Presenting bitcoin as a guaranteed store of value.", "mentalModel": "Show the downside."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup has 18 months of runway in cash.", "prompt": "Which treasury choice fits best?", "options": ["Put half the runway in bitcoin", "Borrow to buy bitcoin for the balance sheet", "Keep runway in cash; skip or keep bitcoin tiny"], "correctIndex": 2, "consequences": ["A drop could cut your runway in half.", "Debt plus volatility can sink a startup.", "Runway pays salaries; it should not swing with prices."], "explanation": "Runway funds the plan. Volatile assets put that plan at risk."}, "proReasoning": "Founders protect runway above all. Treasury bets come from true spare cash.", "commonMistake": "Treating runway as investable spare cash.", "mentalModel": "Protect the runway."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if companies should all copy Strategy.", "prompt": "What's the best answer?", "options": ["Only with spare cash they can afford to lose", "Yes, every company should buy bitcoin now", "No company has ever bought bitcoin"], "correctIndex": 0, "consequences": ["Big holdings brought big paper losses too.", "It is risky for firms needing their cash.", "Many companies hold bitcoin."], "explanation": "It can work for some, but losses are real. Most firms need their cash to operate."}, "proReasoning": "A bold strategy for one company is not a rule for all.", "commonMistake": "Assuming what works for a dedicated holder works for everyone.", "mentalModel": "Not a rule for all."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:96b0c5dd9f2d$ml$]::text[]),
($ml$a4a4bb7c-b766-5701-86d2-6e129db4416c$ml$::uuid, $ml$web3$ml$, 10, 1, $ml${"id": "web3-d10-c1", "title": "A bitcoin miner signs with Microsoft", "lessonTitle": "What it costs to mine one bitcoin", "slot": 1, "type": "apply", "brief": {"headline": "On November 3, 2025, bitcoin miner IREN signed a five-year, $9.7 billion AI cloud contract with Microsoft. Its shares rose nearly 30% at one point that morning.", "kicker": "Apply day 10: when margins tighten, miners sell power to AI.", "fullText": "IREN will provide Microsoft with Nvidia GB300 GPUs at its 750 megawatt campus in Childress, Texas, The Block reported. Microsoft prepays 20%. IREN also placed a separate $5.8 billion order with Dell for the equipment.\n\nMiners already own what AI data centers need most: power contracts, land and cooling. When bitcoin's price falls toward the cost of mining, renting that power to AI firms can pay more.\n\nThrough the day 10 lens: profit is the gap between the coin's price and the cost of power. AI deals change what that power earns.", "sources": [{"url": "https://www.theblock.co/news/deals/2025-11-03-iren-shares-surge-bitcoin-miner-9-7-billion-usd-ai-cloud-deal-microsoft-377255", "label": "The Block, IREN inks $9.7 billion AI cloud deal with Microsoft, Nov 2025"}, {"url": "https://news.bitcoin.com/bitcoin-mining-margins-tighten-as-ai-pivot-accelerates-coinshares-says", "label": "Bitcoin.com News, mining margins tighten as AI pivot accelerates"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why could a bitcoin miner win an AI cloud contract?", "options": ["It already has power, land and cooling", "AI models run on bitcoin", "Microsoft pays for it in bitcoin"], "correctIndex": 0, "explanation": "Miners control power and sites, the scarce inputs for AI data centers."}, "numbers": {"kind": "numberSense", "prompt": "How many billion dollars was IREN's contract with Microsoft?", "min": 0, "max": 25, "value": 9.7, "explanation": "$9.7 billion over five years, with 20% prepaid.", "unit": "B"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a mining company. They ask why miners chase AI deals.", "prompt": "Which answer lands best?", "options": ["Bitcoin mining has been banned in the US", "AI deals let them mine far more bitcoin each day", "Power is their key asset, and AI pays well for it"], "correctIndex": 2, "consequences": ["Mining remains legal in the US.", "The power goes to AI, not mining.", "IREN rented its Texas power to Microsoft."], "explanation": "Miners hold scarce power contracts. AI companies will pay well for that capacity."}, "proReasoning": "Mining people think in megawatts. The best use of power can change.", "commonMistake": "Seeing AI deals as unrelated to mining economics.", "mentalModel": "Sell power to the best buyer."}, "invest": {"call": {"kind": "theCall", "situation": "A miner announces a large AI contract and its stock jumps.", "prompt": "What should you check next?", "options": ["Contract length, prepayment and equipment costs", "How many bitcoin it happened to mine last week", "Whether its logo changed"], "correctIndex": 0, "consequences": ["IREN had five years, 20% prepaid, and a $5.8 billion Dell order.", "Mining output matters less here.", "Branding does not change cash flows."], "explanation": "Big contracts come with big spending. The terms decide how much value remains."}, "proReasoning": "Investors read the terms behind the headline number.", "commonMistake": "Valuing a contract by its headline size alone.", "mentalModel": "Read the terms."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your mining startup controls a cheap 50 megawatt site.", "prompt": "What should you explore as margins tighten?", "options": ["Shutting down without any plan", "Renting part of the power to AI computing", "Buying more old miners on borrowed credit"], "correctIndex": 1, "consequences": ["A cheap site has other uses.", "AI buyers may pay more per megawatt than mining.", "Old machines earn less as hashprice falls."], "explanation": "Power is the asset. If AI pays more per megawatt, mining is not the only option."}, "proReasoning": "Founders in mining value their sites by their best use, not habit.", "commonMistake": "Assuming a mining site can only ever mine.", "mentalModel": "Value the site by its best use."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a bitcoin company is building AI computers.", "prompt": "What's the best answer?", "options": ["Bitcoin and AI are really the same technology", "AI computers mine bitcoin faster", "It already has the power AI data centers need"], "correctIndex": 2, "consequences": ["They are very different technologies.", "The GPUs serve AI customers, not mining.", "Power and cooling are the scarce inputs for both."], "explanation": "Mining and AI both need huge amounts of power. Miners already have it."}, "proReasoning": "Both businesses run on electricity. Whoever has it can choose.", "commonMistake": "Thinking the move means bitcoin itself changed.", "mentalModel": "Both run on power."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3f1080783eff$ml$]::text[]),
($ml$fbd3a357-1116-5b86-8fc6-66da081cd892$ml$::uuid, $ml$web3$ml$, 10, 2, $ml${"id": "web3-d10-c2", "title": "The halving meets the power bill", "lessonTitle": "What it costs to mine one bitcoin", "slot": 2, "type": "connect", "brief": {"headline": "CoinShares put public miners' cash cost at about $79,995 per bitcoin in late 2025. The 2024 halving had already cut the reward per block to 3.125 BTC.", "kicker": "Connect day 2 and day 10: halvings raise the cost of each coin.", "fullText": "Day 2 showed the halving: in April 2024, each block's reward fell from 6.25 to 3.125 BTC. Day 10 showed what that does to costs.\n\nThe same machines and power now earn half as many new coins, so the cost to produce each bitcoin roughly doubles overnight. CoinShares estimated public miners spent about $79,995 in cash per bitcoin in Q4 2025. When bitcoin fell from about $124,500 to about $86,000, margins shrank fast.", "sources": [{"url": "https://news.bitcoin.com/bitcoin-mining-margins-tighten-as-ai-pivot-accelerates-coinshares-says", "label": "Bitcoin.com News, mining margins tighten as AI pivot accelerates"}, {"url": "https://www.benzinga.com/money/what-is-bitcoin-halving", "label": "Benzinga, Bitcoin halving explained"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow the halving through a miner's costs.", "steps": ["The block reward halves", "Each machine earns half the new coins", "Power and costs stay the same", "Cost per bitcoin roughly doubles", "A price drop squeezes margins hard"], "explanation": "Halvings double the cost per coin unless efficiency or price rises."}, "numbers": {"kind": "numberSense", "prompt": "About how many thousand dollars did public miners spend in cash per bitcoin in Q4 2025?", "min": 0, "max": 150, "value": 80, "explanation": "About $80,000, or $79,995, per CoinShares.", "unit": "K"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager at a mining firm asks why costs per coin jumped in 2024.", "prompt": "What is the clearest answer?", "options": ["The halving cut coins earned for the same costs", "Electricity prices doubled everywhere at once", "Bitcoin's supply cap was raised"], "correctIndex": 0, "consequences": ["Half the reward with the same bills doubles cost per coin.", "Power prices did not double everywhere.", "The cap stayed at 21 million."], "explanation": "Costs stayed while rewards halved. Cost per coin rose for every miner."}, "proReasoning": "Mining analysts link cost per coin to the reward schedule first.", "commonMistake": "Blaming rising costs only on electricity.", "mentalModel": "Same bills, half the coins."}, "invest": {"call": {"kind": "theCall", "situation": "Bitcoin trades at $86,000 and cash costs sit near $80,000.", "prompt": "What does that tell you about miners?", "options": ["Costs no longer matter to any of the miners", "Margins are thin, so weak miners are at risk", "Miners are making record profits"], "correctIndex": 1, "consequences": ["Costs decide who survives.", "A small price drop could push costs above price.", "The gap is narrow, not wide."], "explanation": "When price nears cost, high-cost miners struggle first."}, "proReasoning": "Investors compare price to cost per coin. The gap is the margin of safety.", "commonMistake": "Ignoring costs when bitcoin's price looks high.", "mentalModel": "Watch the gap."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your mining startup plans for the next halving.", "prompt": "What must improve to stay profitable?", "options": ["The number of social media followers", "The size of the head office", "Efficiency and power cost per coin"], "correctIndex": 2, "consequences": ["Followers do not lower costs.", "Office space adds cost.", "Those decide cost per coin after rewards halve again."], "explanation": "Each halving raises cost per coin. Efficiency and cheap power are the defense."}, "proReasoning": "Founders plan the next halving now. It is a known cost shock.", "commonMistake": "Waiting for price to rise instead of cutting costs.", "mentalModel": "Get cheaper per coin."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why mining got harder after 2024.", "prompt": "What's the best answer?", "options": ["The reward per block was cut in half", "Computers got slower that year", "Bitcoin started charging miners fees"], "correctIndex": 0, "consequences": ["Same work, half the new coins.", "Machines kept getting faster.", "Miners earn fees; they do not pay them."], "explanation": "The halving cut what miners earn per block. Costs stayed."}, "proReasoning": "Half the pay for the same work makes any job harder.", "commonMistake": "Thinking mining got harder for technical reasons alone.", "mentalModel": "Half the pay, same work."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:eb61cca8e5ed$ml$]::text[]),
($ml$fbf9dc3d-e215-5116-a0df-7e06511a8fbd$ml$::uuid, $ml$web3$ml$, 10, 3, $ml${"id": "web3-d10-c3", "title": "Keep mining or switch off?", "lessonTitle": "What it costs to mine one bitcoin", "slot": 3, "type": "decide", "brief": {"headline": "You run a mine. Hashprice fell to about $29 per petahash per day in early 2026, and CoinShares said some miners may earn up to 70% of revenue from AI by late 2026.", "kicker": "Decide what to do with your machines and your power.", "fullText": "Hashprice is what miners expect to earn per unit of computing power each day. In early 2026 it fell to about $29 per petahash, CoinShares said. Bitcoin had dropped from about $124,500 in October 2025 to about $86,000 by late December.\n\nMiners announced over $70 billion in AI and computing contracts. You must choose whether to keep mining, upgrade, or move power to other uses.", "sources": [{"url": "https://news.bitcoin.com/bitcoin-mining-margins-tighten-as-ai-pivot-accelerates-coinshares-says", "label": "Bitcoin.com News, mining margins tighten as AI pivot accelerates"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this help or hurt your mining profit?", "buckets": ["Helps", "Hurts"], "items": [{"text": "Bitcoin's price rises", "bucket": 0}, {"text": "Your power gets cheaper", "bucket": 0}, {"text": "Hashprice falls", "bucket": 1}, {"text": "The next halving arrives", "bucket": 1}, {"text": "Network hashrate jumps", "bucket": 1}], "explanation": "Price and cheap power help. Falling hashprice, halvings and more competition hurt."}, "numbers": {"kind": "numberSense", "prompt": "About how many dollars per petahash per day was hashprice in early 2026?", "min": 0, "max": 100, "value": 29, "explanation": "About $29. Lower hashprice means less revenue for the same machines.", "unit": "$"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your mine's new analyst is asked what to do as hashprice falls.", "prompt": "What do you recommend first?", "options": ["Buy more machines on credit right away", "Compare each machine's earnings to its power cost", "Run every machine at full power regardless of cost"], "correctIndex": 1, "consequences": ["Debt in a downturn adds risk.", "Machines that cost more than they earn should change roles.", "Unprofitable machines burn cash."], "explanation": "Profit is price minus power. Check each machine against that line."}, "proReasoning": "Analysts rank machines by margin. The worst ones switch off first.", "commonMistake": "Treating every machine as equally worth running.", "mentalModel": "Rank machines by margin."}, "invest": {"call": {"kind": "theCall", "situation": "Two miners face the same hashprice. One has AI contracts.", "prompt": "Which is less exposed to falling bitcoin prices?", "options": ["The one with only mining revenue", "Both are exposed the same", "The one with AI contract revenue"], "correctIndex": 2, "consequences": ["Pure miners ride every price drop.", "Revenue mix changes the exposure.", "Contracted AI revenue does not move with bitcoin."], "explanation": "Diversified revenue cushions price drops. AI deals add steadier income."}, "proReasoning": "Investors look at revenue mix. Contracts add stability.", "commonMistake": "Assuming all miners move with bitcoin's price equally.", "mentalModel": "Revenue mix matters."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your mine has spare power and older machines.", "prompt": "Which plan fits a low hashprice?", "options": ["Retire the worst machines, pursue other power buyers", "Keep everything running and simply hope prices rise", "Sell the site to the first bidder"], "correctIndex": 0, "consequences": ["You cut losses and look for better uses of power.", "Hope does not pay the power bill.", "A rushed sale may undervalue the site."], "explanation": "Power is your asset. Put it where it earns the most."}, "proReasoning": "Founders treat power as inventory and sell it to the highest payer.", "commonMistake": "Running losing machines out of habit.", "mentalModel": "Power to the best use."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what \"hashprice\" means.", "prompt": "What's the best answer?", "options": ["The fee to send a transaction", "What miners earn daily per unit of computing power", "The market price of one bitcoin, in US dollars"], "correctIndex": 1, "consequences": ["Fees are only part of revenue.", "It measures mining revenue for each petahash.", "Bitcoin's price is one input to it."], "explanation": "Hashprice is revenue per unit of computing power per day."}, "proReasoning": "It is a miner's paycheck per unit of work.", "commonMistake": "Thinking hashprice is the same as bitcoin's price.", "mentalModel": "Pay per unit of work."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6315fb7440d0$ml$]::text[]),
($ml$55f6d3fe-7524-5cd8-97e3-a239f4e1ca82$ml$::uuid, $ml$web3$ml$, 11, 1, $ml${"id": "web3-d11-c1", "title": "Texas buys bitcoin through a fund", "lessonTitle": "The bitcoin reserve that cannot sell", "slot": 1, "type": "apply", "brief": {"headline": "Texas reportedly made its first purchase for a state bitcoin reserve on November 20, 2025: about $5 million of BlackRock's IBIT, out of a $10 million budget.", "kicker": "Apply day 11: read how a reserve is funded and held.", "fullText": "Texas Governor Greg Abbott signed SB 21 in June 2025, creating a state bitcoin reserve with a $10 million allocation, The Block reported. On November 20, the state reportedly bought about $5 million of IBIT, a spot bitcoin ETF. The Texas Treasury Safekeeping Trust Company runs the reserve.\n\nThat differs from the federal reserve, which holds bitcoin seized in forfeiture cases and may grow only through budget-neutral strategies.\n\nThrough the day 11 lens: the headline says reserve, but the funding and holding rules tell you what it really is.", "sources": [{"url": "https://www.theblock.co/news/markets/2025-11-25-texas-reportedly-kicks-off-state-bitcoin-reserve-5-million-ibit-purchase-380466", "label": "The Block, Texas reportedly kicks off state bitcoin reserve with $5 million IBIT purchase, Nov 2025"}, {"url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-establishes-the-strategic-bitcoin-reserve-and-u-s-digital-asset-stockpile/", "label": "The White House, fact sheet on the Strategic Bitcoin Reserve"}, {"url": "https://www.theblock.co/amp/post/361525/blackrocks-spot-bitcoin-etf-ibit-surpasses-700000-btc-assets-under-management", "label": "The Block, BlackRock's IBIT surpasses 700,000 BTC"}]}, "evidence": {"kind": "faceOff", "prompt": "How was the Texas reserve's first purchase funded?", "left": {"name": "State budget money", "note": "A $10 million allocation"}, "right": {"name": "Seized bitcoin", "note": "Forfeiture cases"}, "correctIndex": 0, "explanation": "Texas used budget money. The federal reserve starts with forfeited bitcoin."}, "numbers": {"kind": "numberSense", "prompt": "About how many million dollars did Texas reportedly put into IBIT first?", "min": 0, "max": 20, "value": 5, "explanation": "About $5 million, half of its $10 million allocation.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a public finance consultancy. They ask how Texas and the US reserves differ.", "prompt": "Which answer lands best?", "options": ["Texas used budget money; the US uses seized coins", "They are identical programs", "Texas mines all of its own bitcoin at state sites"], "correctIndex": 0, "consequences": ["Funding source is the key difference.", "Their funding and holdings differ.", "Texas bought fund shares."], "explanation": "One spends appropriated money; the other holds forfeited coins and must stay budget neutral."}, "proReasoning": "Policy analysts compare funding rules first. Headlines call both reserves.", "commonMistake": "Treating every government bitcoin reserve as the same thing.", "mentalModel": "Compare the funding."}, "invest": {"call": {"kind": "theCall", "situation": "You read that Texas bought bitcoin through an ETF instead of holding coins.", "prompt": "What does that choice mean?", "options": ["It created a new type of coin", "It holds fund shares, not keys to coins", "It owns more bitcoin than any fund"], "correctIndex": 1, "consequences": ["No new coin was created.", "The ETF holds the coins; Texas holds shares.", "Its $5 million is small next to ETFs."], "explanation": "An ETF lets the state get exposure without running custody. It holds shares, not coins."}, "proReasoning": "Investors note the vehicle. Shares and coins carry different risks.", "commonMistake": "Assuming \"reserve\" always means coins in a state wallet.", "mentalModel": "Note the vehicle."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup pitches custody services to state governments.", "prompt": "What did Texas's first move tell you?", "options": ["Every state wants raw coins in its own wallet now", "States need no custody at all", "Some states start with ETFs before self-custody"], "correctIndex": 2, "consequences": ["Texas did not start with coins.", "Holdings still need safe custody.", "Texas chose IBIT for its first purchase."], "explanation": "Texas went through a fund first. Custody pitches must offer a path from there."}, "proReasoning": "Founders meet buyers where they start. Here, that was an ETF.", "commonMistake": "Pitching complex custody to a buyer starting with fund shares.", "mentalModel": "Meet buyers where they start."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if Texas now owns bitcoin.", "prompt": "What's the best answer?", "options": ["It owns ETF shares backed by bitcoin", "Yes, it mined all of its own coins", "No, it only passed a law"], "correctIndex": 0, "consequences": ["It reportedly bought about $5 million of IBIT.", "Texas did not mine any coins.", "It also reportedly made a purchase."], "explanation": "Texas bought shares of a fund that holds bitcoin, reportedly about $5 million."}, "proReasoning": "It owns a slice of a bitcoin fund, like many investors.", "commonMistake": "Thinking a state reserve must hold coins directly.", "mentalModel": "A slice of a fund."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c2635aecdcb5$ml$]::text[]),
($ml$a48204e3-c141-564c-bd7e-1e82e07394f6$ml$::uuid, $ml$web3$ml$, 11, 2, $ml${"id": "web3-d11-c2", "title": "A reserve that holds, a company that sells", "lessonTitle": "The bitcoin reserve that cannot sell", "slot": 2, "type": "connect", "brief": {"headline": "The US Strategic Bitcoin Reserve, created in March 2025, is barred from selling. Strategy, the largest corporate holder, began selling some bitcoin in 2026.", "kicker": "Connect day 9 and day 11: who is allowed to sell decides the risk.", "fullText": "Day 11 showed the federal reserve: bitcoin from forfeiture cases that the US will not sell. Treasury and Commerce may add more only through budget-neutral strategies. Day 9 showed Strategy, which held about 4% of all bitcoin but started selling coins to fund dividends, interest and buybacks.\n\nBoth are huge holders. One has a rule against selling. The other has bills to pay. The difference shapes how each could affect the market.", "sources": [{"url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-establishes-the-strategic-bitcoin-reserve-and-u-s-digital-asset-stockpile/", "label": "The White House, fact sheet on the Strategic Bitcoin Reserve"}, {"url": "https://theblock.co/news/business/2026-08-10-michael-saylor-strategy-bitcoin-treasury-411237", "label": "The Block, Strategy sells another 1,690 BTC"}]}, "evidence": {"kind": "faceOff", "prompt": "Which holder is barred from selling its bitcoin?", "left": {"name": "The US Strategic Bitcoin Reserve", "note": "Funded by forfeitures"}, "right": {"name": "Strategy", "note": "Funded by investors"}, "correctIndex": 0, "explanation": "The executive order says the US will not sell reserve bitcoin."}, "numbers": {"kind": "numberSense", "prompt": "In early August 2026, Strategy sold bitcoin for about how many million dollars?", "min": 0, "max": 300, "value": 109, "explanation": "About $108.6 million, for 1,690 coins, to help fund payouts.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks which big holder is more likely to sell in a downturn.", "prompt": "Which answer lands best?", "options": ["Neither could ever sell", "Strategy, since it has payouts to fund", "The US reserve, since governments need cash"], "correctIndex": 1, "consequences": ["Strategy did sell some coins.", "Strategy already sold coins to pay obligations.", "The order bars selling reserve bitcoin."], "explanation": "Rules and obligations decide who sells. Strategy has bills; the reserve has a ban."}, "proReasoning": "Strong answers compare constraints, not just sizes.", "commonMistake": "Ranking holders by size without asking who can sell.", "mentalModel": "Constraints decide selling."}, "invest": {"call": {"kind": "theCall", "situation": "You weigh which large holders could add selling pressure.", "prompt": "What matters most?", "options": ["Which holder has the best logo", "Who bought their coins first", "Each holder's rules and obligations"], "correctIndex": 2, "consequences": ["Branding has no effect on selling.", "Timing of purchases does not bind them.", "A ban stops selling; debts can force it."], "explanation": "Holders with obligations may sell. Holders with bans may not."}, "proReasoning": "Investors map who can and must sell. That is where supply surprises come from.", "commonMistake": "Assuming all big holders behave the same in a downturn.", "mentalModel": "Map who must sell."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup tracks big bitcoin holders for clients.", "prompt": "What should your dashboard show for each?", "options": ["Holdings plus selling rules and obligations", "Holdings only, nothing else", "The holder's latest social media posts"], "correctIndex": 0, "consequences": ["Rules and debts tell clients who might sell.", "Size alone misses the key risk.", "Posts are not commitments."], "explanation": "Clients need to know who can sell. Rules and obligations answer that."}, "proReasoning": "Founders add the context that changes decisions, not just raw totals.", "commonMistake": "Showing size without the constraints behind it.", "mentalModel": "Show who can sell."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if the US government will dump its bitcoin.", "prompt": "What's the best answer?", "options": ["The government owns no bitcoin of any kind", "The order says reserve bitcoin will not be sold", "Yes, it sells every year"], "correctIndex": 1, "consequences": ["It holds forfeited bitcoin.", "The March 2025 order bars selling reserve coins.", "Selling reserve bitcoin is barred."], "explanation": "The executive order treats the bitcoin as a reserve asset that will not be sold."}, "proReasoning": "This reserve is built to hold, not trade.", "commonMistake": "Assuming government holdings will be sold off.", "mentalModel": "Built to hold."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:be7e593bcf19$ml$]::text[]),
($ml$00c8e34e-c987-5e6a-abe2-f36f291c5e15$ml$::uuid, $ml$web3$ml$, 11, 3, $ml${"id": "web3-d11-c3", "title": "Reading the reserve order before reacting", "lessonTitle": "The bitcoin reserve that cannot sell", "slot": 3, "type": "decide", "brief": {"headline": "A headline says the US will buy bitcoin for a reserve. The March 2025 order says purchases must be budget-neutral, at no extra cost to taxpayers.", "kicker": "Decide how to read crypto policy before reacting.", "fullText": "The executive order created a Strategic Bitcoin Reserve funded with bitcoin seized in forfeiture cases. The US will not sell those coins. Treasury and Commerce may acquire more only through budget-neutral strategies.\n\nOther seized crypto goes into a separate Digital Asset Stockpile, which Treasury may sell. Headlines often skip these details. The funding rules decide what the order can actually do.", "sources": [{"url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-establishes-the-strategic-bitcoin-reserve-and-u-s-digital-asset-stockpile/", "label": "The White House, fact sheet on the Strategic Bitcoin Reserve"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is this in the order, or headline spin?", "buckets": ["In the order", "Spin"], "items": [{"text": "Seized bitcoin funds the reserve", "bucket": 0}, {"text": "Reserve bitcoin will not be sold", "bucket": 0}, {"text": "Other coins go to a separate stockpile", "bucket": 0}, {"text": "The US will buy billions in bitcoin daily", "bucket": 1}, {"text": "Taxpayers will fund unlimited purchases", "bucket": 1}], "explanation": "The order limits new buying to budget-neutral strategies. Big-buying headlines go beyond it."}, "numbers": {"kind": "numberSense", "prompt": "The White House said earlier sales of seized bitcoin cost taxpayers over how many billion dollars?", "min": 0, "max": 40, "value": 17, "explanation": "Over $17 billion, which it used to argue for holding instead of selling.", "unit": "B"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks you to brief the team on the reserve order.", "prompt": "What do you lead with?", "options": ["The US is buying unlimited bitcoin now", "The order bans all private bitcoin ownership", "Seized coins, no selling, budget-neutral buying"], "correctIndex": 2, "consequences": ["Buying must be budget-neutral.", "Private ownership is untouched.", "Those three points are what the order does."], "explanation": "Brief from the text: funding, holding, and limits on new buying."}, "proReasoning": "Good briefers quote the rules, not the headlines.", "commonMistake": "Repeating a headline as if it were the policy.", "mentalModel": "Brief from the text."}, "invest": {"call": {"kind": "theCall", "situation": "A post claims the reserve will drive massive government buying.", "prompt": "How do you check it?", "options": ["Read the funding rules in the order", "Trust the post if it has many likes", "Buy first and read later"], "correctIndex": 0, "consequences": ["Budget-neutral limits shape any buying.", "Popularity is not accuracy.", "Acting first risks acting on spin."], "explanation": "The order limits new purchases to budget-neutral strategies. That caps what it can do."}, "proReasoning": "Investors read the primary source before trading on news.", "commonMistake": "Trading on a policy summary you have not checked.", "mentalModel": "Read the source."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup writes policy summaries for crypto investors.", "prompt": "What makes a summary trustworthy?", "options": ["It predicts the price effect", "It quotes funding and holding rules exactly", "It uses bold, exciting headlines on every page"], "correctIndex": 1, "consequences": ["Predictions are not summaries.", "Readers can check the facts against the order.", "Hype erodes trust."], "explanation": "Policy summaries earn trust by matching the text. The funding rules matter most."}, "proReasoning": "Founders in media win on accuracy. Readers return to sources that hold up.", "commonMistake": "Writing summaries that amplify the headline instead of the rules.", "mentalModel": "Match the text."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says the government is \"buying all the bitcoin\".", "prompt": "What's the best answer?", "options": ["Yes, it buys every single coin that it can find", "No, it owns no bitcoin", "It mostly holds seized coins; buying has limits"], "correctIndex": 2, "consequences": ["The order limits purchases.", "It holds forfeited bitcoin.", "New buying must be budget-neutral."], "explanation": "The reserve starts with seized bitcoin. Any new buying must cost taxpayers nothing extra."}, "proReasoning": "Read past the headline to the money rules.", "commonMistake": "Believing a policy headline without its funding details.", "mentalModel": "Follow the money rules."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:39d86f6ccbc4$ml$]::text[]),
($ml$ce3457ec-817a-5c40-ae75-fe949aa63ae8$ml$::uuid, $ml$web3$ml$, 12, 1, $ml${"id": "web3-d12-c1", "title": "A wizard fills almost a whole block", "lessonTitle": "Bitcoin's fight over data", "slot": 1, "type": "apply", "brief": {"headline": "On February 1, 2023, the mining pool Luxor mined a 3.96 MB Bitcoin block, the largest ever, carrying a single Taproot Wizard image inscribed as an NFT.", "kicker": "Apply day 12: what belongs in a block is a live dispute.", "fullText": "Bitcoin blocks can hold up to about 4 MB of data. Luxor's block came in at 3.96 MB, The Block reported, mostly one inscription: a wizard image from the Taproot Wizards project. The transaction paid about $209 in fees.\n\nThe block was valid under Bitcoin's rules. The argument was about whether it should be. Supporters said the space belongs to whoever pays for it. Critics called such data spam that crowds out payments.\n\nThrough the day 12 lens: the rules allow a range of uses. Node operators and miners decide how far to go.", "sources": [{"url": "https://www.theblock.co/news/ecosystems/2023-02-02-luxor-mines-largest-bitcoin-block-ever-contains-taproot-wizard-nft-207986", "label": "The Block, Luxor mines largest Bitcoin block ever, Feb 2023"}, {"url": "https://cointelegraph.com/news/bitcoin-core-v30-controversial-op-return-function-now-live", "label": "Cointelegraph, Bitcoin Core v30 controversial OP_RETURN change now live"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the wizard block. Tap it.", "statements": ["It was about 3.96 MB, the largest yet.", "It was valid under Bitcoin's rules.", "Bitcoin rejected it as an invalid block."], "fakeIndex": 2, "explanation": "The block was valid. The dispute was over whether such data should fill block space."}, "numbers": {"kind": "numberSense", "prompt": "The wizard block came in just under how many MB?", "min": 0, "max": 10, "value": 4, "explanation": "Just under 4 MB: about 3.96 MB, near the block size limit.", "unit": "MB"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a bitcoin infrastructure firm. They ask about the wizard block.", "prompt": "Which answer lands best?", "options": ["A block the whole network refused to ever accept", "Valid by the rules, disputed on whether it should be", "An attack that broke Bitcoin's rules"], "correctIndex": 1, "consequences": ["The network accepted it.", "You separate protocol rules from community norms.", "It followed the rules."], "explanation": "The block was valid. The fight was about norms and the use of scarce space."}, "proReasoning": "Strong candidates separate what the rules allow from what people want.", "commonMistake": "Calling something an attack just because it is unpopular.", "mentalModel": "Valid is not the same as welcome."}, "invest": {"call": {"kind": "theCall", "situation": "A mining pool earns fees by including large data inscriptions.", "prompt": "What should an investor weigh?", "options": ["Whether inscriptions break the rules", "Nothing, fees are always good", "New fee income versus community pushback"], "correctIndex": 2, "consequences": ["Inscriptions are valid under the rules.", "Disputes can affect reputation and policy.", "Fees help miners; backlash can carry costs."], "explanation": "Data uses add fee income for miners but stir debate about Bitcoin's purpose."}, "proReasoning": "Investors weigh revenue against reputation. Both shape a miner's future.", "commonMistake": "Ignoring community norms when counting new revenue.", "mentalModel": "Revenue meets reputation."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants to store files on Bitcoin.", "prompt": "What do you need to plan for?", "options": ["Fees for space, and nodes that may not relay it", "Free unlimited storage forever", "A guarantee that every miner will include it"], "correctIndex": 0, "consequences": ["Block space costs money, and policies vary.", "Space is scarce and paid for.", "Miners and nodes choose what to carry."], "explanation": "Storing data on Bitcoin is possible but contested. Plan for fees and policy differences."}, "proReasoning": "Founders building on contested features plan for pushback and changing policy.", "commonMistake": "Assuming any valid use will always be welcome.", "mentalModel": "Plan for pushback."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how an image ended up inside a Bitcoin block.", "prompt": "What's the best answer?", "options": ["Bitcoin added a special image feature in early 2023 for this", "A transaction carried the image data, and a miner included it", "Hackers broke into Bitcoin's servers"], "correctIndex": 1, "consequences": ["The rules already allowed it.", "Valid transactions can carry data like images.", "Bitcoin has no central servers."], "explanation": "Transactions can carry data. A miner chose to include one carrying the image."}, "proReasoning": "Blocks hold data. Some people use that space for pictures.", "commonMistake": "Thinking Bitcoin was hacked to store images.", "mentalModel": "Blocks hold data."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b3c3cb6b1004$ml$]::text[]),
($ml$0bbd8945-9019-5501-8e9e-e6dce1883143$ml$::uuid, $ml$web3$ml$, 12, 2, $ml${"id": "web3-d12-c2", "title": "Who decides what goes in a block?", "lessonTitle": "Bitcoin's fight over data", "slot": 2, "type": "connect", "brief": {"headline": "In October 2025, Bitcoin Core v30 raised its default OP_RETURN limit from 80 bytes to 100,000. About 21% of nodes ran Bitcoin Knots, which can keep the strict limit.", "kicker": "Connect day 3 and day 12: power over blocks sits in several hands.", "fullText": "Day 3 showed that block producers, the mining pools, decide which transactions enter blocks. Day 12 showed another layer: node operators choose which transactions to relay and keep in their memory pools.\n\nBitcoin Core v30 changed a default policy, not the protocol rules. Operators who disagreed could run Bitcoin Knots instead, and BitRef counted 5,114 Knots nodes, about 21.48%. A change spreads only as far as operators agree to run it.", "sources": [{"url": "https://cointelegraph.com/news/bitcoin-core-v30-controversial-op-return-function-now-live", "label": "Cointelegraph, Bitcoin Core v30 controversial OP_RETURN change now live"}, {"url": "https://b10c.me/blog/015-bitcoin-mining-centralization/", "label": "b10c, Bitcoin mining centralization in 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which software lets operators keep the strict 80-byte limit?", "left": {"name": "Bitcoin Knots", "note": "About 21% of nodes"}, "right": {"name": "Bitcoin Core v30", "note": "Default raised to 100,000 bytes"}, "correctIndex": 0, "explanation": "Knots can keep the old limit. Core v30 raised the default."}, "numbers": {"kind": "numberSense", "prompt": "About what share of Bitcoin nodes ran Knots?", "min": 0, "max": 60, "value": 21, "explanation": "About 21%, or 5,114 nodes, per BitRef.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager at a node hosting firm asks what v30 changed.", "prompt": "What is the precise answer?", "options": ["The 21 million coin supply cap in the code", "Who can mine bitcoin", "A relay policy default, not the protocol rules"], "correctIndex": 2, "consequences": ["Supply rules did not change.", "Mining was unaffected.", "Each operator still chooses what to relay."], "explanation": "v30 changed a default. Protocol rules about valid blocks stayed the same."}, "proReasoning": "Precise engineers separate policy from consensus rules.", "commonMistake": "Describing a policy change as a change to Bitcoin itself.", "mentalModel": "Policy is not protocol."}, "invest": {"call": {"kind": "theCall", "situation": "You read that a fifth of nodes reject a new software default.", "prompt": "What does that show?", "options": ["Change depends on operators choosing to run it", "Bitcoin is about to split into two separate chains", "Developers control every node"], "correctIndex": 0, "consequences": ["Adoption is voluntary, node by node.", "Policy differences do not create a split.", "Operators pick their own software."], "explanation": "Operators decide what to run. Defaults spread only with their consent."}, "proReasoning": "Investors note where real control sits. On Bitcoin, it is spread out.", "commonMistake": "Assuming developers can force changes on the network.", "mentalModel": "Operators choose."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app relies on a certain kind of transaction being relayed.", "prompt": "What should you monitor?", "options": ["Nothing, because relay policy never changes", "Which software and policies nodes and pools run", "Only Bitcoin's price"], "correctIndex": 1, "consequences": ["v30 shows policy does change.", "Relay depends on node and pool choices.", "Price does not change relay policy."], "explanation": "Relay and inclusion depend on operators and pools. Track their policies."}, "proReasoning": "Builders track the software their transactions depend on.", "commonMistake": "Assuming every node treats transactions the same way.", "mentalModel": "Track the policies."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks who is in charge of Bitcoin's rules.", "prompt": "What's the best answer?", "options": ["One company writes and enforces them", "Bitcoin's founder updates them yearly", "The people running nodes choose what to run"], "correctIndex": 2, "consequences": ["No single company controls Bitcoin.", "Satoshi is long gone.", "Software spreads only if operators adopt it."], "explanation": "Developers propose. Node operators and miners decide what to run."}, "proReasoning": "Bitcoin changes when enough people choose to run the change.", "commonMistake": "Thinking a central team can change Bitcoin at will.", "mentalModel": "Change by choice."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7cab26c814aa$ml$]::text[]),
($ml$8e264732-0155-57dd-82d2-1d20793c9b46$ml$::uuid, $ml$web3$ml$, 12, 3, $ml${"id": "web3-d12-c3", "title": "Which node software do you run?", "lessonTitle": "Bitcoin's fight over data", "slot": 3, "type": "decide", "brief": {"headline": "You run Bitcoin nodes for a small exchange. Core v30 relays OP_RETURN data up to 100,000 bytes by default. Knots can keep the strict 80-byte limit.", "kicker": "Decide which relay policy fits your business.", "fullText": "OP_RETURN lets a transaction carry a small piece of extra data. Bitcoin Core v30 raised the default limit from 80 to 100,000 bytes in October 2025. Critics warned of blockchain bloat and legal risk from hosting illegal data. Supporters said more space allows richer applications.\n\nThe change is node policy, not protocol rules. Each operator chooses what to relay. Your choice affects what your nodes carry, not which blocks are valid.", "sources": [{"url": "https://cointelegraph.com/news/bitcoin-core-v30-controversial-op-return-function-now-live", "label": "Cointelegraph, Bitcoin Core v30 controversial OP_RETURN change now live"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this favor Core v30 or Knots?", "buckets": ["Core v30", "Knots"], "items": [{"text": "You want the widely used default software", "bucket": 0}, {"text": "You support richer data applications", "bucket": 0}, {"text": "You worry about relaying unwanted data", "bucket": 1}, {"text": "You want the strict 80-byte limit", "bucket": 1}, {"text": "Your lawyers flag hosting risks", "bucket": 1}], "explanation": "Both accept the same valid blocks. They differ on what they relay."}, "numbers": {"kind": "numberSense", "prompt": "Core v30 raised the default OP_RETURN limit to how many thousand bytes?", "min": 0, "max": 250, "value": 100, "explanation": "100,000 bytes, up from 80.", "unit": "K"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your team asks you to recommend node software for the exchange.", "prompt": "What do you base it on?", "options": ["Our relay needs, legal advice and support", "Whichever has the loudest supporters", "Whichever was released most recently"], "correctIndex": 0, "consequences": ["Fit, risk and maintenance decide it.", "Noise is not a requirement.", "Newest is not always the best fit."], "explanation": "Both follow the same consensus rules. Choose by relay policy, risk and upkeep."}, "proReasoning": "Engineers pick infrastructure by requirements, not by online debates.", "commonMistake": "Choosing node software based on social media sides.", "mentalModel": "Pick by requirements."}, "invest": {"call": {"kind": "theCall", "situation": "An exchange you follow switches its nodes to Knots.", "prompt": "Does that change which blocks it accepts?", "options": ["Yes, it leaves the Bitcoin network", "No, it changes what its nodes relay", "Yes, it rejects Core blocks"], "correctIndex": 1, "consequences": ["It stays on the same network.", "Valid blocks stay valid on both.", "Both accept the same valid blocks."], "explanation": "Policy differs; consensus does not. The exchange stays on the same chain."}, "proReasoning": "Investors separate policy noise from real chain risk.", "commonMistake": "Treating a relay policy switch as a fork.", "mentalModel": "Policy, not a fork."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells hosted nodes.", "prompt": "What should you offer customers?", "options": ["Only one option, no explanation", "A promise that relay policy never really matters", "A choice of software, with policies explained"], "correctIndex": 2, "consequences": ["Some customers need the strict limit.", "v30 shows policy matters to many.", "Operators want to set their own relay policy."], "explanation": "About 21% of nodes chose Knots. Customers want the choice."}, "proReasoning": "Founders serve a split market by offering both, clearly explained.", "commonMistake": "Forcing every customer onto one side of a live debate.", "mentalModel": "Offer the choice."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why people argue about data in Bitcoin blocks.", "prompt": "What's the best answer?", "options": ["Some want payments only; others want richer uses", "Data in blocks makes bitcoin worth less money", "The law bans data on blockchains"], "correctIndex": 0, "consequences": ["It is a debate about what block space is for.", "The debate is about use, not price.", "No such general ban exists."], "explanation": "Block space is scarce. People disagree on whether non-payment data belongs there."}, "proReasoning": "It is an argument about what a shared resource is for.", "commonMistake": "Thinking the debate is purely technical.", "mentalModel": "What is the space for?"}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c7d9e9c1e4f5$ml$]::text[]),
($ml$5a0f9f2a-88e1-5480-b0f2-59dac4d2757f$ml$::uuid, $ml$web3$ml$, 13, 1, $ml${"id": "web3-d13-c1", "title": "A rounding error worth $128 million", "lessonTitle": "Programs that live on a blockchain", "slot": 1, "type": "apply", "brief": {"headline": "On November 3, 2025, an attacker drained about $128 million from Balancer's V2 pools across six blockchains in under 30 minutes, using a tiny rounding error.", "kicker": "Apply day 13: a smart contract does exactly what its code says.", "fullText": "Balancer runs pools of tokens as smart contracts. Check Point Research traced the attack to a rounding error in how certain stable pools scaled numbers. Each rounding was tiny, but the attacker chained dozens of small swaps inside single transactions to push down the price of pool tokens and drain value.\n\nThe flaw persisted despite extensive audits, Check Point said. The total reached about $128.64 million on six networks.\n\nThrough the day 13 lens: once deployed, a contract runs as written. If the math has a gap, anyone who finds it can use it.", "sources": [{"url": "https://research.checkpoint.com/2025/how-an-attacker-drained-128m-from-balancer-through-rounding-error-exploitation/", "label": "Check Point Research, how an attacker drained $128M from Balancer, Nov 2025"}, {"url": "https://ethereum.org/developers/docs/smart-contracts/", "label": "ethereum.org, smart contracts"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the Balancer drain in order.", "steps": ["Pools run as deployed smart contracts", "A tiny rounding error sits in the math", "The attacker chains dozens of small swaps", "Pool token prices are pushed down", "About $128 million is drained"], "explanation": "Nobody broke in. The attacker used the contract exactly as its code allowed."}, "numbers": {"kind": "numberSense", "prompt": "About how many million dollars were drained from Balancer?", "min": 0, "max": 300, "value": 128, "explanation": "About $128 million, across six blockchains, in under 30 minutes.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview for a smart contract auditing role. They ask what Balancer shows.", "prompt": "Which answer lands best?", "options": ["Audited code can never contain a serious bug", "Attackers must steal private keys to drain pools", "Small math errors can be chained into big losses"], "correctIndex": 2, "consequences": ["The flaw survived extensive audits.", "No keys were stolen; the code was used as written.", "Rounding gaps compound when repeated many times."], "explanation": "Rounding errors look harmless alone. Repeated inside one transaction, they drain pools."}, "proReasoning": "Auditors test edge cases like rounding under repetition. That is where big losses hide.", "commonMistake": "Treating an audit report as proof a contract is safe.", "mentalModel": "Small errors compound."}, "invest": {"call": {"kind": "theCall", "situation": "A protocol you hold has been audited several times.", "prompt": "How should you treat that?", "options": ["As helpful, but not proof of safety", "As a promise that funds are fully insured", "As a sign the token will rise in price"], "correctIndex": 0, "consequences": ["Balancer's flaw persisted despite extensive audits.", "Audits are not insurance.", "Audits say nothing about price."], "explanation": "Audits lower risk but cannot remove it. Code with money in it stays a target."}, "proReasoning": "Investors size positions knowing any contract can fail.", "commonMistake": "Putting more money into a protocol just because it was audited.", "mentalModel": "Audited is not invincible."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup is about to deploy a token pool contract.", "prompt": "What do you add before launch?", "options": ["A plan to edit the contract if it breaks", "Tests for rounding and repeated small swaps", "Only a quick review by the founding team"], "correctIndex": 1, "consequences": ["Deployed contracts are hard to change.", "Balancer's loss came from rounding under repetition.", "One review rarely catches subtle math gaps."], "explanation": "Contracts run as written once live. Testing edge cases before deploy is the defense."}, "proReasoning": "Founders treat contract math like bank vault design. Edge cases get tested first.", "commonMistake": "Launching with the plan to patch problems later.", "mentalModel": "Test the edges first."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how someone stole $128 million without hacking anyone.", "prompt": "What's the best answer?", "options": ["They guessed the founders' email passwords", "A bank reversed the payments by mistake", "They used a flaw in the contract's own math"], "correctIndex": 2, "consequences": ["No passwords were involved.", "No bank sits behind these pools.", "The contract followed its code, gap included."], "explanation": "Smart contracts do exactly what the code says. The code had a rounding gap."}, "proReasoning": "It is a vending machine with a coin slot bug. Anyone who finds it can use it.", "commonMistake": "Thinking every crypto theft involves stolen passwords.", "mentalModel": "The code had a gap."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9bcd2cc1d67a$ml$]::text[]),
($ml$bc73a7cb-7092-5098-8d5a-774562162c73$ml$::uuid, $ml$web3$ml$, 13, 2, $ml${"id": "web3-d13-c2", "title": "Code you cannot recall, keys you cannot reset", "lessonTitle": "Programs that live on a blockchain", "slot": 2, "type": "connect", "brief": {"headline": "A deployed Ethereum smart contract runs as programmed and cannot be deleted by default. A lost self-custodied private key usually cannot be reset either.", "kicker": "Connect day 5 and day 13: crypto has few undo buttons.", "fullText": "Day 5 showed that control of the key is control of the money. Lose a self-custodied key, and there is no reset email. Day 13 showed a second kind of permanence: once deployed, a smart contract runs exactly as written and cannot be deleted by default.\n\nBoth remove a middleman who could fix mistakes. That is the point of the design, and also its risk. Users and builders must get things right before they act.", "sources": [{"url": "https://ethereum.org/developers/docs/smart-contracts/", "label": "ethereum.org, smart contracts"}, {"url": "https://www.ic3.gov/PSA/2025/PSA250226", "label": "FBI IC3, Bybit theft alert"}]}, "evidence": {"kind": "sortSignal", "prompt": "Can this usually be undone after the fact?", "buckets": ["Can be undone", "Hard to undo"], "items": [{"text": "A card payment disputed with your bank", "bucket": 0}, {"text": "A password reset by email", "bucket": 0}, {"text": "A self-custodied key that is lost", "bucket": 1}, {"text": "A deployed smart contract's code", "bucket": 1}, {"text": "Funds sent to a contract by mistake", "bucket": 1}], "explanation": "Banks and websites can reverse things. Keys and deployed code usually cannot."}, "numbers": {"kind": "numberSense", "prompt": "Bybit lost about how many billion dollars to stolen keys in February 2025?", "min": 0, "max": 5, "value": 1.5, "explanation": "About $1.5 billion. Like deployed code, a theft through keys is hard to undo.", "unit": "B"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager at a crypto firm asks what makes this industry different from banking.", "prompt": "What is the sharpest answer?", "options": ["Mistakes are often final, so checks come first", "Everything can be reversed by customer support", "Transactions are private and invisible to all"], "correctIndex": 0, "consequences": ["Keys and contracts rarely have undo buttons.", "Most crypto actions cannot be reversed.", "Most blockchains are public."], "explanation": "With no middleman to reverse errors, prevention matters more than recovery."}, "proReasoning": "Crypto professionals design for prevention. Recovery is often impossible.", "commonMistake": "Promising customers reversals that the technology cannot do.", "mentalModel": "Prevent, because you cannot undo."}, "invest": {"call": {"kind": "theCall", "situation": "You weigh a protocol that cannot change its contracts.", "prompt": "What is the trade-off?", "options": ["Nobody can ever use the protocol", "Rules are firm, but bugs are hard to fix", "Bugs are fixed instantly by any user"], "correctIndex": 1, "consequences": ["Immutable contracts still work.", "Immutability builds trust and locks in flaws.", "Fixing deployed code is hard."], "explanation": "Fixed code means no one can change the rules on you, and no one can patch a flaw."}, "proReasoning": "Investors weigh immutability as both a strength and a risk.", "commonMistake": "Seeing immutable code only as a feature.", "mentalModel": "Firm rules, firm bugs."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your wallet startup serves first-time users.", "prompt": "What design choice matters most?", "options": ["Hiding warnings so the app feels faster", "Promising support can undo any transfer", "Clear warnings before irreversible actions"], "correctIndex": 2, "consequences": ["Hidden risk turns into real losses.", "Support cannot reverse on-chain transfers.", "Users need to know a step is final before they take it."], "explanation": "Keys and contracts are unforgiving. Good design makes final steps obvious."}, "proReasoning": "Founders put friction where mistakes are permanent.", "commonMistake": "Designing a crypto app like a bank app with a reverse button.", "mentalModel": "Friction where it is final."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why nobody can \"just fix\" a broken smart contract.", "prompt": "What's the best answer?", "options": ["Deployed code runs as written and stays put", "The company is too lazy to fix it", "Fixes are illegal under crypto law"], "correctIndex": 0, "consequences": ["By default a contract cannot be deleted or edited.", "Often no company controls it.", "No such law exists."], "explanation": "Once on the chain, a contract runs as programmed. That is its strength and weakness."}, "proReasoning": "Think of it as a vending machine welded to the floor.", "commonMistake": "Assuming someone always holds an edit button.", "mentalModel": "Welded to the floor."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a5002a89b431$ml$]::text[]),
($ml$a8ac44dc-bf79-5101-a40d-4602b2e7c6ed$ml$::uuid, $ml$web3$ml$, 13, 3, $ml${"id": "web3-d13-c3", "title": "Should your contract trust one price feed?", "lessonTitle": "Programs that live on a blockchain", "slot": 3, "type": "decide", "brief": {"headline": "You build a lending app on Ethereum. Smart contracts cannot read real-world prices on their own, so they rely on oracles to feed them data.", "kicker": "Decide how your contract gets its prices.", "fullText": "A smart contract is code plus data at an address on Ethereum. It runs exactly as written. By design, it cannot fetch outside data such as asset prices. Oracles bring that data on-chain.\n\nA lending app uses prices to decide when loans are under-collateralized. If the price input is wrong, the contract will act on it anyway. Your choice of price source is a security decision.", "sources": [{"url": "https://ethereum.org/developers/docs/smart-contracts/", "label": "ethereum.org, smart contracts"}, {"url": "https://research.checkpoint.com/2025/how-an-attacker-drained-128m-from-balancer-through-rounding-error-exploitation/", "label": "Check Point Research, how an attacker drained $128M from Balancer, Nov 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this make your price input safer or riskier?", "buckets": ["Safer", "Riskier"], "items": [{"text": "Combining several independent oracles", "bucket": 0}, {"text": "Rejecting sudden extreme price jumps", "bucket": 0}, {"text": "Pausing if feeds disagree widely", "bucket": 0}, {"text": "One thinly traded market as the source", "bucket": 1}, {"text": "Letting anyone post the price", "bucket": 1}], "explanation": "Several sources and sanity checks protect a contract that cannot think for itself."}, "numbers": {"kind": "numberSense", "prompt": "The Balancer attacker drained its pools in under how many minutes?", "min": 0, "max": 120, "value": 30, "explanation": "Under 30 minutes. A contract acts on its inputs and code instantly, with no one to stop it.", "unit": "min"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your team asks you to choose a price source for the lending app.", "prompt": "What do you recommend?", "options": ["Whatever price the borrower types in", "Several independent feeds with sanity checks", "The single cheapest feed we can find today"], "correctIndex": 1, "consequences": ["Borrowers would type prices that suit them.", "No single bad feed can trigger wrong liquidations.", "Cheap and single means one point of failure."], "explanation": "The contract trusts its inputs completely. Make those inputs hard to fake."}, "proReasoning": "Engineers treat oracles as part of the security model, not plumbing.", "commonMistake": "Treating the price feed as a minor integration detail.", "mentalModel": "Inputs are security."}, "invest": {"call": {"kind": "theCall", "situation": "A lending protocol uses one small exchange for its prices.", "prompt": "What risk do you see?", "options": ["No risk, since contracts verify every price", "Only the risk of a slow website", "A moved price on that venue moves the protocol"], "correctIndex": 2, "consequences": ["Contracts cannot verify outside data alone.", "The real risk is bad data.", "Contracts act on whatever price they receive."], "explanation": "A contract cannot tell a manipulated price from a real one. Thin sources invite manipulation."}, "proReasoning": "Investors check where a protocol gets its data. Weak inputs are a hidden risk.", "commonMistake": "Assuming on-chain means every input is trustworthy.", "mentalModel": "Check the inputs."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup must launch the lending app this quarter.", "prompt": "Which plan fits best?", "options": ["Launch with multiple feeds and a pause rule", "Launch on one feed and add more later on", "Skip prices and lend without collateral"], "correctIndex": 0, "consequences": ["Safeguards from day one protect early users.", "A single feed is a target from day one.", "Uncollateralized loans need trust you lack."], "explanation": "The contract will act on bad data instantly. Build the safeguards before launch."}, "proReasoning": "Founders put the guardrails in version one when code runs unattended.", "commonMistake": "Planning to harden a contract after money is already in it.", "mentalModel": "Guardrails in version one."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a blockchain program knows the price of anything.", "prompt": "What's the best answer?", "options": ["It guesses from past transactions", "Oracles feed it data from outside", "It searches the web like a browser"], "correctIndex": 1, "consequences": ["Guessing would make it unreliable.", "Contracts cannot fetch outside data by design.", "Contracts cannot browse the web."], "explanation": "Smart contracts are blind to the outside world. Oracles bring the facts in."}, "proReasoning": "The contract is a calculator. Oracles hand it the numbers.", "commonMistake": "Thinking smart contracts can look things up on their own.", "mentalModel": "Oracles hand it the numbers."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ee7a10bb7d82$ml$]::text[]),
($ml$e5ca452f-3600-5b2f-93eb-92742fcc2b0b$ml$::uuid, $ml$web3$ml$, 14, 1, $ml${"id": "web3-d14-c1", "title": "Circle goes public on reserve income", "lessonTitle": "The $10 billion stablecoin business", "slot": 1, "type": "apply", "brief": {"headline": "Circle, issuer of the USDC stablecoin, listed on the NYSE in June 2025 at $31 a share. The shares closed up 168% from that price on day one.", "kicker": "Apply day 14: a stablecoin issuer earns on its reserves.", "fullText": "Circle raised $1.1 billion at an $18.5 billion valuation, DL News reported. Its shares ended the first day 168% above the $31 listing price and traded above $106 the next morning.\n\nMost of Circle's revenue comes from the reserves backing USDC, largely US Treasury bonds. It recorded almost $558 million in revenue in Q1 2025, up 61% from a year earlier, with about $65 million in net income. USDC held about 24% of the stablecoin market, behind Tether's USDT at over 61%.\n\nThrough the day 14 lens: holders hand over dollars, and the issuer earns interest on what it holds.", "sources": [{"url": "https://www.dlnews.com/articles/snapshot/circle-stock-soars-on-first-day-amid-red-hot-stablecoin-market", "label": "DL News, Circle stock soars on first day, Jun 2025"}, {"url": "https://www.theblock.co/post/387908/tether-rakes-10-billion-net-profit-2025-excess-reserves-6-3-billion", "label": "The Block, Tether earns $10 billion net profit in 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Where does most of Circle's revenue come from?", "options": ["Fees on every USDC payment made", "Selling USDC above one dollar", "Interest on reserves backing USDC"], "correctIndex": 2, "explanation": "Reserves, largely Treasuries, earn interest. That is Circle's main revenue."}, "numbers": {"kind": "numberSense", "prompt": "About what share of the stablecoin market did USDC hold?", "min": 0, "max": 100, "value": 24, "explanation": "About 24%, behind Tether's USDT at over 61%.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a stablecoin company. They ask how the business makes money.", "prompt": "Which answer lands best?", "options": ["Interest on the reserves that back each coin", "Charging users every time they send a coin", "Selling each coin for more than one dollar"], "correctIndex": 0, "consequences": ["Reserves held in Treasuries earn interest.", "Most revenue is not from transfer fees.", "The coin aims to stay at $1."], "explanation": "Users hand over dollars. The issuer invests reserves and keeps the interest."}, "proReasoning": "Strong candidates name reserve income first. It is the engine of the business.", "commonMistake": "Assuming stablecoin issuers profit mainly from transaction fees.", "mentalModel": "Reserves are the engine."}, "invest": {"call": {"kind": "theCall", "situation": "Circle's revenue depends on interest from Treasuries.", "prompt": "What risk follows from that?", "options": ["More users always mean lower profit", "Lower interest rates cut its revenue", "Higher rates make USDC worth less"], "correctIndex": 1, "consequences": ["More coins mean more reserves earning.", "Reserve income moves with short-term rates.", "USDC aims for $1 whatever rates do."], "explanation": "Reserve income rises and falls with rates. Falling rates shrink the main revenue line."}, "proReasoning": "Investors map an issuer's revenue to interest rates. It is the key sensitivity.", "commonMistake": "Valuing a stablecoin issuer without asking what rates will do.", "mentalModel": "Rates drive revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup plans to issue its own dollar stablecoin.", "prompt": "What does Circle's model tell you?", "options": ["Profit comes fast from small transfer fees", "Profit comes from keeping reserves very small", "Profit needs scale, since income is reserve yield"], "correctIndex": 2, "consequences": ["Fees are not the main engine.", "Thin reserves break the one-dollar promise.", "Interest on a small reserve is a small number."], "explanation": "Issuers earn on reserves. Without scale, that income stays small."}, "proReasoning": "Founders model stablecoin income as reserves times rate. Scale is everything.", "commonMistake": "Expecting a new stablecoin to profit before it grows large.", "mentalModel": "Reserves times rate."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a company can earn billions from a coin worth one dollar.", "prompt": "What's the best answer?", "options": ["It invests the dollars behind each coin", "It charges a fee to hold the coin", "It slowly lowers the coin's value"], "correctIndex": 0, "consequences": ["Reserves earn interest while coins stay at $1.", "Holding USDC carries no fee.", "The coin aims to stay at $1."], "explanation": "People hand over dollars for coins. The issuer earns interest on those dollars."}, "proReasoning": "It is like a bank keeping the interest on your deposit.", "commonMistake": "Thinking the issuer profits by changing the coin's price.", "mentalModel": "It keeps the interest."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3954f85b60da$ml$]::text[]),
($ml$853f1b58-ff26-556d-9638-377dbcc9441f$ml$::uuid, $ml$web3$ml$, 14, 2, $ml${"id": "web3-d14-c2", "title": "The issuer's profit, and the code it runs on", "lessonTitle": "The $10 billion stablecoin business", "slot": 2, "type": "connect", "brief": {"headline": "Tether reported over $10 billion in net profit for 2025, with over $186 billion of USDT outstanding. Every USDT moves through smart contracts on public blockchains.", "kicker": "Connect day 13 and day 14: a stablecoin is a contract plus a reserve.", "fullText": "Day 13 showed that a smart contract holds its own code and data at an address and runs as written. Day 14 showed the business behind a stablecoin: users hand over dollars, and the issuer holds reserves such as Treasuries.\n\nA stablecoin needs both. The token itself is a contract that records balances and transfers. The reserve sits off-chain, held by the issuer. Tether reported $193 billion in assets backing about $186 billion of USDT, and about $122 billion in US Treasuries.", "sources": [{"url": "https://www.theblock.co/post/387908/tether-rakes-10-billion-net-profit-2025-excess-reserves-6-3-billion", "label": "The Block, Tether earns $10 billion net profit in 2025"}, {"url": "https://ethereum.org/developers/docs/smart-contracts/", "label": "ethereum.org, smart contracts"}]}, "evidence": {"kind": "faceOff", "prompt": "Where do Tether's Treasuries sit?", "left": {"name": "With the issuer, off-chain", "note": "Held as reserves"}, "right": {"name": "Inside the token contract", "note": "Stored on-chain"}, "correctIndex": 0, "explanation": "The contract tracks USDT balances. The reserves sit off-chain with Tether."}, "numbers": {"kind": "numberSense", "prompt": "About how many billion dollars in US Treasuries did Tether hold at the end of 2025?", "min": 0, "max": 300, "value": 122, "explanation": "About $122 billion, making it one of the largest holders of US debt.", "unit": "B"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks what a stablecoin is, technically and financially.", "prompt": "Which answer lands best?", "options": ["A bank account that lives inside a crypto app", "A token contract on-chain plus reserves held off-chain", "A coin mined by computers just like bitcoin"], "correctIndex": 1, "consequences": ["It is a token, not a bank account.", "The contract moves balances; reserves back value.", "Stablecoins are issued, not mined."], "explanation": "Code records who holds what. Reserves give each token its value."}, "proReasoning": "Strong answers cover both layers. Most people describe only one.", "commonMistake": "Describing a stablecoin as only code or only a reserve.", "mentalModel": "Code plus reserve."}, "invest": {"call": {"kind": "theCall", "situation": "You assess a stablecoin's safety.", "prompt": "What two things do you check?", "options": ["The logo and the founder's social posts", "Only whether it trades at exactly $1 today", "The token contract and the reserve quality"], "correctIndex": 2, "consequences": ["Branding does not protect holders.", "A price today says little about tomorrow.", "Either can fail: code bugs or weak reserves."], "explanation": "A stablecoin can fail through its code or its reserves. Check both."}, "proReasoning": "Investors look at both layers. Each has its own failure mode.", "commonMistake": "Judging a stablecoin by its price on a calm day.", "mentalModel": "Check both layers."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds a payments app on stablecoins.", "prompt": "What should you verify about the coin you pick?", "options": ["How the contract can freeze or block funds", "How many colors its logo uses", "Whether its issuer is the most famous"], "correctIndex": 0, "consequences": ["Contracts can include admin controls affecting your users.", "Design does not affect payments.", "Fame is not a safety check."], "explanation": "The token contract defines what the issuer can do to balances. Know it before you build."}, "proReasoning": "Founders read the contract rules of the coin they depend on.", "commonMistake": "Building on a stablecoin without reading its contract controls.", "mentalModel": "Read the token rules."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks where the money behind a stablecoin actually is.", "prompt": "What's the best answer?", "options": ["Nowhere, it is just code", "With the issuer, mostly in safe assets", "Inside the blockchain itself"], "correctIndex": 1, "consequences": ["Reserves back the coins.", "Tether held about $122 billion in Treasuries.", "The chain tracks balances, not dollars."], "explanation": "The token lives on the chain. The dollars behind it sit with the issuer."}, "proReasoning": "The coin is a receipt on-chain. The money is in the issuer's accounts.", "commonMistake": "Thinking dollars are stored inside the blockchain.", "mentalModel": "Receipt on-chain, money off-chain."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:acd05584bdbc$ml$]::text[]),
($ml$643dc2e9-0dd1-577e-b639-610e6bf4b050$ml$::uuid, $ml$web3$ml$, 14, 3, $ml${"id": "web3-d14-c3", "title": "Holding USDT for a business", "lessonTitle": "The $10 billion stablecoin business", "slot": 3, "type": "decide", "brief": {"headline": "Your company receives USDT from overseas customers. Tether reported $193 billion in assets against about $186 billion of USDT, including about 140 tons of gold.", "kicker": "Decide what to check before holding a stablecoin balance.", "fullText": "A stablecoin aims to stay worth one dollar. USDT reached a record of over $186 billion in circulation, and Tether reported $193 billion in assets, about $6.3 billion more than needed. It held about $122 billion in US Treasuries and about 140 tons of gold.\n\nYour finance team must decide how much USDT to hold and for how long. The reserves are both the coin's safety and the issuer's profit engine.", "sources": [{"url": "https://www.theblock.co/post/387908/tether-rakes-10-billion-net-profit-2025-excess-reserves-6-3-billion", "label": "The Block, Tether earns $10 billion net profit in 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this reduce or add to your risk holding USDT?", "buckets": ["Reduces", "Adds"], "items": [{"text": "Converting to dollars soon after receipt", "bucket": 0}, {"text": "Capping the balance you keep", "bucket": 0}, {"text": "Reading the issuer's reserve reports", "bucket": 0}, {"text": "Holding all your cash in one stablecoin", "bucket": 1}, {"text": "Ignoring what backs the coin", "bucket": 1}], "explanation": "Short holding periods, caps and reading reserves keep stablecoin risk in check."}, "numbers": {"kind": "numberSense", "prompt": "About how many billion dollars more in assets than USDT did Tether report?", "min": 0, "max": 20, "value": 6.3, "explanation": "About $6.3 billion: $193 billion in assets for about $186 billion of USDT.", "unit": "B"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a finance analyst. Customers pay in USDT and the CFO asks for a policy.", "prompt": "What do you propose?", "options": ["Hold every coin forever as long-term savings", "Refuse every USDT payment from customers", "Cap balances and convert to dollars on a schedule"], "correctIndex": 2, "consequences": ["Long holding piles up issuer risk.", "Refusing loses customers who pay this way.", "You keep the sales and limit exposure."], "explanation": "A stablecoin is only as good as its issuer. Caps and conversion limit that exposure."}, "proReasoning": "Finance teams treat stablecoins like cash at one institution. They cap it.", "commonMistake": "Treating a stablecoin balance like insured bank cash.", "mentalModel": "Cap and convert."}, "invest": {"call": {"kind": "theCall", "situation": "You see Tether holds both Treasuries and gold.", "prompt": "What does the gold tell you?", "options": ["Some reserves can swing in value", "The coin is worth more than $1", "Gold is the same as Treasuries"], "correctIndex": 0, "consequences": ["Gold prices move; Treasuries are steadier.", "USDT aims for $1 regardless.", "They carry different risks."], "explanation": "Not all reserves are equally steady. Gold adds price risk to the backing."}, "proReasoning": "Investors read the reserve mix, not just the total.", "commonMistake": "Assuming every reserve asset is as safe as a T-bill.", "mentalModel": "Read the mix."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup pays overseas contractors in USDT.", "prompt": "What should your process include?", "options": ["No records, since stablecoins are simple", "Short holding times and reserve checks", "Holding a year of payroll in one coin"], "correctIndex": 1, "consequences": ["Payments still need records for taxes and audits.", "Less time held means less issuer risk.", "Concentration in one issuer adds risk."], "explanation": "Use stablecoins to move money, not to store it all."}, "proReasoning": "Founders use stablecoins as rails and keep reserves diversified.", "commonMistake": "Storing all company cash in a single stablecoin.", "mentalModel": "Rails, not vaults."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if a stablecoin is as safe as a bank account.", "prompt": "What's the best answer?", "options": ["Yes, they are government insured", "No, stablecoins are always worthless", "It depends on the issuer's reserves"], "correctIndex": 2, "consequences": ["Stablecoins are not insured deposits.", "Many hold large reserves.", "Safety rests on what the issuer holds."], "explanation": "A stablecoin's safety comes from its reserves and the issuer, not deposit insurance."}, "proReasoning": "Ask what backs it and who holds it.", "commonMistake": "Assuming stablecoins carry bank deposit insurance.", "mentalModel": "Ask what backs it."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5e0a213ecbbf$ml$]::text[]),
($ml$d2083f79-763a-5d45-a063-50b18b104007$ml$::uuid, $ml$web3$ml$, 15, 1, $ml${"id": "web3-d15-c1", "title": "One client software, one-third of the network", "lessonTitle": "The staking giant near one-third", "slot": 1, "type": "apply", "brief": {"headline": "After Ethereum's May 2023 finality stall, developers argued it could have been avoided if no single consensus client ran on a third or more of validators.", "kicker": "Apply day 15: crossing one-third gives one group outsized power.", "fullText": "Ethereum validators run consensus software from several teams. During the May 2023 incident, over 60% of nodes went offline at one point, Blockworks reported. Some clients struggled under load while others kept going.\n\nDevelopers argued the stall could have been avoided if no client held a third or more of validators. Prysm had once run on upwards of 66% of nodes and still sat above 33%.\n\nThrough the day 15 lens: on proof of stake, one-third is a key line. Whether it is a staking pool or a software client, crossing it concentrates power and risk.", "sources": [{"url": "https://blockworks.co/news/ethereum-finality-hiccup-decentralization", "label": "Blockworks, Ethereum finality hiccup a 'fire drill', May 2023"}, {"url": "https://www.theblock.co/post/230723", "label": "The Block, Ethereum developers patch beacon chain finality issues, May 2023"}, {"url": "https://blockworks.co/news/lido-centralization-debate-ethereum", "label": "Blockworks, the Lido centralization debate"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Prysm once ran on upwards of 66% of nodes.", "Over 60% of nodes went offline at one point.", "Every validator ran the exact same software."], "fakeIndex": 2, "explanation": "Validators run several clients. That diversity helped the network recover."}, "numbers": {"kind": "numberSense", "prompt": "Developers said no client should run on more than what share of validators?", "min": 0, "max": 100, "value": 33, "explanation": "About a third. Below that line, one client's bug cannot stall finality alone.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a staking firm. They ask how they should pick client software.", "prompt": "Which answer lands best?", "options": ["Pick the client with the most social followers", "Prefer clients with smaller shares of the network", "Always use whatever most other validators run"], "correctIndex": 1, "consequences": ["Popularity online is not a safety measure.", "Diversity limits damage from one client's bug.", "Following the crowd concentrates risk."], "explanation": "A bug in a dominant client can stall the chain. Smaller clients spread that risk."}, "proReasoning": "Operators think about network risk, not just their own uptime.", "commonMistake": "Choosing the majority client because it feels safest.", "mentalModel": "Spread the client risk."}, "invest": {"call": {"kind": "theCall", "situation": "You read that one client still runs on over a third of Ethereum.", "prompt": "Why does that matter to ETH holders?", "options": ["It makes ETH supply grow faster", "It means Ethereum switched to proof of work", "One bug there could stall finality"], "correctIndex": 2, "consequences": ["Supply has nothing to do with clients.", "Ethereum stays on proof of stake.", "Concentration turns one bug into a network event."], "explanation": "Concentrated software is a hidden single point of failure."}, "proReasoning": "Investors count software concentration as a network risk.", "commonMistake": "Assuming many validators means no single point of failure.", "mentalModel": "Count the clients."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup runs validators for customers.", "prompt": "What should your setup avoid?", "options": ["Running the same majority client everywhere", "Spreading your validators across clients", "Testing new client releases before rollout"], "correctIndex": 0, "consequences": ["One bug could take all your validators down.", "Spreading clients is the safer choice.", "Testing releases is good practice."], "explanation": "Mixing clients protects customers and the network from one shared bug."}, "proReasoning": "Founders in staking build client diversity into their operations.", "commonMistake": "Standardizing every validator on one client for convenience.", "mentalModel": "Mix your clients."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why it matters which software Ethereum validators use.", "prompt": "What's the best answer?", "options": ["It does not matter; all software is perfect", "If most use one, one bug can stall the chain", "It changes how much ETH each person owns"], "correctIndex": 1, "consequences": ["Every program has bugs.", "Diversity limits the damage of any single bug.", "Software choice does not change balances."], "explanation": "When one client dominates, its bugs become the network's bugs."}, "proReasoning": "Do not put all the validators in one basket.", "commonMistake": "Assuming all software works the same under stress.", "mentalModel": "Not one basket."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:787e309df059$ml$]::text[]),
($ml$eff9310b-66f3-5148-9cc6-de7a7c115d7b$ml$::uuid, $ml$web3$ml$, 15, 2, $ml${"id": "web3-d15-c2", "title": "Pools of miners, pools of stake", "lessonTitle": "The staking giant near one-third", "slot": 2, "type": "connect", "brief": {"headline": "Six mining pools produce over 95% of Bitcoin's blocks. On Ethereum, Lido held about 32% of staked ETH in 2023, close to the one-third line critics warned about.", "kicker": "Connect day 3 and day 15: pooling concentrates power on both chains.", "fullText": "Day 3 showed proof of work: miners pool their computing power for steadier pay, so a few pools build most Bitcoin blocks. Day 15 showed the proof of stake version: holders pool their ETH through liquid staking, and Lido grew to about 32% of staked ETH in 2023.\n\nThe pattern repeats. Pooling brings convenience and steady rewards. It also gathers power in a few hands. Lido's share later eased to about 24.45% by January 2026.", "sources": [{"url": "https://blockworks.co/news/lido-centralization-debate-ethereum", "label": "Blockworks, the Lido centralization debate"}, {"url": "https://www.kucoin.com/news/flash/ethereum-staking-rate-hits-28-91-lido-holds-24-45-share", "label": "KuCoin News, Ethereum staking rate hits 28.91%, Lido holds 24.45%"}, {"url": "https://www.theblock.co/post/230723", "label": "The Block, Ethereum developers patch beacon chain finality issues, May 2023"}]}, "evidence": {"kind": "faceOff", "prompt": "About what share of staked ETH did Lido hold in January 2026?", "left": {"name": "About 24%", "note": "Down from about 32% in 2023"}, "right": {"name": "About 51%", "note": "A majority of stake"}, "correctIndex": 0, "explanation": "About 24.45% by January 2026, below the one-third line."}, "numbers": {"kind": "numberSense", "prompt": "About what share of staked ETH did Lido hold in 2023?", "min": 0, "max": 100, "value": 32, "explanation": "About 32%, close to the one-third level critics warned about.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A hiring manager asks what Bitcoin pools and Lido have in common.", "prompt": "Which answer lands best?", "options": ["Both are owned by the same company", "Both secure the network with mining rigs", "Pooling for steady rewards concentrates power"], "correctIndex": 2, "consequences": ["They are unrelated organizations.", "Lido works with staked ETH, not rigs.", "Convenience pulls participants into a few big pools."], "explanation": "Different chains, same pull: pooling smooths rewards and gathers influence."}, "proReasoning": "Strong answers see the pattern across consensus models.", "commonMistake": "Treating concentration as a problem only for proof of work.", "mentalModel": "Pooling gathers power."}, "invest": {"call": {"kind": "theCall", "situation": "You compare concentration risk across chains.", "prompt": "What should you measure on each?", "options": ["Share held by the largest few producers", "The number of coins listed on exchanges", "How old each blockchain is"], "correctIndex": 0, "consequences": ["Top shares show who could steer block space.", "Listings do not show control.", "Age does not measure concentration."], "explanation": "Whether miners or stakers, the top few producers' share is the key number."}, "proReasoning": "Investors track the biggest producers' share on every chain they hold.", "commonMistake": "Assuming proof of stake is automatically less concentrated.", "mentalModel": "Measure the top few."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers staking to users.", "prompt": "What can you do about concentration?", "options": ["Ignore it, since it is not your job", "Route stake to smaller providers too", "Send all stake to the largest pool"], "correctIndex": 1, "consequences": ["Your routing choices shape the network.", "Spreading stake avoids feeding the biggest pool.", "That adds to concentration."], "explanation": "Where you send stake shapes the network your users rely on."}, "proReasoning": "Builders carry producers' risk. Spreading stake reduces it.", "commonMistake": "Defaulting all users to the biggest pool for convenience.", "mentalModel": "Spread the stake."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why people worry about big staking pools.", "prompt": "What's the best answer?", "options": ["Big pools steal coins from small ones", "Staking pools make ETH supply infinite", "Too much stake in one pool means too much say"], "correctIndex": 2, "consequences": ["Pools do not take coins from others.", "Supply rules are unaffected.", "Influence follows stake in proof of stake."], "explanation": "In proof of stake, whoever pools the most stake gets the most influence."}, "proReasoning": "Big pools mean a few voices speak for many.", "commonMistake": "Thinking the worry is about theft rather than influence.", "mentalModel": "Stake is influence."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6dcc43c738a2$ml$]::text[]),
($ml$5329d350-04eb-5a41-9c01-3aba722df174$ml$::uuid, $ml$web3$ml$, 15, 3, $ml${"id": "web3-d15-c3", "title": "Where do you stake your ETH?", "lessonTitle": "The staking giant near one-third", "slot": 3, "type": "decide", "brief": {"headline": "You manage 500 ETH for a small fund. Lido offers liquid staking and spreads stake across many node operators, but it held about 24.45% of staked ETH in January 2026.", "kicker": "Decide how to stake without adding to concentration.", "fullText": "Liquid staking lets you stake ETH and get a tradable token back, so your ETH earns while staying usable. In 2023, Lido used 37 node operators, each holding under 1.5% of staked ETH.\n\nCritics warned that a pool above one-third could gain outsized influence over block space. Lido's share was about 24.45% in January 2026. Your fund must weigh convenience against adding to the largest pool.", "sources": [{"url": "https://blockworks.co/news/lido-centralization-debate-ethereum", "label": "Blockworks, the Lido centralization debate"}, {"url": "https://www.kucoin.com/news/flash/ethereum-staking-rate-hits-28-91-lido-holds-24-45-share", "label": "KuCoin News, Ethereum staking rate hits 28.91%, Lido holds 24.45%"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this favor the largest pool, or spreading out?", "buckets": ["Largest pool", "Spread out"], "items": [{"text": "You need the most liquid staking token", "bucket": 0}, {"text": "You want the simplest setup", "bucket": 0}, {"text": "You worry about one-third concentration", "bucket": 1}, {"text": "You can manage several providers", "bucket": 1}, {"text": "Your fund promises to support decentralization", "bucket": 1}], "explanation": "Convenience favors the leader. Concentration worries favor spreading out."}, "numbers": {"kind": "numberSense", "prompt": "In 2023, Lido used how many node operators?", "min": 0, "max": 100, "value": 37, "explanation": "37 operators, each holding under 1.5% of staked ETH."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your fund's manager asks where to stake 500 ETH.", "prompt": "What do you recommend?", "options": ["Split across providers, including smaller ones", "All of it in the biggest pool, for simplicity", "Keep it unstaked forever to avoid any choice"], "correctIndex": 0, "consequences": ["You earn rewards without feeding concentration.", "That adds to the largest pool's share.", "Unstaked ETH earns nothing."], "explanation": "Splitting stake earns rewards and keeps any one pool from growing too large."}, "proReasoning": "Analysts balance return, liquidity and network health.", "commonMistake": "Picking a staking provider on convenience alone.", "mentalModel": "Split the stake."}, "invest": {"call": {"kind": "theCall", "situation": "A liquid staking pool nears one-third of all stake.", "prompt": "What risk grows for ETH holders?", "options": ["ETH turning into a stablecoin", "Outsized influence over block space", "A faster halving schedule for ETH"], "correctIndex": 1, "consequences": ["Staking does not change ETH's nature.", "Critics warned of steering block space above 33%.", "Ethereum has no halving schedule."], "explanation": "A pool above one-third could gain outsized influence. Censorship risk grows with share."}, "proReasoning": "Investors watch staking shares the way they watch pool shares on Bitcoin.", "commonMistake": "Assuming liquid staking is risk-free because it is convenient.", "mentalModel": "One-third is the line."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds a staking app for retail users.", "prompt": "What default should you set?", "options": ["Always route to the largest pool by default", "Let a random provider take everything", "Spread new stake across several providers"], "correctIndex": 2, "consequences": ["Defaults to the leader feed concentration.", "Random choice ignores quality.", "Defaults shape where most users' stake ends up."], "explanation": "Most users keep defaults. A spread-out default protects the network they depend on."}, "proReasoning": "Founders know defaults decide outcomes. They choose them carefully.", "commonMistake": "Setting the biggest pool as the default without thinking.", "mentalModel": "Defaults decide outcomes."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if it matters where they stake their ETH.", "prompt": "What's the best answer?", "options": ["Yes, piling into one pool concentrates power", "No, every staking choice is exactly the same", "Yes, small pools pay ten times more"], "correctIndex": 0, "consequences": ["Where stake goes shapes who steers the network.", "Choices differ in liquidity and network impact.", "Rewards are broadly similar."], "explanation": "Staking gives influence. Where you stake decides who holds it."}, "proReasoning": "Your stake is a small vote. Where you cast it adds up.", "commonMistake": "Thinking staking choices affect only your own rewards.", "mentalModel": "Your stake is a vote."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4dfb9506d2c2$ml$]::text[]),
($ml$56b2bf91-3320-5616-846c-9c8518b8d626$ml$::uuid, $ml$web3$ml$, 16, 1, $ml${"id": "web3-d16-c1", "title": "A 46-day line to leave", "lessonTitle": "Over a quarter of all ETH is staked", "slot": 1, "type": "apply", "brief": {"headline": "In September 2025, Ethereum's exit queue reached about 2.65 million ETH, and the wait to unstake passed 46 days, an all-time high, according to Figment.", "kicker": "Apply day 16: staked ETH earns rewards but cannot leave at once.", "fullText": "Figment traced the spike mainly to one infrastructure provider that decided on September 9, 2025 to exit all its validators as a security precaution. That alone covered about 1.6 million ETH, worth about $7 billion and about 4.5% of all staked ETH.\n\nEthereum limits how fast stake can move. The churn limit lets about 57,600 ETH a day enter or leave, so a big exit turns into a long line.\n\nThrough the day 16 lens: over a quarter of ETH is staked to guard the network. The same rules that make that stake steady also make it slow to unwind.", "sources": [{"url": "https://www.figment.io/insights/ethereums-exit-queue-hits-record-high-what-stakers-need-to-know/", "label": "Figment, Ethereum's exit queue hits a record high, Sep 2025"}, {"url": "https://www.kucoin.com/news/flash/ethereum-staking-rate-hits-28-91-lido-holds-24-45-share", "label": "KuCoin News, Ethereum staking rate hits 28.91%, Lido holds 24.45%"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the record exit queue in order.", "steps": ["A provider decides to exit all its validators", "About 1.6 million ETH joins the exit queue", "The daily churn limit caps how much can leave", "The queue reaches about 2.65 million ETH", "The wait to unstake passes 46 days"], "explanation": "One big exit met a fixed daily limit, so the line grew to a record."}, "numbers": {"kind": "numberSense", "prompt": "The wait to leave staking passed about how many days?", "min": 0, "max": 100, "value": 46, "explanation": "Over 46 days in September 2025, an all-time high, Figment said.", "unit": "days"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a staking company. They ask what the record exit queue shows.", "prompt": "Which answer is strongest?", "options": ["Stakers can always withdraw within one hour", "The queue proves staking is about to end", "Staked ETH is steady because it cannot leave fast"], "correctIndex": 2, "consequences": ["The wait passed 46 days in September 2025.", "One provider caused most of the spike.", "The churn limit turns big exits into long waits."], "explanation": "Ethereum caps how much stake moves each day. That protects the network and slows exits."}, "proReasoning": "Strong candidates explain the churn limit and why it exists, not just the wait.", "commonMistake": "Treating staked ETH like cash that can leave the same day.", "mentalModel": "Steady by design."}, "invest": {"call": {"kind": "theCall", "situation": "You stake ETH you may need for a payment next month.", "prompt": "What should you weigh first?", "options": ["Exits can take weeks when the queue is long", "Staking rewards always cover any delay", "Unstaked ETH is paid back within minutes"], "correctIndex": 0, "consequences": ["The exit wait topped 46 days in September 2025.", "Rewards do not help if you need cash now.", "Withdrawals follow a queue, not a timer."], "explanation": "Staking ties ETH up. In a crowded queue, getting it back can take over a month."}, "proReasoning": "Investors match staking to money they will not need soon.", "commonMistake": "Staking funds you will need on a fixed date.", "mentalModel": "Stake what can wait."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers staking to small savers.", "prompt": "What do you build first?", "options": ["A hidden fee for leaving early", "A live estimate of the exit wait", "A promise of instant withdrawals"], "correctIndex": 1, "consequences": ["Hidden fees destroy trust fast.", "Users see the wait before they choose.", "You cannot beat the protocol queue."], "explanation": "The queue is set by the protocol. Showing it honestly is the best service you can offer."}, "proReasoning": "Founders design around protocol limits instead of promising to beat them.", "commonMistake": "Marketing staking as if exits were instant.", "mentalModel": "Show the wait."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why someone had to wait 46 days for their own ETH.", "prompt": "What's the best answer?", "options": ["The bank that runs Ethereum was closed for weeks", "Their password reset took six weeks", "The network limits how much stake leaves each day"], "correctIndex": 2, "consequences": ["No bank runs Ethereum.", "Passwords have nothing to do with the queue.", "About 57,600 ETH a day can move, so a big rush builds a line."], "explanation": "Ethereum lets only so much stake leave per day. When many leave at once, everyone waits."}, "proReasoning": "Think of a stadium exit with a fixed number of turnstiles.", "commonMistake": "Assuming the delay was someone's mistake.", "mentalModel": "Fixed turnstiles."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:cb345c833abe$ml$]::text[]),
($ml$65b4a12f-c8b7-5672-86f1-7973aa155c24$ml$::uuid, $ml$web3$ml$, 16, 2, $ml${"id": "web3-d16-c2", "title": "How much of the stake sits with Lido?", "lessonTitle": "Over a quarter of all ETH is staked", "slot": 2, "type": "connect", "brief": {"headline": "In January 2026, about 35.9 million ETH was staked, and Lido held 24.45% of that stake. That works out to roughly 8.8 million ETH in one protocol.", "kicker": "Connect day 15 and day 16: a big stake makes one share matter more.", "fullText": "Day 15 showed why a single staking pool near one-third worries critics: above 33%, a pool could steer block space. Day 16 showed how big the staked pool has become, about 35.9 million ETH, or 28.91% of supply.\n\nPut together, Lido's 24.45% share is about 8.8 million ETH, by our arithmetic from the Dune figures. Its share fell from near one-third in 2023, but the stake behind it grew.", "sources": [{"url": "https://www.kucoin.com/news/flash/ethereum-staking-rate-hits-28-91-lido-holds-24-45-share", "label": "KuCoin News, Ethereum staking rate hits 28.91%, Lido holds 24.45%"}, {"url": "https://blockworks.co/news/lido-centralization-debate-ethereum", "label": "Blockworks, the Lido centralization debate"}]}, "evidence": {"kind": "faceOff", "prompt": "Which number tells you how close Lido is to the one-third line?", "left": {"name": "Lido's share of staked ETH", "note": "24.45% of all staked ETH in January 2026"}, "right": {"name": "Lido's ETH in raw coins", "note": "About 8.8 million ETH by our arithmetic"}, "correctIndex": 0, "explanation": "The one-third worry is about share of the stake, not raw coins. Share is what decides power."}, "numbers": {"kind": "numberSense", "prompt": "Lido held about what percent of staked ETH in January 2026?", "min": 0, "max": 60, "value": 24, "explanation": "About 24.45%, below the one-third line critics warned about.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks you to brief the team on staking concentration.", "prompt": "Which point leads?", "options": ["Share of stake decides power, not coin count", "Bigger stake always means more risk", "Lido now controls over half of Ethereum"], "correctIndex": 0, "consequences": ["The one-third line is a share threshold.", "A larger total can dilute one pool's share.", "Lido held 24.45%, well under half."], "explanation": "Lido held more coins than before but a smaller share. Share is what matters for control."}, "proReasoning": "Analysts separate absolute size from share. Each answers a different question.", "commonMistake": "Confusing a big coin count with a dominant share.", "mentalModel": "Share decides power."}, "invest": {"call": {"kind": "theCall", "situation": "You compare staking protocols for a client.", "prompt": "Which risk do you flag about Lido?", "options": ["Lido stake can never be withdrawn", "A share near one-third would give it real sway", "Lido pays no staking rewards to any of its users"], "correctIndex": 1, "consequences": ["Withdrawals opened at Shanghai.", "Critics drew the line at 33%.", "Lido does pay staking rewards."], "explanation": "Concentration risk depends on how close one pool gets to one-third of the stake."}, "proReasoning": "Investors track staking shares each quarter. Direction matters as much as level.", "commonMistake": "Ignoring the trend in a protocol's share.", "mentalModel": "Watch the share."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup runs a small staking pool.", "prompt": "How do you pitch it to users?", "options": ["Our pool will soon pass one-third", "Big pools pay more, so wait for us to grow", "Spreading stake makes the network sturdier"], "correctIndex": 2, "consequences": ["Passing one-third is the risk critics fear.", "Size does not set Ethereum rewards.", "Fewer giant pools means less single control."], "explanation": "Many users care that no single pool dominates. A smaller pool can sell that."}, "proReasoning": "Founders turn a network risk into a reason to choose them.", "commonMistake": "Bragging about a share that would worry the network.", "mentalModel": "Spread the stake."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if Lido \"owns\" a quarter of Ethereum.", "prompt": "What's the best answer?", "options": ["It runs about a quarter of the staked ETH", "It owns a quarter of all ETH ever made", "It owns Ethereum's code"], "correctIndex": 0, "consequences": ["Lido held 24.45% of staked ETH, not of all ETH.", "Only 28.91% of all ETH was staked.", "No company owns Ethereum's code."], "explanation": "Lido manages stake for many users. Its share is of staked ETH, which is under a third of supply."}, "proReasoning": "A quarter of a quarter is a very different number than a quarter of everything.", "commonMistake": "Mixing up share of stake with share of supply.", "mentalModel": "A share of the stake."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3a343452447f$ml$]::text[]),
($ml$e52ccbb4-6dab-5317-bbc5-dba8be6aeec3$ml$::uuid, $ml$web3$ml$, 16, 3, $ml${"id": "web3-d16-c3", "title": "Stake it, or keep it liquid?", "lessonTitle": "Over a quarter of all ETH is staked", "slot": 3, "type": "decide", "brief": {"headline": "You hold ETH for a small fund. About 28.91% of all ETH was staked in January 2026, earning rewards for helping secure the network.", "kicker": "Decide how much of your ETH to stake.", "fullText": "Staked ETH earns rewards but is tied up. Since withdrawals opened at the Shanghai upgrade, net inflows reached about 17.7 million ETH, so stakers kept adding rather than leaving.\n\nLiquid staking tokens let holders keep using staked ETH, but they add a layer of risk. Your fund may need cash at short notice.", "sources": [{"url": "https://www.kucoin.com/news/flash/ethereum-staking-rate-hits-28-91-lido-holds-24-45-share", "label": "KuCoin News, Ethereum staking rate hits 28.91%, Lido holds 24.45%"}, {"url": "https://www.figment.io/insights/ethereums-exit-queue-hits-record-high-what-stakers-need-to-know/", "label": "Figment, Ethereum's exit queue hits a record high, Sep 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this point toward staking more, or keeping ETH liquid?", "buckets": ["Stake more", "Keep liquid"], "items": [{"text": "You will not need the ETH for a year", "bucket": 0}, {"text": "You want rewards on idle coins", "bucket": 0}, {"text": "A payout is due in two weeks", "bucket": 1}, {"text": "The exit queue is at a record", "bucket": 1}, {"text": "Your fund may face sudden redemptions", "bucket": 1}], "explanation": "Stake money that can wait. Keep enough liquid for known and surprise payouts."}, "numbers": {"kind": "numberSense", "prompt": "About what percent of all ETH was staked in January 2026?", "min": 0, "max": 100, "value": 29, "explanation": "About 28.91% of total supply.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks you to propose a staking split for the fund.", "prompt": "What do you recommend?", "options": ["Stake nothing until rewards double", "Stake the long-term part, keep a liquid buffer", "Stake everything for the highest rewards"], "correctIndex": 1, "consequences": ["You give up rewards for no clear reason.", "Rewards on idle ETH, cash for payouts.", "One redemption wave could leave you stuck."], "explanation": "Staking earns rewards but exits can take weeks. Split by when you need the money."}, "proReasoning": "Treasury teams match each coin to its time horizon.", "commonMistake": "Treating all ETH as if it were never needed.", "mentalModel": "Split by horizon."}, "invest": {"call": {"kind": "theCall", "situation": "A fund you analyze stakes 100% of its ETH.", "prompt": "What question do you ask?", "options": ["Why are its rewards so low?", "Why does it not stake even more?", "How would it pay a large redemption?"], "correctIndex": 2, "consequences": ["Rewards are not the main risk here.", "It cannot stake more than all.", "A long exit queue could block payouts."], "explanation": "Full staking leaves no buffer. In a record queue, exits took over 46 days."}, "proReasoning": "Investors test liquidity under stress, not on a calm day.", "commonMistake": "Only looking at the reward rate.", "mentalModel": "Test the exit."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds a treasury tool for crypto funds.", "prompt": "Which feature helps most?", "options": ["A planner that matches stake to payout dates", "A button that stakes every coin at once", "A forecast of next year's ETH price"], "correctIndex": 0, "consequences": ["Funds see what can be staked safely.", "It ignores cash needs.", "Price calls do not solve liquidity."], "explanation": "Funds struggle to balance rewards and access. Tools that plan both are useful."}, "proReasoning": "Founders build around the real decision users face.", "commonMistake": "Building for yield alone and ignoring liquidity.", "mentalModel": "Plan both sides."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why not stake all their ETH for free rewards.", "prompt": "What's the best answer?", "options": ["Rewards are paid only once a decade", "Staked ETH can take weeks to get back", "Staking is banned in most countries"], "correctIndex": 1, "consequences": ["Rewards flow continuously.", "Exit waits passed 46 days in 2025.", "That is not true."], "explanation": "Rewards are real, but staked coins are tied up. Keep some ready for life."}, "proReasoning": "It is like a savings account that takes a month to withdraw from.", "commonMistake": "Locking up money you may need soon.", "mentalModel": "Rewards, not cash."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4d3fe962acb0$ml$]::text[]),
($ml$da1bf5b9-e82a-5f50-b59a-dfa38580bc02$ml$::uuid, $ml$web3$ml$, 17, 1, $ml${"id": "web3-d17-c1", "title": "The rulebook arrives", "lessonTitle": "America's first stablecoin law", "slot": 1, "type": "apply", "brief": {"headline": "In October 2026, the US bank regulator, the OCC, finalised its rule to implement the GENIUS Act for payment stablecoin issuers. It takes effect on January 18, 2027.", "kicker": "Apply day 17: a law sets the goal, then regulators write the details.", "fullText": "The OCC first published its proposal on February 25, 2026. The final rule covers permitted activities, reserve assets, redemption, risk management, audits, reporting, custody and capital backstops. Weekly and quarterly reporting forms were finalised too.\n\nAnti-money laundering and sanctions rules are being handled separately with the Treasury.\n\nThrough the day 17 lens: the July 2025 law set one-to-one reserves and banned paying holders interest. The OCC rule turns that into checklists that issuers must meet.", "sources": [{"url": "https://thepaypers.com/regulations/news/occ-finalises-genius-act-rule-for-payment-stablecoin-issuers", "label": "The Paypers, OCC finalises GENIUS Act rule for stablecoin issuers, Oct 2026"}, {"url": "https://www.everycrsreport.com/files/2026-08-20_IN12553_0b329134f6be0cc12f78017358552f4053d52c5e.html", "label": "Congressional Research Service, overview of the GENIUS Act of 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the stablecoin rulemaking in order.", "steps": ["The GENIUS Act becomes law", "The OCC publishes its proposal", "The proposal appears in the Federal Register", "The OCC finalises its rule", "The rule takes effect"], "explanation": "July 2025, February 2026, March 2026, October 2026, then January 18, 2027."}, "numbers": {"kind": "numberSense", "prompt": "About how many months passed from the law to the rule taking effect?", "min": 0, "max": 48, "value": 18, "explanation": "From July 2025 to January 2027 is about 18 months, by our count.", "unit": "months"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A stablecoin issuer is hiring a compliance analyst. They ask what changes on January 18, 2027.", "prompt": "Which answer lands best?", "options": ["The OCC rule makes the law's duties enforceable", "Stablecoins become securities that day", "Issuers can start paying holders interest"], "correctIndex": 0, "consequences": ["Reserves, redemption and reporting rules apply.", "The law says payment stablecoins are not securities.", "The law bans paying holders interest."], "explanation": "The law set the principles. The OCC rule sets the reporting, audits and reserves issuers must show."}, "proReasoning": "Compliance hires who know the effective date and the forms stand out.", "commonMistake": "Treating the law's signing date as the day rules bite.", "mentalModel": "Effective date matters."}, "invest": {"call": {"kind": "theCall", "situation": "You weigh a stablecoin issuer ahead of the rule.", "prompt": "What do you check?", "options": ["Whether its token price will rise", "Whether its reserves and reports fit the rule", "Whether it pays holders the highest interest rate"], "correctIndex": 1, "consequences": ["A stablecoin aims to hold one dollar.", "The rule tests reserves, redemption and reporting.", "Paying holders interest is banned."], "explanation": "Issuers that already meet the reserve and reporting rules face less risk in 2027."}, "proReasoning": "Investors ask how ready a firm is for rules that are already written.", "commonMistake": "Judging a stablecoin by yield it is not allowed to pay.", "mentalModel": "Check readiness."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup plans a US payment stablecoin in 2027.", "prompt": "What is your first workstream?", "options": ["Design a rewards rate to pay token holders", "Launch first and apply later", "Build weekly reporting and reserve audits"], "correctIndex": 2, "consequences": ["Issuers may not pay holders interest.", "The rule takes effect January 18, 2027.", "Weekly and quarterly forms were finalised."], "explanation": "The rule is final. Reporting and audit systems take months to build, so start now."}, "proReasoning": "Founders treat compliance as product work with a hard deadline.", "commonMistake": "Leaving reporting systems for after launch.", "mentalModel": "Build reporting now."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a law from 2025 only \"kicks in\" in 2027.", "prompt": "What's the best answer?", "options": ["Regulators first had to write the detailed rules", "Congress forgot to sign it", "Stablecoins were banned in the US until 2027"], "correctIndex": 0, "consequences": ["The OCC proposed in February 2026 and finalised in October.", "It became law on July 18, 2025.", "They were not banned."], "explanation": "Laws often set goals. Agencies then write the detailed rules and give firms time to comply."}, "proReasoning": "It is like a new building code that starts after inspectors get their checklists.", "commonMistake": "Assuming a law works the day it is signed.", "mentalModel": "Rules come after the law."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:120b0dfe71b7$ml$]::text[]),
($ml$0629dddb-f6f8-5365-b19f-305f4e9c4742$ml$::uuid, $ml$web3$ml$, 17, 2, $ml${"id": "web3-d17-c2", "title": "Tether's cushion meets the new rule", "lessonTitle": "America's first stablecoin law", "slot": 2, "type": "connect", "brief": {"headline": "Tether reported about $193 billion in assets backing about $186 billion of USDT in 2025. The GENIUS Act requires at least $1 of permitted reserves for every $1 of US payment stablecoins.", "kicker": "Connect day 14 and day 17: profit from reserves, rules for reserves.", "fullText": "Day 14 showed how Tether earns over $10 billion a year by holding reserves that pay interest. Its excess reserves were about $6.3 billion.\n\nDay 17 showed the new US rule: permitted reserves are cash-like assets such as insured deposits and short-dated Treasury bills, held one to one. Bitcoin and stocks do not count. Under the law, what is in the reserve matters as much as how big it is.", "sources": [{"url": "https://www.theblock.co/post/387908/tether-rakes-10-billion-net-profit-2025-excess-reserves-6-3-billion", "label": "The Block, Tether earns $10 billion net profit in 2025"}, {"url": "https://www.everycrsreport.com/files/2026-08-20_IN12553_0b329134f6be0cc12f78017358552f4053d52c5e.html", "label": "Congressional Research Service, overview of the GENIUS Act of 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Under the GENIUS Act, which reserve asset counts toward the one-to-one rule?", "options": ["Short-dated Treasury bills", "Bitcoin held in cold storage", "Shares of large tech companies"], "correctIndex": 0, "explanation": "Permitted reserves are cash-like: cash, insured deposits and short-dated T-bills."}, "numbers": {"kind": "numberSense", "prompt": "Tether reported $193 billion of assets backing about how many billion dollars of USDT?", "min": 0, "max": 300, "value": 186, "explanation": "About $186 billion of USDT, leaving about $6.3 billion extra.", "unit": "B"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a stablecoin firm's treasury team. Your lead asks what the new law changes for reserves.", "prompt": "Which answer is best?", "options": ["Reserves no longer need to be reported", "What reserves hold now matters, not just size", "Any asset counts as long as the total is large"], "correctIndex": 1, "consequences": ["Reporting is central to the rules.", "Only permitted, cash-like assets count.", "Bitcoin and stocks do not count."], "explanation": "A big cushion of the wrong assets does not meet the law. Composition is the test."}, "proReasoning": "Treasury staff who sort assets into permitted and not permitted are valuable.", "commonMistake": "Assuming a large surplus fixes everything.", "mentalModel": "Composition counts."}, "invest": {"call": {"kind": "theCall", "situation": "You compare two stablecoins with the same reserve size.", "prompt": "Which one carries less rule risk?", "options": ["The one holding bitcoin and gold bars instead", "The one paying the highest yield", "The one holding T-bills and insured deposits"], "correctIndex": 2, "consequences": ["Those are not permitted reserves.", "Paying holders interest is banned.", "Those are permitted reserves."], "explanation": "Same size, different quality. Only cash-like reserves meet the one-to-one rule."}, "proReasoning": "Investors read the reserve breakdown, not just the total.", "commonMistake": "Treating all reserves as equal.", "mentalModel": "Read the breakdown."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your stablecoin startup wants to earn like Tether.", "prompt": "Where can revenue come from under the law?", "options": ["Interest on permitted reserves like T-bills", "Paying users interest to attract them", "Investing reserves in growth stocks"], "correctIndex": 0, "consequences": ["Reserves can still earn interest for the issuer.", "Issuers may not pay holders interest.", "Stocks are not permitted reserves."], "explanation": "Issuers can keep the yield on safe reserves. They cannot pass it to holders or chase risk."}, "proReasoning": "Founders model revenue on T-bill rates, which move with policy.", "commonMistake": "Planning a business that depends on paying holders yield.", "mentalModel": "Earn on safe reserves."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how Tether can make $10 billion from a coin worth one dollar.", "prompt": "What's the best answer?", "options": ["It charges a fee on every payment", "It earns interest on the reserves behind the coins", "It sells each coin for two dollars to new buyers"], "correctIndex": 1, "consequences": ["Its profit comes mainly from reserves.", "Reserves like T-bills pay interest.", "Each USDT aims to stay at one dollar."], "explanation": "People hand over dollars for tokens. Tether invests those dollars safely and keeps the interest."}, "proReasoning": "It is like a bank that keeps the interest on your deposit.", "commonMistake": "Thinking stablecoin profits come from the coin's price.", "mentalModel": "Interest on reserves."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3ab34cf5a87e$ml$]::text[]),
($ml$ccba8d9a-e072-5cd1-ae57-d1230f8dffe5$ml$::uuid, $ml$web3$ml$, 17, 3, $ml${"id": "web3-d17-c3", "title": "State charter or federal oversight?", "lessonTitle": "America's first stablecoin law", "slot": 3, "type": "decide", "brief": {"headline": "You run a fast-growing US stablecoin with $4 billion outstanding. Under the GENIUS Act, issuers with more than $10 billion outstanding fall under federal oversight.", "kicker": "Decide how to plan for crossing $10 billion.", "fullText": "The law requires $1 of permitted reserves for every $1 issued and bans paying holders interest. If an issuer fails, holders have priority over other claims.\n\nAbove $10 billion outstanding, an issuer falls under federal oversight. Your growth plan could take you past that line within two years.", "sources": [{"url": "https://www.everycrsreport.com/files/2026-08-20_IN12553_0b329134f6be0cc12f78017358552f4053d52c5e.html", "label": "Congressional Research Service, overview of the GENIUS Act of 2025"}, {"url": "https://thepaypers.com/regulations/news/occ-finalises-genius-act-rule-for-payment-stablecoin-issuers", "label": "The Paypers, OCC finalises GENIUS Act rule for stablecoin issuers, Oct 2026"}]}, "evidence": {"kind": "faceOff", "prompt": "What should drive your plan for passing $10 billion?", "left": {"name": "Preparing early for federal oversight", "note": "Build reports and audits that fit the federal rule now"}, "right": {"name": "Staying just under $10 billion forever", "note": "Cap growth to avoid any change in supervisor"}, "correctIndex": 0, "explanation": "A cap limits the business. Preparing early makes the transition routine."}, "numbers": {"kind": "numberSense", "prompt": "Above how many billion dollars outstanding does federal oversight apply?", "min": 0, "max": 50, "value": 10, "explanation": "More than $10 billion outstanding.", "unit": "B"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your board asks for a two-year plan.", "prompt": "What do you put first?", "options": ["A cap at $9.9 billion of tokens", "A move offshore so the US law never applies", "Systems that already meet federal standards"], "correctIndex": 2, "consequences": ["A cap throttles your own growth.", "US users would still need a compliant coin.", "Crossing the line becomes a formality."], "explanation": "If growth is the plan, build for the next supervisor before you meet it."}, "proReasoning": "Leaders prepare for the rules they will face at the next size.", "commonMistake": "Designing the business around avoiding a threshold.", "mentalModel": "Build for the next size."}, "invest": {"call": {"kind": "theCall", "situation": "An issuer you follow is at $9 billion and growing.", "prompt": "What do you watch?", "options": ["Its readiness for federal oversight", "Whether it starts paying holders interest", "Whether its token trades above one dollar"], "correctIndex": 0, "consequences": ["The jump in supervision is near.", "Paying holders interest is banned.", "It aims to hold one dollar."], "explanation": "Crossing $10 billion changes who supervises the issuer. Readiness lowers the risk."}, "proReasoning": "Investors look for thresholds that change a firm's rules.", "commonMistake": "Ignoring a regulatory line the firm is about to cross.", "mentalModel": "Watch the line."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells compliance software to issuers.", "prompt": "Who is your best first customer?", "options": ["Projects that hold bitcoin as reserves", "Issuers approaching $10 billion outstanding", "Issuers that pay holders interest"], "correctIndex": 1, "consequences": ["Those reserves are not permitted.", "They face new oversight soon.", "That is banned, so they have bigger problems."], "explanation": "Firms near a threshold have urgent, funded needs. That is a strong first market."}, "proReasoning": "Founders sell to customers whose deadline is closest.", "commonMistake": "Selling to firms that cannot meet the law at all.", "mentalModel": "Sell to the deadline."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a bigger stablecoin gets a different regulator.", "prompt": "What's the best answer?", "options": ["Big issuers asked to be watched more", "Small stablecoins are not allowed in the US", "A failure would hurt more people, so rules rise"], "correctIndex": 2, "consequences": ["Size, not preference, sets the rule.", "Small issuers are allowed.", "Above $10 billion, federal oversight applies."], "explanation": "The more dollars a coin holds, the more people it affects if it fails."}, "proReasoning": "It is like larger banks facing stricter checkups.", "commonMistake": "Thinking every issuer faces the same supervisor.", "mentalModel": "Bigger means closer watch."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:17aed380421b$ml$]::text[]),
($ml$c2f963e9-5984-56d4-adf6-0e1b0a35e9fa$ml$::uuid, $ml$web3$ml$, 18, 1, $ml${"id": "web3-d18-c1", "title": "Five years for a privacy wallet", "lessonTitle": "Can you sanction a piece of code?", "slot": 1, "type": "apply", "brief": {"headline": "In November 2025, Samourai Wallet's founders were sentenced in New York: CEO Keonne Rodriguez to five years in prison and CTO William Hill to four.", "kicker": "Apply day 18: running a service is judged differently from writing code.", "fullText": "Both were sentenced for conspiring to operate a money transmitting business that knowingly moved criminal proceeds. Prosecutors said more than $237 million of criminal proceeds went through Samourai's Whirlpool and Ricochet services, and over 80,000 bitcoin passed through them in total.\n\nEach was fined $250,000. Prosecutors cited marketing on a darknet forum.\n\nThrough the day 18 lens: courts said Tornado Cash's ownerless contracts were not property. Samourai was a company that ran a service, collected fees and marketed it.", "sources": [{"url": "https://www.justice.gov/usao-sdny/pr/founders-samourai-wallet-cryptocurrency-mixing-service-sentenced-five-and-four-years", "label": "US Attorney SDNY, Samourai Wallet founders sentenced, Nov 2025"}, {"url": "https://www.venable.com/insights/publications/2025/04/a-legal-whirlwind-settles-treasury-lifts-sanctions", "label": "Venable, Treasury lifts sanctions on Tornado Cash"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Rodriguez was sentenced to five years in prison", "Prosecutors cited over $237 million of criminal proceeds", "A court ruled Samourai was ownerless code"], "fakeIndex": 2, "explanation": "The ownerless ruling was about Tornado Cash. Samourai was run as a business that charged fees."}, "numbers": {"kind": "numberSense", "prompt": "Prosecutors said about how many million dollars of criminal proceeds went through Samourai?", "min": 0, "max": 600, "value": 237, "explanation": "Over $237 million, out of more than 80,000 bitcoin that passed through.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview for a crypto compliance role. They ask how Samourai differs from Tornado Cash.", "prompt": "Which answer is strongest?", "options": ["Samourai was legal because it only used bitcoin, not ether", "Samourai ran a paid service; the Tornado ruling was on code", "Both were found innocent on all charges"], "correctIndex": 1, "consequences": ["The currency does not change the law.", "Running and marketing a service carries liability.", "Samourai's founders were sentenced."], "explanation": "The line courts draw is between publishing code and running a service for money."}, "proReasoning": "Strong candidates explain where liability sits, not just the verdicts.", "commonMistake": "Treating every privacy tool case as the same.", "mentalModel": "Service versus code."}, "invest": {"call": {"kind": "theCall", "situation": "You weigh a startup building a privacy feature for a wallet.", "prompt": "What do you ask first?", "options": ["Will it be faster than every rival wallet?", "Can it list a token next year?", "Does the company run, control or charge for it?"], "correctIndex": 2, "consequences": ["Speed is not the main risk.", "A token does not answer the legal question.", "Control and fees shaped the Samourai case."], "explanation": "Legal risk rises when a company operates the service, takes fees and markets it."}, "proReasoning": "Investors map where liability would land before they fund a privacy tool.", "commonMistake": "Ignoring legal design until after launch.", "mentalModel": "Find the liability."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your team is building a coin mixing feature.", "prompt": "Which choice cuts your legal risk most?", "options": ["Never market it to criminals or take their funds", "Advertise it on darknet forums for reach", "Take a cut of every mixed transaction quietly"], "correctIndex": 0, "consequences": ["Prosecutors cited darknet marketing at Samourai.", "That was cited as evidence against Samourai.", "Fees helped show it was a business."], "explanation": "Samourai's founders were sentenced partly over marketing and fees. Do neither."}, "proReasoning": "Founders get legal advice before building tools that hide fund flows.", "commonMistake": "Assuming open-source status protects any business model.", "mentalModel": "Watch the marketing."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a wallet maker went to prison but a code writer's sanctions were lifted.", "prompt": "What's the best answer?", "options": ["The courts picked at random", "One ran a paid service; the other was ownerless code", "Prison terms depend on which coin the tool used"], "correctIndex": 1, "consequences": ["Each case had its own facts.", "That distinction runs through both cases.", "Both involved crypto mixing."], "explanation": "Courts look at who controls and profits from a tool. Code alone was not property; a business was liable."}, "proReasoning": "It is the difference between writing a lock design and running a getaway service.", "commonMistake": "Thinking the technology alone decides guilt.", "mentalModel": "Control and profit."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8097fac8008a$ml$]::text[]),
($ml$a29573d7-9562-5474-b8bb-025502f6afc3$ml$::uuid, $ml$web3$ml$, 18, 2, $ml${"id": "web3-d18-c2", "title": "Code that cannot be deleted, or owned", "lessonTitle": "Can you sanction a piece of code?", "slot": 2, "type": "connect", "brief": {"headline": "A deployed Ethereum smart contract cannot be deleted by default. In November 2024, a US appeals court ruled Tornado Cash's immutable contracts were not property that could be sanctioned.", "kicker": "Connect day 13 and day 18: what you cannot change, no one may own.", "fullText": "Day 13 showed that once deployed, a smart contract runs exactly as written and, by default, stays on the chain. Day 18 showed what a court made of that: contracts that no one owns, controls or can shut off lack the hallmarks of property.\n\nTreasury had sanctioned the mixer in August 2022 and lifted the sanctions in March 2025. The same permanence that makes contracts trustworthy put them outside a sanctions tool built for property.", "sources": [{"url": "https://ethereum.org/developers/docs/smart-contracts/", "label": "ethereum.org, smart contracts"}, {"url": "https://www.venable.com/insights/publications/2025/04/a-legal-whirlwind-settles-treasury-lifts-sanctions", "label": "Venable, Treasury lifts sanctions on Tornado Cash"}]}, "evidence": {"kind": "faceOff", "prompt": "Why could the contracts not be sanctioned as property?", "left": {"name": "No one owned or controlled them", "note": "Immutable code with no one able to change it"}, "right": {"name": "They held no crypto at all", "note": "The contracts were empty when sanctioned"}, "correctIndex": 0, "explanation": "The court said they lacked ownership, control and exclusivity."}, "numbers": {"kind": "numberSense", "prompt": "About how many months passed between the sanctions and their lifting?", "min": 0, "max": 70, "value": 31, "explanation": "From August 2022 to March 2025 is about 31 months, by our count.", "unit": "months"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager at a crypto law firm asks you to explain the Tornado Cash ruling.", "prompt": "Which summary is best?", "options": ["All smart contracts are now legal by default", "Developers can never be prosecuted", "Ownerless, unchangeable code is not property"], "correctIndex": 2, "consequences": ["The ruling was narrow.", "Roman Storm still faces a retrial.", "That is the core of the 2024 ruling."], "explanation": "The ruling turned on control. It did not clear developers or every contract."}, "proReasoning": "Precise summaries beat sweeping ones in legal work.", "commonMistake": "Reading a narrow ruling as a blanket green light.", "mentalModel": "Narrow ruling."}, "invest": {"call": {"kind": "theCall", "situation": "You hold a token whose contract has an admin key.", "prompt": "What does the ruling suggest about it?", "options": ["Someone can control it, so rules can reach it", "It is immune from any sanctions, like Tornado Cash", "It cannot be upgraded by anyone"], "correctIndex": 0, "consequences": ["Control makes something look more like property.", "The ruling covered ownerless code.", "An admin key means it can be changed."], "explanation": "Control cuts both ways. It allows fixes, and it gives regulators a target."}, "proReasoning": "Investors note who holds admin keys and what that means legally.", "commonMistake": "Assuming the Tornado Cash ruling covers every contract.", "mentalModel": "Control is a target."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup is choosing whether to keep an upgrade key.", "prompt": "What do you weigh?", "options": ["Only how users feel about the logo", "Fixing bugs versus being someone who controls it", "Only which option is cheaper to deploy today"], "correctIndex": 1, "consequences": ["Branding does not settle control.", "An upgrade key allows fixes and creates control.", "Cost is a small part of this choice."], "explanation": "Keeping control lets you patch flaws. It also makes you answerable for the contract."}, "proReasoning": "Founders decide on control with lawyers and engineers together.", "commonMistake": "Choosing immutability or control without weighing both sides.", "mentalModel": "Weigh fixes and liability."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a court can say code is not property.", "prompt": "What's the best answer?", "options": ["Code is too small to count as anything", "The judge did not understand how computers work", "Property needs an owner, and no one controlled it"], "correctIndex": 2, "consequences": ["Size had nothing to do with it.", "The ruling explained its reasoning.", "The court cited a lack of ownership and control."], "explanation": "A deployed contract no one can change has no owner. That is why sanctions aimed at property did not fit."}, "proReasoning": "It is like a public bench bolted down by no one.", "commonMistake": "Thinking the ruling means code can never be regulated.", "mentalModel": "No owner, no property."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1daa050d60fe$ml$]::text[]),
($ml$70b5105c-03aa-5e76-8759-59c50cac3f95$ml$::uuid, $ml$web3$ml$, 18, 3, $ml${"id": "web3-d18-c3", "title": "Ship the privacy tool as code, or as a service?", "lessonTitle": "Can you sanction a piece of code?", "slot": 3, "type": "decide", "brief": {"headline": "You are building a privacy tool for crypto payments. Courts are still drawing the line between writing code and running a service, as the Tornado Cash and Samourai cases show.", "kicker": "Decide how to ship your privacy tool.", "fullText": "An appeals court said Tornado Cash's ownerless contracts were not sanctionable property. Yet developer Roman Storm was convicted on one count in August 2025 and faces a retrial in April 2027.\n\nSamourai's founders, who ran a service, collected fees and marketed it, were sentenced to five and four years. Your design and business model shape your risk.", "sources": [{"url": "https://theblock.co/news/regulation/2026-08-26-tornado-cash-roman-storm-retrial-april-2027-412761", "label": "The Block, Roman Storm's retrial pushed back to April 2027"}, {"url": "https://www.justice.gov/usao-sdny/pr/founders-samourai-wallet-cryptocurrency-mixing-service-sentenced-five-and-four-years", "label": "US Attorney SDNY, Samourai Wallet founders sentenced, Nov 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this make your tool look more like a service or more like code?", "buckets": ["More like a service", "More like code"], "items": [{"text": "You charge a fee on every use", "bucket": 0}, {"text": "You can pause or block transactions", "bucket": 0}, {"text": "You market it to specific users", "bucket": 0}, {"text": "Anyone can run it without you", "bucket": 1}, {"text": "You hold no keys and earn no fees", "bucket": 1}], "explanation": "Control, fees and marketing make a tool look like a service you operate."}, "numbers": {"kind": "numberSense", "prompt": "Treasury lifted the Tornado Cash sanctions about how many months after the court ruling?", "min": 0, "max": 24, "value": 4, "explanation": "From November 2024 to March 2025, about 4 months.", "unit": "months"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your cofounder asks how to cut legal risk before launch.", "prompt": "What do you propose?", "options": ["Get counsel and avoid running or marketing it as a service", "Launch fast and handle lawyers later", "Add fees now so they can fund any future legal bills"], "correctIndex": 0, "consequences": ["Service traits drove the Samourai case.", "Legal design is hard to change later.", "Fees make it look more like a business."], "explanation": "How you run a privacy tool matters as much as its code. Plan the model with counsel."}, "proReasoning": "Founders treat legal structure as part of product design.", "commonMistake": "Treating the Tornado Cash ruling as permission for any model.", "mentalModel": "Design with counsel."}, "invest": {"call": {"kind": "theCall", "situation": "You are asked to fund a privacy tool startup.", "prompt": "What makes you most cautious?", "options": ["A product with no token at all", "A plan to charge fees and control transactions", "A team that publishes all of its code openly"], "correctIndex": 1, "consequences": ["No token is not a red flag.", "Those traits raise service liability.", "Open code alone is not the main risk."], "explanation": "Fees and control make a tool look like a money service, which carries real legal risk."}, "proReasoning": "Investors weigh legal design as heavily as technology here.", "commonMistake": "Funding a model that mirrors the cases that ended in prison.", "mentalModel": "Fees plus control."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup needs revenue but wants low legal risk.", "prompt": "Which model fits best?", "options": ["Take a cut of every private transfer", "Run your own servers that route every payment", "Sell audits and support, not a fee per mix"], "correctIndex": 2, "consequences": ["Per-transfer fees signal a money service.", "Routing funds looks like operating a service.", "Revenue does not depend on moving funds."], "explanation": "You can earn from services around the code without operating the flow of funds."}, "proReasoning": "Founders separate their revenue from the act of moving money.", "commonMistake": "Building revenue on the riskiest part of the product.", "mentalModel": "Earn around, not through."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend building a privacy app asks if writing code is ever a crime.", "prompt": "What's the best answer?", "options": ["Courts are still deciding; how you run it matters", "Code is always legal, no matter what it is used for", "Any privacy code is now illegal"], "correctIndex": 0, "consequences": ["Storm faces a retrial in April 2027.", "Samourai's founders were sentenced.", "The 2024 ruling went the other way."], "explanation": "The law is unsettled. Running, charging for and marketing a tool raise the risk most."}, "proReasoning": "Like a chemist: publishing a formula differs from running a lab for a cartel.", "commonMistake": "Assuming the question is settled either way.", "mentalModel": "Still unsettled."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1ca5b8913296$ml$]::text[]),
($ml$ca141734-0187-5cdc-aad0-2872f92f3e87$ml$::uuid, $ml$web3$ml$, 19, 1, $ml${"id": "web3-d19-c1", "title": "A whole blockchain moves onto Ethereum", "lessonTitle": "Why layer 2 fees fell 99%", "slot": 1, "type": "apply", "brief": {"headline": "On March 26, 2025, Celo halted block production on its own layer 1 and relaunched as a layer 2 on Ethereum, nearly two years after first proposing the move.", "kicker": "Apply day 19: layer 2s settle back to Ethereum for its security.", "fullText": "cLabs first proposed the switch in July 2023. Celo was rebuilt with the OP Stack, Optimism's toolkit, and now runs as an optimistic rollup that posts its data to Ethereum.\n\nBlock times dropped from 5 seconds to 1 second, and Celo gained native bridging to Ethereum. The stated aims were Ethereum's security with low-cost, fast transactions, and closer ties to Ethereum developers.\n\nThrough the day 19 lens: once Dencun gave rollups cheap data space, running on Ethereum got cheaper than ever.", "sources": [{"url": "https://www.theblock.co/post/348146/celo-developers-finalize-ethereum-layer-2-transition-nearly-two-years-after-initial-proposal", "label": "The Block, Celo finalizes its Ethereum layer 2 transition, Mar 2025"}, {"url": "https://www.theblock.co/post/282417/ethereum-layer-2s-show-dramatic-drop-in-transaction-fees-after-dencun", "label": "The Block, layer 2 fees drop after Dencun, Mar 2024"}]}, "evidence": {"kind": "buildChain", "prompt": "Put Celo's move in order.", "steps": ["cLabs proposes moving Celo to a layer 2", "Celo is rebuilt on the OP Stack", "Layer 1 block production is halted", "Celo runs as an optimistic rollup on Ethereum", "Blocks arrive every second instead of five"], "explanation": "Proposed in July 2023, switched on March 26, 2025."}, "numbers": {"kind": "numberSense", "prompt": "About how many months passed between the proposal and the switch?", "min": 0, "max": 48, "value": 20, "explanation": "From July 2023 to March 2025 is about 20 months, by our count.", "unit": "months"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a layer 2 team. They ask why a chain would give up being a layer 1.", "prompt": "Which answer is strongest?", "options": ["To raise fees for its users", "To stop other teams from building apps on it", "To borrow Ethereum's security and developer base"], "correctIndex": 2, "consequences": ["Lower costs were part of the goal.", "It wanted more builders, not fewer.", "Celo cited Ethereum security and ecosystem ties."], "explanation": "A layer 2 settles to Ethereum, so it inherits its security instead of paying for its own."}, "proReasoning": "Strong answers name the trade: less independence for more security and reach.", "commonMistake": "Assuming every chain wants to stay a layer 1.", "mentalModel": "Borrow security."}, "invest": {"call": {"kind": "theCall", "situation": "You hold tokens of a small layer 1 thinking about becoming a layer 2.", "prompt": "What do you weigh?", "options": ["Stronger security versus less independence", "Only whether the logo changes", "Only whether block times stay the same"], "correctIndex": 0, "consequences": ["That trade sits at the center of such moves.", "Branding is not the economic question.", "Celo got faster, but speed is not the main point."], "explanation": "Moving to a layer 2 swaps self-reliance for Ethereum's security and users."}, "proReasoning": "Investors ask what a chain gains and what control it gives up.", "commonMistake": "Judging the move by a single speed number.", "mentalModel": "Weigh the trade."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your payments startup is choosing where to build.", "prompt": "What does Celo's move suggest?", "options": ["Layer 2s cannot connect back to Ethereum at all", "Layer 2s now offer cheap, fast settlement on Ethereum", "Only a new layer 1 can be fast"], "correctIndex": 1, "consequences": ["Celo gained native Ethereum bridging.", "Celo cut block times to one second as a rollup.", "Celo got faster after leaving layer 1."], "explanation": "You can get speed and Ethereum security together on a layer 2."}, "proReasoning": "Founders choose platforms by cost, speed and reach, not by layer label.", "commonMistake": "Building a new chain when a rollup would do.", "mentalModel": "Speed plus security."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what it means that Celo \"became a layer 2.\"", "prompt": "What's the best answer?", "options": ["It merged with Bitcoin to share one network", "It shut down for good", "It now posts its records to Ethereum for safety"], "correctIndex": 2, "consequences": ["Bitcoin was not involved.", "It kept running, faster than before.", "Rollups settle their data back to Ethereum."], "explanation": "A layer 2 runs its own transactions but leans on Ethereum to keep the records safe."}, "proReasoning": "Like a shop moving into a mall with better security guards.", "commonMistake": "Thinking a layer 2 is a weaker copy of a blockchain.", "mentalModel": "Leaning on Ethereum."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:cf735927fe62$ml$]::text[]),
($ml$2f068a31-9b0c-54e0-8386-aedc681521a9$ml$::uuid, $ml$web3$ml$, 19, 2, $ml${"id": "web3-d19-c2", "title": "Cheap enough to use contracts daily", "lessonTitle": "Why layer 2 fees fell 99%", "slot": 2, "type": "connect", "brief": {"headline": "After Dencun in March 2024, a Starknet swap fell from over $6.80 to about $0.04, according to Argent. Smart contract use became practical for small, everyday amounts.", "kicker": "Connect day 13 and day 19: contracts are only useful if people can afford them.", "fullText": "Day 13 showed what smart contracts can do: programs that run as written on a blockchain. Each use costs a fee.\n\nDay 19 showed how Dencun cut that cost on layer 2s by giving rollups blobs, a cheaper place to post data. A swap that cost several dollars dropped to a few cents. That changes which contracts make sense for small users.", "sources": [{"url": "https://www.theblock.co/post/282417/ethereum-layer-2s-show-dramatic-drop-in-transaction-fees-after-dencun", "label": "The Block, layer 2 fees drop after Dencun, Mar 2024"}, {"url": "https://ethereum.org/developers/docs/smart-contracts/", "label": "ethereum.org, smart contracts"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did Dencun give layer 2 networks?", "options": ["A way to skip Ethereum entirely", "Blobs, a cheaper place to post data", "A new coin to replace ETH"], "correctIndex": 1, "explanation": "Blobs gave rollups a cheaper place to post their data back to Ethereum."}, "numbers": {"kind": "numberSense", "prompt": "A Starknet swap fell to about how many cents after Dencun?", "min": 0, "max": 20, "value": 4, "explanation": "About $0.04, down from over $6.80, according to Argent.", "unit": "cents"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your team lead asks why app usage on layer 2s jumped after 2024.", "prompt": "Which reason leads?", "options": ["Contract calls got cheap enough for small users", "Ethereum stopped charging any fees", "Layer 2s became fully separate from Ethereum"], "correctIndex": 0, "consequences": ["Swaps fell from dollars to cents.", "Users still pay small fees.", "Rollups still post data to Ethereum."], "explanation": "A $6.80 swap rules out small trades. At four cents, everyday use works."}, "proReasoning": "Product teams track fees because they decide who can use an app.", "commonMistake": "Ignoring cost when explaining user growth.", "mentalModel": "Cost decides use."}, "invest": {"call": {"kind": "theCall", "situation": "A layer 2 app shows rising users after Dencun.", "prompt": "What question do you ask?", "options": ["Will Ethereum shut down layer 2s?", "Is growth lasting, or just cheaper trades?", "Why does it charge its users any fees at all?"], "correctIndex": 1, "consequences": ["Rollups depend on Ethereum by design.", "Low fees can draw activity that is easy to lose.", "Some fee is part of using a network."], "explanation": "Cheap fees open the door. Investors still need to see users who stay."}, "proReasoning": "Investors separate fee-driven activity from real demand.", "commonMistake": "Reading every usage jump as lasting demand.", "mentalModel": "Test the growth."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants to launch micro-payments with smart contracts.", "prompt": "Where do you build?", "options": ["On Ethereum's main chain only", "On paper until fees reach zero", "On a layer 2 where fees are cents"], "correctIndex": 2, "consequences": ["Main-chain fees are higher for small amounts.", "Waiting for zero fees means never launching.", "Small payments need tiny fees."], "explanation": "Micro-payments only work when a fee is a small slice of the payment."}, "proReasoning": "Founders match a product's ticket size to the platform's fee.", "commonMistake": "Building small payments where fees eat the value.", "mentalModel": "Match fee to payment."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why crypto apps suddenly felt usable in 2024.", "prompt": "What's the best answer?", "options": ["An upgrade made layer 2 fees fall to cents", "Banks started paying the fees for their customers", "Phones got faster that year"], "correctIndex": 0, "consequences": ["Dencun cut swap fees from dollars to cents.", "Banks do not pay these fees.", "Fees, not phones, were the barrier."], "explanation": "Each app action costs a fee. Dencun made those fees tiny on layer 2s."}, "proReasoning": "Like a toll road dropping its toll from dollars to pennies.", "commonMistake": "Thinking the apps changed rather than the costs.", "mentalModel": "Tolls dropped."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b86b4bcb7748$ml$]::text[]),
($ml$2dc51024-3515-518a-9411-28dc1846b7cf$ml$::uuid, $ml$web3$ml$, 19, 3, $ml${"id": "web3-d19-c3", "title": "Layer 1 or layer 2 for your wallet app?", "lessonTitle": "Why layer 2 fees fell 99%", "slot": 3, "type": "decide", "brief": {"headline": "You are launching a consumer wallet app. After Dencun, Base's median fee fell from about $0.50 to about $0.0012, based on Dune data.", "kicker": "Decide where your users will transact.", "fullText": "A layer 1 is the base blockchain. A layer 2 runs on top and settles back to it, bundling many transactions into one post.\n\nDencun gave rollups blobs, a cheaper place for that data. For a consumer app, a fee of half a dollar per action and a fee of a tenth of a cent are very different products.", "sources": [{"url": "https://www.theblock.co/post/282417/ethereum-layer-2s-show-dramatic-drop-in-transaction-fees-after-dencun", "label": "The Block, layer 2 fees drop after Dencun, Mar 2024"}]}, "evidence": {"kind": "faceOff", "prompt": "Which suits a consumer app with many small actions?", "left": {"name": "A layer 2 after Dencun", "note": "Median fees around a tenth of a cent on Base"}, "right": {"name": "Ethereum's main chain", "note": "Higher fees for each small action"}, "correctIndex": 0, "explanation": "Small actions need tiny fees. Layer 2s now offer them while settling to Ethereum."}, "numbers": {"kind": "numberSense", "prompt": "Before Dencun, Base's median fee was about how many cents?", "min": 0, "max": 80, "value": 50, "explanation": "About $0.50, falling to about $0.0012 after Dencun.", "unit": "cents"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your product lead asks where to launch.", "prompt": "What do you recommend?", "options": ["A brand new layer 1 chain that we run ourselves", "A layer 2 for daily actions, settling to Ethereum", "The main chain for every tap"], "correctIndex": 1, "consequences": ["A new chain costs time and security.", "Users pay fractions of a cent.", "Fees would add up fast for users."], "explanation": "For many small actions, the layer 2 fee level makes the app usable."}, "proReasoning": "Product teams pick the layer that matches how often users act.", "commonMistake": "Choosing the main chain out of habit.", "mentalModel": "Fit the layer to usage."}, "invest": {"call": {"kind": "theCall", "situation": "You compare two wallet startups.", "prompt": "Which plan looks stronger?", "options": ["Charging users full main-chain fees", "Waiting for fees to vanish", "Building on a low-fee layer 2"], "correctIndex": 2, "consequences": ["High fees drive users away.", "Waiting delays any traction.", "Low fees support everyday use."], "explanation": "Fees shape retention. Investors favor products users can afford to use daily."}, "proReasoning": "Investors ask what each user action costs.", "commonMistake": "Ignoring per-action cost in the pitch.", "mentalModel": "Ask the unit cost."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup must hit 10,000 daily users this year.", "prompt": "Which move helps most?", "options": ["Launch on a layer 2 with sub-cent fees", "Add more features on the main chain", "Pay every fee yourself on the main chain"], "correctIndex": 0, "consequences": ["Cheap actions keep users coming back.", "Features do not fix a costly tap.", "Subsidies burn cash fast."], "explanation": "Cutting the cost of each action is the fastest way to more daily use."}, "proReasoning": "Founders remove the biggest friction first.", "commonMistake": "Paying to hide a cost you could avoid.", "mentalModel": "Remove friction."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what a layer 2 is.", "prompt": "What's the best answer?", "options": ["A faster kind of Wi-Fi made for crypto apps", "A network on Ethereum that bundles activity", "A second Bitcoin"], "correctIndex": 1, "consequences": ["It is software, not a network cable.", "Rollups post bundles of data back to Ethereum.", "It is unrelated to Bitcoin."], "explanation": "Layer 2s handle many transactions and settle a summary on Ethereum, sharing the cost."}, "proReasoning": "Like carpooling to split one toll.", "commonMistake": "Thinking a layer 2 is a separate, unconnected chain.", "mentalModel": "Carpooling."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:950bc0c84be4$ml$]::text[]),
($ml$54ad8c2d-988e-527f-800f-d1012b0cda3a$ml$::uuid, $ml$web3$ml$, 20, 1, $ml${"id": "web3-d20-c1", "title": "Uniswap builds its own layer 2", "lessonTitle": "How a layer 2 makes money", "slot": 1, "type": "apply", "brief": {"headline": "On February 11, 2025, Uniswap Labs launched Unichain, its own Ethereum layer 2, with 1 to 2 second block times.", "kicker": "Apply day 20: whoever runs the sequencer keeps the fees.", "fullText": "Unichain launched two weeks after Uniswap v4. The team said 65% of Unichain's net chain revenue would go to validators and stakers in its Unichain Validation Network.\n\nUniswap has long run on other chains, where others collect the transaction fees. Running its own layer 2 means its own network earns the sequencer revenue.\n\nThrough the day 20 lens: a layer 2 earns fees minus data costs. Owning the chain lets an app capture that margin.", "sources": [{"url": "https://www.theblock.co/post/339930/uniswap-labs-launches-unichain-ethereum-scaling-solution-in-mainnet", "label": "The Block, Uniswap Labs launches Unichain on mainnet, Feb 2025"}, {"url": "https://www.talos.com/insights/state-of-the-network-350", "label": "Talos, Base sequencer revenue estimate, Q4 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What share of Unichain's net chain revenue was set to go to validators and stakers?", "options": ["100%", "10%", "65%"], "correctIndex": 2, "explanation": "65% of net chain revenue, Uniswap Labs said."}, "numbers": {"kind": "numberSense", "prompt": "About what percent of net chain revenue was set for Unichain validators and stakers?", "min": 0, "max": 100, "value": 65, "explanation": "65%, as Uniswap Labs announced at launch.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a DeFi company. They ask why Uniswap launched a layer 2.", "prompt": "Which answer lands best?", "options": ["To keep sequencer revenue its activity creates", "To stop its users trading on Ethereum at all", "To avoid paying any data costs"], "correctIndex": 0, "consequences": ["Its trades earned fees for other chains.", "It still settles to Ethereum.", "Layer 2s still pay Ethereum for data."], "explanation": "Big apps generate fees. Owning the chain lets them keep the sequencer margin."}, "proReasoning": "Strong answers tie the move to who earns the fees.", "commonMistake": "Thinking app chains are only about speed.", "mentalModel": "Keep the margin."}, "invest": {"call": {"kind": "theCall", "situation": "You weigh a DeFi app launching its own layer 2.", "prompt": "What do you check?", "options": ["Will block times stay over 10 seconds?", "Will its fees cover data costs and shares?", "Will it change its token's logo?"], "correctIndex": 1, "consequences": ["Unichain runs 1 to 2 second blocks.", "Revenue is fees minus costs and revenue shares.", "Branding does not move revenue."], "explanation": "An app chain needs enough paid activity to beat its data costs and payouts."}, "proReasoning": "Investors model net revenue, not gross fees.", "commonMistake": "Valuing an app chain on gross fees alone.", "mentalModel": "Model net revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app has strong volume on a layer 2 you do not run.", "prompt": "When does your own chain make sense?", "options": ["As soon as you have any users", "Never, since chains earn nothing", "When your fees would cover running it"], "correctIndex": 2, "consequences": ["Small apps rarely cover the costs.", "Base earned about $15 million net in one quarter.", "Net revenue must beat costs."], "explanation": "Owning a chain pays only at scale. Below that, renting space is cheaper."}, "proReasoning": "Founders build infrastructure after demand proves it.", "commonMistake": "Launching a chain before the volume justifies it.", "mentalModel": "Scale first."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a trading app would launch its own blockchain.", "prompt": "What's the best answer?", "options": ["So the fees its users pay stay in its network", "To make trading on other networks illegal", "Because Ethereum stopped working"], "correctIndex": 0, "consequences": ["Sequencer fees go to whoever runs the chain.", "It cannot ban other chains.", "Ethereum kept working."], "explanation": "Every trade pays a fee to someone. Running the chain means keeping more of it."}, "proReasoning": "Like a shop opening its own payment terminal to stop paying card fees.", "commonMistake": "Thinking the move was mainly technical.", "mentalModel": "Keep the fees."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e9c7981ad290$ml$]::text[]),
($ml$910e0e22-4cea-5c83-83e6-17999c692c15$ml$::uuid, $ml$web3$ml$, 20, 2, $ml${"id": "web3-d20-c2", "title": "Cheaper data, thinner fees", "lessonTitle": "How a layer 2 makes money", "slot": 2, "type": "connect", "brief": {"headline": "Dencun cut layer 2 data costs in March 2024. By Q4 2025, Base earned about $19 million in gross sequencer revenue and about $15 million net, a Talos estimate.", "kicker": "Connect day 19 and day 20: the same upgrade cut costs and prices.", "fullText": "Day 19 showed how Dencun gave rollups blobs and pushed Base's median fee from about $0.50 to about $0.0012. Day 20 showed what Base keeps: fees minus Ethereum data costs and its share to the Optimism Collective.\n\nCheaper data lowered Base's costs. It also let fees fall, so each transaction brings in less. In July 2026, Coinbase said Base revenue fell even as stablecoin volume grew sevenfold.", "sources": [{"url": "https://www.theblock.co/post/282417/ethereum-layer-2s-show-dramatic-drop-in-transaction-fees-after-dencun", "label": "The Block, layer 2 fees drop after Dencun, Mar 2024"}, {"url": "https://www.talos.com/insights/state-of-the-network-350", "label": "Talos, Base sequencer revenue estimate, Q4 2025"}, {"url": "https://thedefiant.io/news/cefi/coinbase-says-revenue-from-its-base-layer-2-fell-despite-record-volume", "label": "The Defiant, Coinbase says Base revenue fell despite record volume, Jul 2026"}]}, "evidence": {"kind": "buildChain", "prompt": "Trace how Dencun reached Base's revenue.", "steps": ["Dencun gives rollups cheap blob space", "Base's data costs fall", "Base's user fees fall too", "Each transaction earns less", "Revenue can fall even as volume grows"], "explanation": "Lower costs and lower prices together squeezed revenue per transaction."}, "numbers": {"kind": "numberSense", "prompt": "Base's net sequencer revenue in Q4 2025 was about how many million dollars?", "min": 0, "max": 40, "value": 15, "explanation": "About $15 million net, from about $19 million gross.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks why Base revenue fell while volume rose.", "prompt": "Which answer is best?", "options": ["Ethereum raised its data costs sharply that year", "Fees per transaction fell faster than volume grew", "Users stopped using Base entirely"], "correctIndex": 1, "consequences": ["Dencun lowered data costs.", "Cheap fees shrink revenue per transaction.", "Stablecoin volume grew sevenfold."], "explanation": "Revenue is price times volume. When price collapses, volume has to grow even faster."}, "proReasoning": "Analysts break revenue into price and volume before explaining it.", "commonMistake": "Assuming more usage always means more revenue.", "mentalModel": "Price times volume."}, "invest": {"call": {"kind": "theCall", "situation": "You model a layer 2 business.", "prompt": "What assumption is riskiest?", "options": ["That data costs will matter at all", "That volume can grow", "That fees per transaction stay high"], "correctIndex": 2, "consequences": ["Data costs are part of the margin.", "Volume did grow on Base.", "Fees fell to fractions of a cent."], "explanation": "Cheap fees help users but cap revenue. Plan for thin fees."}, "proReasoning": "Investors test models against falling prices.", "commonMistake": "Building a forecast on old fee levels.", "mentalModel": "Plan for thin fees."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells to layer 2 teams.", "prompt": "What pain can you solve?", "options": ["Revenue beyond thin transaction fees", "Higher fees users will happily pay", "Removing data costs entirely"], "correctIndex": 0, "consequences": ["Layer 2s need other income.", "Users left high fees behind.", "Data costs are set by Ethereum."], "explanation": "Layer 2s carry more traffic for less money. Tools that add revenue meet a real need."}, "proReasoning": "Founders follow where their customers' margins are under pressure.", "commonMistake": "Selling a plan to raise fees users just escaped.", "mentalModel": "Solve the margin."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a busier network can earn less.", "prompt": "What's the best answer?", "options": ["Fewer people used it", "Each transaction got much cheaper", "The network stopped charging fees"], "correctIndex": 1, "consequences": ["Volume grew sevenfold.", "Fees fell from cents to fractions of a cent.", "It still charges small fees."], "explanation": "If each sale is tiny, more sales can still add up to less money."}, "proReasoning": "Like a shop cutting prices so far that full shelves earn less.", "commonMistake": "Assuming busy always means profitable.", "mentalModel": "Cheaper each time."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c269ea5265fe$ml$]::text[]),
($ml$afc49f57-e836-556f-b513-c4cd9744aecf$ml$::uuid, $ml$web3$ml$, 20, 3, $ml${"id": "web3-d20-c3", "title": "Where will your layer 2 earn money?", "lessonTitle": "How a layer 2 makes money", "slot": 3, "type": "decide", "brief": {"headline": "You run a young layer 2. Base earned about $19 million gross from its sequencer in Q4 2025, yet later reported falling revenue as usage grew.", "kicker": "Decide how your layer 2 will pay its way.", "fullText": "A sequencer orders transactions and collects fees. A layer 2 keeps those fees minus Ethereum data costs and any revenue share.\n\nCheap fees cut both ways: they draw users but leave little per transaction. Your chain needs revenue that does not depend only on fees.", "sources": [{"url": "https://www.talos.com/insights/state-of-the-network-350", "label": "Talos, Base sequencer revenue estimate, Q4 2025"}, {"url": "https://thedefiant.io/news/cefi/coinbase-says-revenue-from-its-base-layer-2-fell-despite-record-volume", "label": "The Defiant, Coinbase says Base revenue fell despite record volume, Jul 2026"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is this a cost or a source of revenue for your layer 2?", "buckets": ["Cost", "Revenue"], "items": [{"text": "Posting data to Ethereum", "bucket": 0}, {"text": "A share paid to a partner collective", "bucket": 0}, {"text": "Fees users pay per transaction", "bucket": 1}, {"text": "Services sold to apps on the chain", "bucket": 1}, {"text": "Payments to run the sequencer hardware", "bucket": 0}], "explanation": "Revenue minus data costs and shares is what a layer 2 keeps."}, "numbers": {"kind": "numberSense", "prompt": "Stablecoin volume on Base grew about how many times as revenue fell?", "min": 0, "max": 20, "value": 7, "explanation": "About sevenfold, while revenue fell, Coinbase said.", "unit": "times"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your board asks for a revenue plan.", "prompt": "What do you propose?", "options": ["Raise transaction fees tenfold next year", "Stop paying for Ethereum data", "Add paid services, not just transaction fees"], "correctIndex": 2, "consequences": ["Users would move to cheaper chains.", "A rollup must post its data.", "Fee income alone stays thin."], "explanation": "Fees will stay low. A layer 2 needs other income to cover costs."}, "proReasoning": "Leaders plan revenue around the market price, not the old one.", "commonMistake": "Betting the chain on fees users will not pay.", "mentalModel": "Diversify revenue."}, "invest": {"call": {"kind": "theCall", "situation": "A layer 2 you follow reports record volume.", "prompt": "What do you look at next?", "options": ["Net revenue after data costs", "The number of logos on its site", "Its daily social media posts"], "correctIndex": 0, "consequences": ["Volume alone can hide falling revenue.", "Logos do not pay costs.", "Posts are not revenue."], "explanation": "Base showed volume can rise while revenue falls. Net revenue is the real test."}, "proReasoning": "Investors look past volume to the margin.", "commonMistake": "Celebrating volume without checking revenue.", "mentalModel": "Check the margin."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup could build on a layer 2 or run its own.", "prompt": "What tips the decision?", "options": ["Whether others launched chains too", "Whether your fees would beat the costs", "Whether you like the name better"], "correctIndex": 1, "consequences": ["Following others is not a plan.", "Running a chain has real costs.", "Names do not cover costs."], "explanation": "A chain is a business with costs. Run one only if your activity pays for it."}, "proReasoning": "Founders do the margin math before building infrastructure.", "commonMistake": "Launching a chain because it is fashionable.", "mentalModel": "Do the math."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a layer 2 network makes money.", "prompt": "What's the best answer?", "options": ["It mines new bitcoin", "It charges a monthly subscription", "It keeps user fees minus its data costs"], "correctIndex": 2, "consequences": ["Layer 2s do not mine bitcoin.", "Users pay per transaction.", "That is the core sequencer model."], "explanation": "Users pay small fees. The network pays Ethereum for data and keeps the rest."}, "proReasoning": "Like a delivery service keeping fees after paying for the truck.", "commonMistake": "Thinking layer 2s earn from token prices alone.", "mentalModel": "Fees minus costs."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b4de8137ce1a$ml$]::text[]),
($ml$ce5088f8-4602-5392-b7ee-bd6e262f9add$ml$::uuid, $ml$web3$ml$, 21, 1, $ml${"id": "web3-d21-c1", "title": "The first ZK-rollup at Stage 1", "lessonTitle": "Who can override a layer 2?", "slot": 1, "type": "apply", "brief": {"headline": "In May 2025, Starknet reached Stage 1, becoming the only ZK-rollup at that stage, according to L2BEAT data reported by FXStreet.", "kicker": "Apply day 21: a stage tells you who can still override a layer 2.", "fullText": "To get there, Starknet created a security council and added ways for users to avoid censorship. Its validity proof system is now governed by smart contracts.\n\nL2BEAT showed Starknet securing about $629 million, about 1.4% of layer 2 value, fifth largest. The four bigger networks were all optimistic rollups at Stage 1, and only three small layer 2s had reached Stage 2.\n\nThrough the day 21 lens: at Stage 1, proofs are live and a council can step in only in emergencies.", "sources": [{"url": "https://www.fxstreet.com/cryptocurrencies/news/starknet-hits-stage-one-decentralization-tops-zk-rollups-for-value-locked-202505160850", "label": "FXStreet, Starknet hits Stage 1 decentralization, May 2025"}, {"url": "https://www.growthepie.com/answers/ethereum-l2-maturity-stages", "label": "growthepie, Ethereum L2 maturity stages"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Starknet was the only ZK-rollup at Stage 1", "The four larger layer 2s were all at Stage 1", "Most layer 2s had already reached Stage 2"], "fakeIndex": 2, "explanation": "Only three small layer 2s had reached Stage 2, L2BEAT data showed."}, "numbers": {"kind": "numberSense", "prompt": "Starknet secured about how many million dollars in May 2025?", "min": 0, "max": 1500, "value": 629, "explanation": "About $629 million, about 1.4% of layer 2 value.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a layer 2 team. They ask what Stage 1 means.", "prompt": "Which answer is strongest?", "options": ["A single company signs every block it ever makes", "Proofs are live; a council acts only in emergencies", "No one can ever change the network again"], "correctIndex": 1, "consequences": ["That is not what stages measure.", "That matches the stage definition.", "That would be closer to Stage 2."], "explanation": "Stages measure who can override a rollup. Stage 1 keeps a council for emergencies only."}, "proReasoning": "Strong candidates explain the training wheels that remain at each stage.", "commonMistake": "Treating Stage 1 as fully trustless.", "mentalModel": "Emergencies only."}, "invest": {"call": {"kind": "theCall", "situation": "You compare two layer 2 tokens for a research note.", "prompt": "Which fact belongs in the risk section?", "options": ["Which logo color each network picked", "How many tweets each team posted", "Which stage each network has reached"], "correctIndex": 2, "consequences": ["Colors carry no risk information.", "Posts say little about control.", "Stage shows who can override the chain."], "explanation": "A Stage 0 network can be overridden by a council. That is a real risk for users."}, "proReasoning": "Analysts check stage ratings before comparing growth.", "commonMistake": "Ignoring who can change the rules.", "mentalModel": "Check the stage."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup is choosing a rollup framework.", "prompt": "What does Starknet's step show?", "options": ["A ZK design can reach Stage 1 with a council", "Only optimistic rollups can reach Stage 1", "Stages do not matter to app builders"], "correctIndex": 0, "consequences": ["Starknet did it in May 2025.", "Starknet was a ZK-rollup at Stage 1.", "Users care who can override funds."], "explanation": "Both rollup families can reach Stage 1. Pick on tech and stage, not one label."}, "proReasoning": "Founders check the stage roadmap of any chain they build on.", "commonMistake": "Assuming one rollup type is always safer.", "mentalModel": "Both can mature."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what the \"training wheels\" of a layer 2 are.", "prompt": "What's the best answer?", "options": ["Speed limits on how fast you can trade on it", "Powers a council keeps to step in or override", "Extra coins handed out to new users"], "correctIndex": 1, "consequences": ["Speed is a separate question.", "Stages track how many of those powers remain.", "Training wheels are about control."], "explanation": "Young layer 2s keep override powers in case of bugs. Stages show how many remain."}, "proReasoning": "Like a learner driver: the instructor's brake comes off in steps.", "commonMistake": "Thinking all layer 2s are equally independent.", "mentalModel": "Brakes come off in steps."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8587008c0cef$ml$]::text[]),
($ml$a70f7e6e-2b03-5c40-bb7b-dabd6ff5efac$ml$::uuid, $ml$web3$ml$, 21, 2, $ml${"id": "web3-d21-c2", "title": "The earner that kept the brakes", "lessonTitle": "Who can override a layer 2?", "slot": 2, "type": "connect", "brief": {"headline": "Base earned about $15 million in net sequencer revenue in Q4 2025. It reached Stage 1 in 2025, so a security council can still act in emergencies.", "kicker": "Connect day 20 and day 21: who earns the fees and who holds the brakes.", "fullText": "Day 20 showed that Base, run by Coinbase, keeps user fees minus data costs. Talos estimated about $19 million gross and $15 million net in Q4 2025.\n\nDay 21 showed what Stage 1 means: proofs are live and a council can override only in emergencies. Vitalik Buterin has said he recognizes only Stage 1 or higher networks as rollups. A network can earn steadily while still keeping emergency powers.", "sources": [{"url": "https://www.talos.com/insights/state-of-the-network-350", "label": "Talos, Base sequencer revenue estimate, Q4 2025"}, {"url": "https://beincrypto.com/base-overtakes-arbitrum-layer-2/", "label": "BeInCrypto, Base beats Arbitrum and reaches Stage 1"}, {"url": "https://www.growthepie.com/answers/ethereum-l2-maturity-stages", "label": "growthepie, Ethereum L2 maturity stages"}]}, "evidence": {"kind": "faceOff", "prompt": "Which question tells you who can still change Base?", "left": {"name": "What stage it has reached", "note": "Stage 1: a council acts only in emergencies"}, "right": {"name": "How much revenue it earned", "note": "About $15 million net in Q4 2025"}, "correctIndex": 0, "explanation": "Revenue shows the business. Stage shows who holds the override powers."}, "numbers": {"kind": "numberSense", "prompt": "Base earned about how many million dollars of gross sequencer revenue in Q4 2025?", "min": 0, "max": 50, "value": 19, "explanation": "About $19 million gross, $15 million net, a Talos estimate.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks you to profile Base in one slide.", "prompt": "Which pair of facts leads?", "options": ["Its logo history and office locations", "Its block color and font choices", "Its fee revenue and its Stage 1 status"], "correctIndex": 2, "consequences": ["Those do not explain the business.", "Those do not explain the risk.", "Revenue plus control tells the full story."], "explanation": "A layer 2 is a business and a set of powers. Show both."}, "proReasoning": "Analysts pair economics with governance.", "commonMistake": "Showing revenue with no word on control.", "mentalModel": "Money plus powers."}, "invest": {"call": {"kind": "theCall", "situation": "You weigh a company that earns from its layer 2.", "prompt": "What do you ask beside revenue?", "options": ["Who can override the chain and when", "Whether the token has a mascot yet", "Whether its fees will go back to $0.50"], "correctIndex": 0, "consequences": ["Stage 1 limits overrides to emergencies.", "Mascots do not change risk.", "Fees fell after Dencun."], "explanation": "Revenue depends on users trusting the chain. Override powers shape that trust."}, "proReasoning": "Investors check control risks alongside cash flows.", "commonMistake": "Valuing chain revenue without asking about control.", "mentalModel": "Ask about control."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup plans its own layer 2 for revenue.", "prompt": "What must you plan from day one?", "options": ["A plan to skip proofs to save costs", "A path from Stage 0 to Stage 1", "A way to keep full control forever"], "correctIndex": 1, "consequences": ["Live proofs are needed for Stage 1.", "Users and Vitalik look for Stage 1 or higher.", "That keeps you at Stage 0."], "explanation": "Revenue needs users, and users want limits on who can override."}, "proReasoning": "Founders publish a stage roadmap early.", "commonMistake": "Treating decentralization as a later problem.", "mentalModel": "Plan the stages."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if Coinbase controls Base.", "prompt": "What's the best answer?", "options": ["No one runs Base, and no one earns from it at all", "Coinbase can change any balance at will", "It runs it, but a council has only emergency powers"], "correctIndex": 2, "consequences": ["Coinbase earns its sequencer fees.", "Stage 1 limits that power.", "At Stage 1, overrides are for emergencies only."], "explanation": "Coinbase runs Base and earns its fees. Stage 1 limits overrides to emergencies."}, "proReasoning": "Running something and fully controlling it are different.", "commonMistake": "Assuming the company can do anything it likes.", "mentalModel": "Runs, but limited."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9bcf7c647374$ml$]::text[]),
($ml$5a8301f9-17c1-5908-9ddc-eb670f40de2d$ml$::uuid, $ml$web3$ml$, 21, 3, $ml${"id": "web3-d21-c3", "title": "Launch on a Stage 0 or Stage 1 network?", "lessonTitle": "Who can override a layer 2?", "slot": 3, "type": "decide", "brief": {"headline": "You are launching a lending app on a layer 2. One network is at Stage 0, with a council that can override and no live proofs. Another is at Stage 1.", "kicker": "Decide which network your users' funds should sit on.", "fullText": "At Stage 0, a council can override the network and proofs are not live. At Stage 1, proofs are live and the council can act only in emergencies.\n\nThe Stage 0 network offers you a launch grant. By 2026, very few networks had reached Stage 2.", "sources": [{"url": "https://www.growthepie.com/answers/ethereum-l2-maturity-stages", "label": "growthepie, Ethereum L2 maturity stages"}, {"url": "https://beincrypto.com/base-overtakes-arbitrum-layer-2/", "label": "BeInCrypto, Base beats Arbitrum and reaches Stage 1"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this point to the Stage 1 network or the Stage 0 one?", "buckets": ["Stage 1 network", "Stage 0 network"], "items": [{"text": "Users will deposit large sums", "bucket": 0}, {"text": "You want live proofs protecting funds", "bucket": 0}, {"text": "You are only testing with play money", "bucket": 1}, {"text": "A grant matters more than safety now", "bucket": 1}, {"text": "Partners ask who can override the chain", "bucket": 0}], "explanation": "Real funds favor live proofs and limited overrides. Tests can tolerate more risk."}, "numbers": {"kind": "numberSense", "prompt": "How many stages does the layer 2 scale have, counting Stage 0?", "min": 0, "max": 10, "value": 3, "explanation": "Three: Stage 0, Stage 1 and Stage 2.", "unit": "stages"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO asks where to launch.", "prompt": "What do you recommend?", "options": ["The Stage 1 network for real user funds", "The Stage 0 network because of the grant", "Both at once with no stage disclosure"], "correctIndex": 0, "consequences": ["Live proofs protect deposits.", "A grant does not offset override risk.", "Users deserve to know the risk."], "explanation": "Lending holds user money. Pick the network with live proofs and limited overrides."}, "proReasoning": "Leaders match platform risk to what users entrust to them.", "commonMistake": "Letting a grant decide where deposits sit.", "mentalModel": "Safety over grants."}, "invest": {"call": {"kind": "theCall", "situation": "A lending app you follow launches on a Stage 0 network.", "prompt": "What risk do you flag?", "options": ["Stage 0 networks cannot hold stablecoins", "A council could override the chain", "Fees on Stage 0 are always higher"], "correctIndex": 1, "consequences": ["They can hold stablecoins.", "That is the Stage 0 definition.", "Stage is about control, not fees."], "explanation": "At Stage 0, users rely on a council behaving well."}, "proReasoning": "Investors read the stage before the growth chart.", "commonMistake": "Assuming every layer 2 offers the same protection.", "mentalModel": "Read the stage."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants grant money but also user trust.", "prompt": "Which plan fits best?", "options": ["Put everything on Stage 0 to keep the grant", "Skip layer 2s and build a new chain", "Test on Stage 0, put real funds on Stage 1"], "correctIndex": 2, "consequences": ["Real deposits face override risk.", "A new chain adds cost and risk.", "You get both learning and safety."], "explanation": "Use the cheap network for testing. Keep real deposits where protections are stronger."}, "proReasoning": "Founders separate experiments from user money.", "commonMistake": "Mixing test risk with customer funds.", "mentalModel": "Test cheap, hold safe."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why stages matter if both networks work.", "prompt": "What's the best answer?", "options": ["They show who could override your funds", "They show which network is faster", "They rank networks by their coin price"], "correctIndex": 0, "consequences": ["Stage 0 lets a council override.", "Speed is not what stages measure.", "Price has nothing to do with stages."], "explanation": "Two networks can feel the same until something goes wrong. Stages show who can step in."}, "proReasoning": "Like checking who holds a spare key to your house.", "commonMistake": "Judging a network only when things go well.", "mentalModel": "Who holds the spare key."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:001c565ebd55$ml$]::text[]),
($ml$da99f718-b5e8-578e-b348-73f260834dd1$ml$::uuid, $ml$web3$ml$, 22, 1, $ml${"id": "web3-d22-c1", "title": "More room than anyone used", "lessonTitle": "Ethereum more than doubles its data room", "slot": 1, "type": "apply", "brief": {"headline": "In January 2026, MigaLabs found that after Fusaka's capacity increases, Ethereum was not reaching its new target of 14 blobs per slot. The median even fell from 6 to 4 blobs.", "kicker": "Apply day 22: more data room only matters if demand fills it.", "fullText": "MigaLabs studied over 750,000 slots. It found slots with 16 to 21 blobs were missed at higher rates, about 0.77% to 1.79%, against about 0.5% for smaller ones, though samples were small.\n\nIt advised against further increases until miss rates normalise and demand uses the space. An April 2026 follow-up found the link had disappeared, likely due to a client database issue.\n\nThrough the day 22 lens: Fusaka raised the target from 6 toward 14 blobs. Capacity rose faster than use.", "sources": [{"url": "https://ethresear.ch/t/blob-analysis-after-fusaka-and-bpo-updates/23853", "label": "MigaLabs on ethresear.ch, blob analysis after Fusaka and BPO updates, Jan 2026"}, {"url": "https://blog.ethereum.org/2025/11/06/fusaka-mainnet-announcement", "label": "Ethereum Foundation blog, Fusaka mainnet announcement"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the blob story in order.", "steps": ["Fusaka goes live on Ethereum", "Blob targets are raised in steps", "MigaLabs finds use below the new target", "It advises pausing further increases", "A follow-up finds the miss link disappeared"], "explanation": "December 2025, January 2026 steps, the January report, then the April follow-up."}, "numbers": {"kind": "numberSense", "prompt": "MigaLabs studied over how many thousand slots?", "min": 0, "max": 2000, "value": 750, "explanation": "Over 750,000 slots.", "unit": "K"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join an Ethereum research team. Your lead asks what the MigaLabs data shows.", "prompt": "Which summary is best?", "options": ["Blobs became too expensive for layer 2s", "Fusaka cut the blob target back to six", "Capacity rose faster than demand for blobs"], "correctIndex": 2, "consequences": ["Unused space pushes blob prices down.", "The target rose toward 14.", "The median fell while the target rose."], "explanation": "The network had more room than layer 2s used. That is a demand question."}, "proReasoning": "Researchers separate capacity from use.", "commonMistake": "Assuming more capacity means more use.", "mentalModel": "Supply ahead of demand."}, "invest": {"call": {"kind": "theCall", "situation": "You follow a layer 2 that posts data in blobs.", "prompt": "What does spare blob space mean for it?", "options": ["Its data costs should stay low", "It must stop posting data", "Its users must pay more fees"], "correctIndex": 0, "consequences": ["Unused space keeps blob prices down.", "Rollups keep posting data.", "Cheap data does not raise fees."], "explanation": "When blob space goes unused, layer 2 data costs stay low."}, "proReasoning": "Investors track blob use to model layer 2 costs.", "commonMistake": "Ignoring data costs in layer 2 margins.", "mentalModel": "Spare room is cheap."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds Ethereum node tools.", "prompt": "What need does the MigaLabs report point to?", "options": ["Apps that hide missed slots from users", "Monitoring that spots missed slots early", "Tools that raise the blob target alone"], "correctIndex": 1, "consequences": ["Hiding data helps no one.", "Miss rates guided the advice.", "Targets change through upgrades."], "explanation": "Node teams need to see when bigger slots cause problems."}, "proReasoning": "Founders build tools for questions researchers are asking.", "commonMistake": "Building features no one can safely use.", "mentalModel": "Measure the misses."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Ethereum added room no one used.", "prompt": "What's the best answer?", "options": ["Users asked for fewer blobs per slot last year", "The upgrade failed and was cancelled", "It built ahead of demand, then paused to check"], "correctIndex": 2, "consequences": ["Use fell, but no one asked for that.", "Fusaka went live in December 2025.", "MigaLabs advised waiting for demand."], "explanation": "Ethereum raised capacity in steps. Researchers checked whether it was used and safe."}, "proReasoning": "Like adding highway lanes before traffic grows.", "commonMistake": "Thinking unused capacity means the upgrade failed.", "mentalModel": "Lanes before traffic."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2f5df408f727$ml$]::text[]),
($ml$06326bdb-fbad-500e-b561-7931471beb4a$ml$::uuid, $ml$web3$ml$, 22, 2, $ml${"id": "web3-d22-c2", "title": "From six blobs to fourteen", "lessonTitle": "Ethereum more than doubles its data room", "slot": 2, "type": "connect", "brief": {"headline": "Dencun introduced blobs in March 2024 and cut layer 2 fees sharply. Fusaka, live December 3, 2025, raised the blob target from 6 to 14 by January 2026.", "kicker": "Connect day 19 and day 22: blobs cut fees, then the room grew.", "fullText": "Day 19 showed how blobs gave rollups a cheaper place for data. Base's median fee fell from about $0.50 to about $0.0012.\n\nDay 22 showed the next step. Fusaka raised the target to 10 blobs in December and 14 in January, with a maximum of 21. PeerDAS lets nodes check data by sampling pieces rather than downloading everything.", "sources": [{"url": "https://www.theblock.co/post/282417/ethereum-layer-2s-show-dramatic-drop-in-transaction-fees-after-dencun", "label": "The Block, layer 2 fees drop after Dencun, Mar 2024"}, {"url": "https://blog.ethereum.org/2025/11/06/fusaka-mainnet-announcement", "label": "Ethereum Foundation blog, Fusaka mainnet announcement"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What lets Ethereum nodes check blob data without downloading all of it?", "options": ["A new layer 1 chain", "PeerDAS sampling", "A bigger gas token"], "correctIndex": 1, "explanation": "PeerDAS lets nodes sample pieces of blob data instead of downloading everything."}, "numbers": {"kind": "numberSense", "prompt": "Fusaka raised the blob target to how many by January 2026?", "min": 0, "max": 30, "value": 14, "explanation": "From 6 to 10 in December, then 14 in January.", "unit": "blobs"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks you to explain why Fusaka matters to rollups.", "prompt": "Which answer leads?", "options": ["More blob room keeps rollup data cheap", "It forces rollups to use the main chain", "It ends the need for layer 2s"], "correctIndex": 0, "consequences": ["The target rose from 6 to 14.", "Rollups still post into blobs.", "Layer 2s still carry most activity."], "explanation": "Blobs cut costs once. Fusaka added room so costs can stay low as use grows."}, "proReasoning": "Analysts link each upgrade to its effect on costs.", "commonMistake": "Treating each upgrade as unrelated.", "mentalModel": "Room keeps it cheap."}, "invest": {"call": {"kind": "theCall", "situation": "You model a layer 2's costs for next year.", "prompt": "What does Fusaka change?", "options": ["Nothing, since layer 2s pay no data costs", "Data room grew, easing pressure on blob costs", "Data costs rise because blobs are gone"], "correctIndex": 1, "consequences": ["Layer 2s do pay for data.", "Target rose to 14, max to 21.", "Blobs remain."], "explanation": "More blob space means more room before data prices rise."}, "proReasoning": "Investors update cost models after each capacity change.", "commonMistake": "Using pre-Fusaka capacity in a 2026 model.", "mentalModel": "Update the model."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup is a data-heavy rollup.", "prompt": "How do you plan around the upgrades?", "options": ["Move all data back to costly calldata", "Wait for blobs to be removed", "Use the extra blob room while it is cheap"], "correctIndex": 2, "consequences": ["That raises costs.", "Blobs are growing, not going.", "More room keeps costs down."], "explanation": "Fusaka gave data-heavy apps more cheap room. Build to use it."}, "proReasoning": "Founders plan products around new capacity.", "commonMistake": "Ignoring cheaper data options.", "mentalModel": "Use the room."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what a blob is.", "prompt": "What's the best answer?", "options": ["A cheap data space layer 2s post into", "A new kind of coin traded on Ethereum", "A bug that slows down Ethereum"], "correctIndex": 0, "consequences": ["Blobs arrived with Dencun in 2024.", "Blobs hold data, not value.", "They were added on purpose."], "explanation": "Blobs are temporary data space on Ethereum. Layer 2s use them to post records cheaply."}, "proReasoning": "Like a cheap parcel locker next to a costly safe.", "commonMistake": "Thinking a blob is a token.", "mentalModel": "Cheap lockers."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a14b4e10fa15$ml$]::text[]),
($ml$edbbacb8-9fda-5ee9-b4b8-6fbb2460d111$ml$::uuid, $ml$web3$ml$, 22, 3, $ml${"id": "web3-d22-c3", "title": "Promise users cheaper fees after Fusaka?", "lessonTitle": "Ethereum more than doubles its data room", "slot": 3, "type": "decide", "brief": {"headline": "You run marketing for a layer 2. Fusaka raised Ethereum's blob target from 6 to 14 by January 2026, and your team wants to promise users even cheaper fees.", "kicker": "Decide what to promise users after Fusaka.", "fullText": "Blobs give layer 2s cheap space to post data to Ethereum. Fusaka more than doubled that space and added PeerDAS sampling.\n\nYour fees are already a fraction of a cent. Data cost is only one part of what users pay.", "sources": [{"url": "https://blog.ethereum.org/2025/11/06/fusaka-mainnet-announcement", "label": "Ethereum Foundation blog, Fusaka mainnet announcement"}, {"url": "https://www.theblock.co/post/282417/ethereum-layer-2s-show-dramatic-drop-in-transaction-fees-after-dencun", "label": "The Block, layer 2 fees drop after Dencun, Mar 2024"}]}, "evidence": {"kind": "faceOff", "prompt": "Which message is safer to publish?", "left": {"name": "More room keeps data costs low", "note": "Ties the claim to blob capacity"}, "right": {"name": "Fees will fall to zero forever", "note": "A promise no network can keep"}, "correctIndex": 0, "explanation": "Fusaka added room. It did not make fees free."}, "numbers": {"kind": "numberSense", "prompt": "Fusaka's maximum blobs per slot reached about how many?", "min": 0, "max": 30, "value": 21, "explanation": "The maximum rose from 9 to 21.", "unit": "blobs"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CMO wants a headline for the launch.", "prompt": "Which do you pick?", "options": ["\"Fusaka makes our chain fully free to use\"", "\"More room on Ethereum keeps our fees low\"", "\"Fees fall to zero forever after Fusaka\""], "correctIndex": 1, "consequences": ["Fees still exist.", "Accurate and tied to the upgrade.", "A promise you cannot keep."], "explanation": "Make claims the upgrade supports. Overpromising invites backlash."}, "proReasoning": "Marketers check claims with engineers.", "commonMistake": "Promising what you cannot control.", "mentalModel": "Claim what is true."}, "invest": {"call": {"kind": "theCall", "situation": "A layer 2 claims fees will hit zero after Fusaka.", "prompt": "How do you read the claim?", "options": ["As proof the network is undervalued", "As a signal that fees will rise", "As hype, since data is one part of fees"], "correctIndex": 2, "consequences": ["That is a leap.", "It says nothing about rises.", "Other costs remain."], "explanation": "Fusaka eased data costs. Zero fees forever is not a claim it supports."}, "proReasoning": "Investors test bold claims against how costs are built.", "commonMistake": "Taking marketing claims as forecasts.", "mentalModel": "Test the claim."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup could pass Fusaka savings to users.", "prompt": "What is the smartest move?", "options": ["Pass on savings but keep margin for costs", "Cut fees to zero to win new users fast", "Raise fees since demand is strong"], "correctIndex": 0, "consequences": ["Users benefit and you stay viable.", "Zero fees leave no revenue.", "Users can move to cheaper chains."], "explanation": "Share the gain without giving away the revenue you need."}, "proReasoning": "Founders price for both growth and survival.", "commonMistake": "Pricing below what keeps you running.", "mentalModel": "Share, do not give away."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if Ethereum fees will now be free.", "prompt": "What's the best answer?", "options": ["No, fees went up after the upgrade", "Cheaper data, but fees will not vanish", "Yes, every transaction is now free"], "correctIndex": 1, "consequences": ["Fusaka added capacity.", "Data cost is one part of fees.", "Fees still exist."], "explanation": "Fusaka added room for cheap data. Fees stay low, not zero."}, "proReasoning": "Like a bigger parking lot: easier to park, still not free.", "commonMistake": "Assuming more capacity means free.", "mentalModel": "Low, not zero."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9664fb496012$ml$]::text[]),
($ml$7db48b57-d52f-5b3c-8474-3151be395fa9$ml$::uuid, $ml$web3$ml$, 23, 1, $ml${"id": "web3-d23-c1", "title": "An XRP fund breaks a first-day record", "lessonTitle": "The rule that opened crypto ETFs", "slot": 1, "type": "apply", "brief": {"headline": "Canary Capital's XRP ETF, XRPC, traded $59 million on its first day in November 2025, the highest first-day volume of any ETF launch that year, Nasdaq said.", "kicker": "Apply day 23: new crypto ETFs reached the market in a wave.", "fullText": "XRPC listed on Nasdaq and held about $250 million in assets after its first day. It joined other Canary funds tracking HBAR and Litecoin, and a staked Solana fund.\n\nThe press release does not say which listing route each fund used.\n\nThrough the day 23 lens: in September 2025, the SEC approved generic listing standards. Exchanges could list qualifying crypto ETFs without a separate review that could take up to 240 days.", "sources": [{"url": "https://www.nasdaq.com/press-release/canary-capitals-crypto-etf-suite-accelerates-xrpc-sets-record-highest-first-day", "label": "Nasdaq press release, Canary's XRPC sets a first-day record, Nov 2025"}, {"url": "https://crypto.news/sec-nods-generic-listing-standards-crypto-etfs-2025/", "label": "crypto.news, SEC approves generic listing standards for crypto ETFs"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["XRPC traded $59 million on its first day", "XRPC listed on Nasdaq", "The release said XRPC used generic standards"], "fakeIndex": 2, "explanation": "The release did not say which listing route the fund used."}, "numbers": {"kind": "numberSense", "prompt": "XRPC held about how many million dollars after its first day?", "min": 0, "max": 600, "value": 250, "explanation": "About $250 million, according to Nasdaq's release.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at an ETF issuer. They ask what the XRPC launch shows.", "prompt": "Which answer is strongest?", "options": ["Demand exists beyond bitcoin and ether funds", "XRP will outperform every other coin soon", "Generic standards guarantee inflows"], "correctIndex": 0, "consequences": ["A record first day for an XRP fund.", "That is a price call, not analysis.", "Rules allow listing, not demand."], "explanation": "A record first day showed real interest in a newer crypto fund."}, "proReasoning": "Strong answers stick to what the data shows.", "commonMistake": "Turning one launch into a price prediction.", "mentalModel": "Stick to the data."}, "invest": {"call": {"kind": "theCall", "situation": "A friend says XRPC's record means XRP is a sure bet.", "prompt": "How do you answer?", "options": ["Volume proves the price will double", "First-day volume is not a forecast of returns", "A record launch guarantees future gains"], "correctIndex": 1, "consequences": ["That claim has no support.", "Volume measures trading, not future value.", "No launch guarantees gains."], "explanation": "Trading volume shows interest on one day. It says nothing certain about returns."}, "proReasoning": "Investors separate launch buzz from long-run value.", "commonMistake": "Treating launch volume as a buy signal.", "mentalModel": "Buzz is not returns."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup provides services to ETF issuers.", "prompt": "What does the launch wave suggest?", "options": ["Only bitcoin funds will ever list", "ETF issuers no longer need custodians", "More issuers need crypto fund services"], "correctIndex": 2, "consequences": ["XRP, HBAR and Litecoin funds listed.", "Every fund needs a custodian.", "Several new crypto ETFs launched."], "explanation": "A wave of new funds means more demand for custody, data and compliance help."}, "proReasoning": "Founders follow where new products create work.", "commonMistake": "Assuming the market stops at bitcoin.", "mentalModel": "Follow the wave."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what an XRP ETF is.", "prompt": "What's the best answer?", "options": ["A fund on a stock exchange that holds XRP", "A new coin that replaces XRP", "A bank account that pays XRP interest"], "correctIndex": 0, "consequences": ["It trades like a stock.", "It holds XRP rather than replacing it.", "It is a fund, not a bank account."], "explanation": "An ETF holds the asset and trades on an exchange, so buyers do not need a wallet."}, "proReasoning": "Like buying a share of a basket that holds the coin.", "commonMistake": "Confusing a fund with the coin itself.", "mentalModel": "A fund that holds it."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f620a79fcd86$ml$]::text[]),
($ml$71bfc015-1dd2-59f0-a41e-e1001298ee2e$ml$::uuid, $ml$web3$ml$, 23, 2, $ml${"id": "web3-d23-c2", "title": "Staking rewards inside an ETF", "lessonTitle": "The rule that opened crypto ETFs", "slot": 2, "type": "connect", "brief": {"headline": "Bitwise's BSOL, launched in October 2025, stakes the Solana it holds through Helius. About 28.91% of all ETH was staked in January 2026, showing how common staking has become.", "kicker": "Connect day 16 and day 23: staking moves into stock market funds.", "fullText": "Day 16 showed staking at scale: about 35.9 million ETH earning rewards for helping secure Ethereum.\n\nDay 23 showed generic listing standards, approved in September 2025, which let exchanges list qualifying crypto ETFs faster. BSOL went further than holding coins: it stakes them, so the fund can earn network rewards.", "sources": [{"url": "https://blockworks.com/news/bitwise-solana-etf-nyse", "label": "Blockworks, Bitwise slated to launch US Solana ETF"}, {"url": "https://www.kucoin.com/news/flash/ethereum-staking-rate-hits-28-91-lido-holds-24-45-share", "label": "KuCoin News, Ethereum staking rate hits 28.91%, Lido holds 24.45%"}]}, "evidence": {"kind": "multipleChoice", "prompt": "How does BSOL put its Solana to work?", "options": ["It stakes it through Helius", "It lends it to day traders", "It sells it every month"], "correctIndex": 0, "explanation": "BSOL stakes its SOL through Helius."}, "numbers": {"kind": "numberSense", "prompt": "About what percent of all ETH was staked in January 2026?", "min": 0, "max": 100, "value": 29, "explanation": "About 28.91%, about 35.9 million ETH.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks how staking ETFs differ from plain spot ETFs.", "prompt": "Which answer is best?", "options": ["They pay a fixed bank interest rate yearly", "They stake holdings to earn network rewards", "They hold futures instead of coins"], "correctIndex": 1, "consequences": ["Rewards vary with the network.", "BSOL stakes through Helius.", "Spot and staking funds hold coins."], "explanation": "A staking ETF holds coins and stakes them, adding network rewards."}, "proReasoning": "Analysts note who stakes for the fund and how.", "commonMistake": "Treating staking ETFs as identical to spot ETFs.", "mentalModel": "Holds and stakes."}, "invest": {"call": {"kind": "theCall", "situation": "You compare a staking ETF with a plain spot fund.", "prompt": "What risk do you check?", "options": ["Whether the ticker is easy to say", "Whether the fund has a mascot", "The staking provider and its rules"], "correctIndex": 2, "consequences": ["Tickers carry no risk.", "Mascots carry no risk.", "Staking adds a provider to trust."], "explanation": "Staking adds rewards and a new party to rely on."}, "proReasoning": "Investors read who stakes for the fund.", "commonMistake": "Looking only at the reward rate.", "mentalModel": "Check the staker."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup runs staking infrastructure.", "prompt": "Where is a new customer type?", "options": ["ETF issuers that want to stake holdings", "Retail traders who avoid staking at all", "Funds that hold only futures"], "correctIndex": 0, "consequences": ["BSOL chose Helius to stake.", "They are not looking for staking.", "Futures funds cannot stake."], "explanation": "Staking ETFs need reliable providers. That is a new institutional market."}, "proReasoning": "Founders spot when big buyers adopt their service.", "commonMistake": "Ignoring regulated funds as customers.", "mentalModel": "Serve the funds."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how an ETF can earn crypto rewards.", "prompt": "What's the best answer?", "options": ["It charges investors a bonus fee", "It stakes the coins it holds", "It mines new coins in a warehouse"], "correctIndex": 1, "consequences": ["Fees are costs, not rewards.", "BSOL stakes its SOL.", "Staking is not mining."], "explanation": "Staking lets coin holders earn rewards for securing a network. An ETF can do it too."}, "proReasoning": "Like a fund that rents out what it owns.", "commonMistake": "Thinking rewards come from fees.", "mentalModel": "Stakes what it holds."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1ba5a6c1eb76$ml$]::text[]),
($ml$32a1a9dd-895c-5106-b83d-98c562cf6a8d$ml$::uuid, $ml$web3$ml$, 23, 3, $ml${"id": "web3-d23-c3", "title": "Which crypto fund can list fastest?", "lessonTitle": "The rule that opened crypto ETFs", "slot": 3, "type": "decide", "brief": {"headline": "You run product at an ETF issuer. Under the SEC's September 2025 generic listing standards, one way an asset qualifies is having six months of CFTC-regulated futures trading.", "kicker": "Decide which crypto ETF to bring to market first.", "fullText": "Before generic standards, a crypto ETF needed its own review, which could take up to 240 days. Nasdaq, NYSE Arca and Cboe adopted the new standards.\n\nYour team has three ideas. One asset has had regulated futures for over a year, one for two months, and one has none.", "sources": [{"url": "https://crypto.news/sec-nods-generic-listing-standards-crypto-etfs-2025/", "label": "crypto.news, SEC approves generic listing standards for crypto ETFs"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this asset look likely to qualify under generic standards soon?", "buckets": ["Likely to qualify", "Not yet"], "items": [{"text": "Over a year of CFTC-regulated futures", "bucket": 0}, {"text": "Two months of regulated futures", "bucket": 1}, {"text": "No regulated futures at all", "bucket": 1}, {"text": "Six months of regulated futures", "bucket": 0}], "explanation": "Six months of CFTC-regulated futures is one way to qualify."}, "numbers": {"kind": "numberSense", "prompt": "The old review could take up to how many days?", "min": 0, "max": 400, "value": 240, "explanation": "Up to 240 days, before generic standards.", "unit": "days"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO asks which fund to file first.", "prompt": "What do you recommend?", "options": ["The asset with no futures, just to be first", "All three at once, ignoring the rules", "The asset with over a year of regulated futures"], "correctIndex": 2, "consequences": ["It cannot use that route yet.", "Two may not qualify.", "It meets the six-month futures route."], "explanation": "Lead with the product that meets the standard. It can list faster."}, "proReasoning": "Product leaders sequence launches by readiness.", "commonMistake": "Leading with the product least ready to list.", "mentalModel": "Lead with ready."}, "invest": {"call": {"kind": "theCall", "situation": "An issuer announces a fund on an asset with no futures.", "prompt": "What do you expect?", "options": ["A slower path than generic standards", "Listing the next morning", "Automatic approval within one week"], "correctIndex": 0, "consequences": ["It cannot use the futures route.", "It needs another route.", "No such rule exists."], "explanation": "Without futures history, the fund cannot use that generic route."}, "proReasoning": "Analysts check which route a fund can use.", "commonMistake": "Assuming every crypto ETF lists fast now.", "mentalModel": "Check the route."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells data to ETF issuers.", "prompt": "Which product fits?", "options": ["A list of coin logos", "A tracker of futures history by asset", "A forecast of each coin's price"], "correctIndex": 1, "consequences": ["Logos do not help listing.", "Issuers need to know who qualifies.", "Price calls do not settle eligibility."], "explanation": "Issuers need to know which assets meet the standards. Data on that is useful."}, "proReasoning": "Founders build around the rule buyers must meet.", "commonMistake": "Selling predictions instead of facts.", "mentalModel": "Track eligibility."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why some crypto funds launch faster than others.", "prompt": "What's the best answer?", "options": ["The SEC picks its favorites at random each year", "Faster funds paid higher fees", "Some meet a standard, like six months of futures"], "correctIndex": 2, "consequences": ["Rules decide, not chance.", "Fees do not set listing speed.", "That route skips the long review."], "explanation": "Generic standards gave a fast lane to assets that meet set tests."}, "proReasoning": "Like a fast lane for travelers with the right pass.", "commonMistake": "Thinking listing speed is luck.", "mentalModel": "A pass for the fast lane."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:631e7b26979e$ml$]::text[]),
($ml$2c5c4240-322a-520a-8c65-a31135da9ed5$ml$::uuid, $ml$web3$ml$, 24, 1, $ml${"id": "web3-d24-c1", "title": "Circle opens its own blockchain", "lessonTitle": "Stripe builds its own blockchain", "slot": 1, "type": "apply", "brief": {"headline": "On September 16, 2026, Circle opened public mainnet for Arc, its own layer 1 blockchain where fees are paid in USDC, with BlackRock, Visa and Mastercard among the founding validators.", "kicker": "Apply day 24: payment firms are building their own chains.", "fullText": "Arc launched with 11 founding validator institutions, including DTCC and ICE. It works with Ethereum tools and offers sub-second finality. Its test network handled over 700 million transactions after opening in October 2025.\n\nCircle minted 10 billion ARC tokens at genesis but said this was \"not a commitment to launch them publicly.\" Over 100 apps launched, including Aave, Morpho and Uniswap.\n\nThrough the day 24 lens: like Stripe's Tempo, Arc lets users pay fees in a stablecoin.", "sources": [{"url": "https://www.theblock.co/news/ecosystems/2026-09-16-circle-launches-arc-mainnet-with-blackrock-and-visa-among-validators-mints-10-billion-arc-tokens-415250", "label": "The Block, Circle launches Arc mainnet, Sep 2026"}, {"url": "https://crypto.news/stripe-and-paradigms-tempo-mainnet-goes-live-for-machine-payments/", "label": "crypto.news, Stripe and Paradigm's Tempo mainnet goes live"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Arc fees are paid in USDC", "Arc had 11 founding validator institutions", "Circle committed to a public ARC token sale"], "fakeIndex": 2, "explanation": "Circle said minting ARC was not a commitment to launch the tokens publicly."}, "numbers": {"kind": "numberSense", "prompt": "Arc's test network handled over how many million transactions?", "min": 0, "max": 1500, "value": 700, "explanation": "Over 700 million, after opening in October 2025.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a payments company. They ask why Circle built Arc.", "prompt": "Which answer lands best?", "options": ["To replace Visa and Mastercard all at once", "To run payments on a chain built around USDC", "To stop USDC from working on Ethereum"], "correctIndex": 1, "consequences": ["Visa and Mastercard are validators.", "Fees are in USDC on Arc.", "USDC still runs on other chains."], "explanation": "Circle built a chain around its own stablecoin, with big finance firms as validators."}, "proReasoning": "Strong answers name the strategy without hype.", "commonMistake": "Assuming a new chain means leaving the old ones.", "mentalModel": "Built around USDC."}, "invest": {"call": {"kind": "theCall", "situation": "You research Circle after Arc's launch.", "prompt": "Which fact needs care in your note?", "options": ["Arc uses USDC to pay its network fees", "Arc launched with over 100 apps live on it", "ARC was minted but not promised to the public"], "correctIndex": 2, "consequences": ["That is reported plainly.", "That is reported plainly.", "Circle said no public commitment."], "explanation": "Do not treat a minted token as a planned sale. Circle said it was not committed."}, "proReasoning": "Researchers report exactly what a company said.", "commonMistake": "Turning a genesis mint into a token launch rumor.", "mentalModel": "Report exactly."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your fintech startup must choose a chain for payments.", "prompt": "What does Arc add to your options?", "options": ["A chain with USDC fees and big validators", "The only chain where USDC exists today", "A chain that needs no apps"], "correctIndex": 0, "consequences": ["Fees in USDC, validators like Visa.", "USDC exists on many chains.", "Apps make a chain useful."], "explanation": "Arc and Tempo both let users pay fees in stablecoins. Compare cost and partners."}, "proReasoning": "Founders compare payment chains on fees, speed and who backs them.", "commonMistake": "Picking a chain on brand alone.", "mentalModel": "Compare the options."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why BlackRock and Visa run parts of a blockchain.", "prompt": "What's the best answer?", "options": ["They mine bitcoin for Circle on the side", "They are validators that confirm Arc's blocks", "They bought Circle outright"], "correctIndex": 1, "consequences": ["Arc does not mine bitcoin.", "They are founding validators.", "They did not buy Circle."], "explanation": "Validators confirm transactions. Arc chose big finance firms for that role."}, "proReasoning": "Like well-known auditors checking the books.", "commonMistake": "Thinking validators own the chain.", "mentalModel": "Trusted checkers."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3185e2ecf88a$ml$]::text[]),
($ml$cde12546-4cc3-544e-87ed-6254765e8a03$ml$::uuid, $ml$web3$ml$, 24, 2, $ml${"id": "web3-d24-c2", "title": "Stablecoin rules, stablecoin rails", "lessonTitle": "Stripe builds its own blockchain", "slot": 2, "type": "connect", "brief": {"headline": "The GENIUS Act became law in July 2025. In March 2026, Stripe and Paradigm's Tempo launched as its own blockchain where fees are paid in stablecoins and no token was issued.", "kicker": "Connect day 17 and day 24: rules for the coin, a road built for it.", "fullText": "Day 17 showed the GENIUS Act: one-to-one reserves of cash-like assets, no interest to holders, and payment stablecoins treated as neither securities nor commodities.\n\nDay 24 showed Tempo: its own layer 1, compatible with Ethereum tools, paying fees in stablecoins. Klarna planned a stablecoin on it. Clear rules for the coin and a chain built for paying with it go together.", "sources": [{"url": "https://www.everycrsreport.com/files/2026-08-20_IN12553_0b329134f6be0cc12f78017358552f4053d52c5e.html", "label": "Congressional Research Service, overview of the GENIUS Act of 2025"}, {"url": "https://crypto.news/stripe-and-paradigms-tempo-mainnet-goes-live-for-machine-payments/", "label": "crypto.news, Stripe and Paradigm's Tempo mainnet goes live"}]}, "evidence": {"kind": "faceOff", "prompt": "What makes Tempo different from most blockchains?", "left": {"name": "Fees are paid in stablecoins", "note": "No separate gas token to buy"}, "right": {"name": "It has no connection to Ethereum", "note": "It cannot run Ethereum tools"}, "correctIndex": 0, "explanation": "Tempo pays fees in stablecoins and works with Ethereum tools."}, "numbers": {"kind": "numberSense", "prompt": "About how many months passed between the GENIUS Act and Tempo's mainnet?", "min": 0, "max": 36, "value": 8, "explanation": "From July 2025 to March 2026 is about 8 months, by our count.", "unit": "months"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks why payment companies care about the GENIUS Act.", "prompt": "Which answer leads?", "options": ["The law lets them pay holders a set interest", "The law made stablecoins securities", "Clear stablecoin rules make building rails safer"], "correctIndex": 2, "consequences": ["The law bans interest to holders.", "It says they are not securities.", "Rules lower legal uncertainty."], "explanation": "Payment firms build when the rules are clear. The law gave that clarity."}, "proReasoning": "Analysts connect regulation to product launches.", "commonMistake": "Treating law and products as separate stories.", "mentalModel": "Rules invite building."}, "invest": {"call": {"kind": "theCall", "situation": "You compare payment chains like Tempo.", "prompt": "What do you weigh?", "options": ["Fees in stablecoins and the backers behind it", "Whether it has the flashiest token on offer", "Whether it hides its fee model"], "correctIndex": 0, "consequences": ["Tempo issued no token.", "No token was issued.", "Fee models should be clear."], "explanation": "Payment chains compete on cost, speed and trust, not token hype."}, "proReasoning": "Investors judge payment rails on use.", "commonMistake": "Looking for a token where none exists.", "mentalModel": "Judge on use."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup issues a stablecoin for merchant payments.", "prompt": "Why might Tempo appeal?", "options": ["Tempo exempts you from the GENIUS Act rules", "Merchants pay fees in the coin they already hold", "Tempo lets you pay holders interest"], "correctIndex": 1, "consequences": ["The law still applies.", "No gas token to buy.", "The law still bans that."], "explanation": "Paying fees in the same stablecoin removes a step for merchants."}, "proReasoning": "Founders cut steps between users and payment.", "commonMistake": "Thinking a chain changes the law for you.", "mentalModel": "Fewer steps."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Stripe built a blockchain.", "prompt": "What's the best answer?", "options": ["To launch a coin and sell it to its users", "To replace the US dollar entirely", "To move stablecoin payments faster and cheaper"], "correctIndex": 2, "consequences": ["No token was issued.", "Stablecoins track the dollar.", "Tempo issued no token."], "explanation": "Stripe wants a road built for stablecoin payments, with fees in stablecoins."}, "proReasoning": "Like a payments company laying its own track.", "commonMistake": "Assuming every new chain launches a coin.", "mentalModel": "A road for payments."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:13b1b7703220$ml$]::text[]),
($ml$f5200787-0d7d-5e85-895a-528736b25089$ml$::uuid, $ml$web3$ml$, 24, 3, $ml${"id": "web3-d24-c3", "title": "Build on Tempo or an existing layer 2?", "lessonTitle": "Stripe builds its own blockchain", "slot": 3, "type": "decide", "brief": {"headline": "You run a payments startup. Tempo launched in March 2026 as its own layer 1 with stablecoin fees. Ethereum layer 2s already host many stablecoin apps.", "kicker": "Decide where to build your payment product.", "fullText": "Tempo works with Ethereum tools, pays fees in stablecoins and claims \"tens of thousands\" of transactions per second. It added a protocol for machine payments.\n\nLayer 2s settle to Ethereum and already have users and apps. Your choice affects costs, reach and who you depend on.", "sources": [{"url": "https://crypto.news/stripe-and-paradigms-tempo-mainnet-goes-live-for-machine-payments/", "label": "crypto.news, Stripe and Paradigm's Tempo mainnet goes live"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this point toward Tempo or an existing layer 2?", "buckets": ["Tempo", "Existing layer 2"], "items": [{"text": "You want fees paid in stablecoins", "bucket": 0}, {"text": "You need machine payments support", "bucket": 0}, {"text": "You need apps users already use", "bucket": 1}, {"text": "You want Ethereum settlement", "bucket": 1}, {"text": "You want Stripe in your stack", "bucket": 0}], "explanation": "Tempo fits payment-first designs. Layer 2s fit reach and Ethereum settlement."}, "numbers": {"kind": "numberSense", "prompt": "Tempo launched mainnet in which month of 2026?", "min": 0, "max": 12, "value": 3, "explanation": "March 2026, month 3.", "unit": "month"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your board asks where to build.", "prompt": "What do you recommend?", "options": ["Match the chain to your users and fees", "Pick the newest chain every time", "Build your own chain from scratch"], "correctIndex": 0, "consequences": ["Each choice suits different needs.", "New does not mean better.", "That costs time and security."], "explanation": "Tempo suits payment-first designs. Layer 2s offer reach. Choose by need."}, "proReasoning": "Leaders choose platforms by fit.", "commonMistake": "Following hype instead of users.", "mentalModel": "Choose by fit."}, "invest": {"call": {"kind": "theCall", "situation": "A payments startup moves to Tempo.", "prompt": "What do you ask?", "options": ["Will fees be paid in bitcoin?", "Will its users and partners follow?", "Will Tempo launch a token for it?"], "correctIndex": 1, "consequences": ["Fees are in stablecoins.", "Reach matters for payments.", "Tempo issued no token."], "explanation": "A new chain is useful only if users and partners are there."}, "proReasoning": "Investors check where a startup's users are.", "commonMistake": "Valuing the move on its novelty.", "mentalModel": "Follow the users."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup could support both platforms.", "prompt": "Is that wise?", "options": ["No, since chains can never talk to each other", "Only if both launch tokens", "Yes, if your tools work with Ethereum code"], "correctIndex": 2, "consequences": ["Bridges and shared tools exist.", "Tokens are not needed.", "Tempo works with Ethereum tools."], "explanation": "Shared Ethereum tooling lowers the cost of supporting both."}, "proReasoning": "Founders reduce risk by not betting on one rail.", "commonMistake": "Locking into one chain too early.", "mentalModel": "Hedge with shared tools."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why there are so many blockchains for payments.", "prompt": "What's the best answer?", "options": ["Each trades off cost, speed and who backs it", "Only one of them actually works", "They are all the same chain under new names"], "correctIndex": 0, "consequences": ["Tempo, Arc and layer 2s differ.", "Several run today.", "They are separate networks."], "explanation": "Payment chains compete on fees, speed and partners."}, "proReasoning": "Like card networks competing for merchants.", "commonMistake": "Assuming one chain will do everything.", "mentalModel": "Competing rails."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:72acf9eb9902$ml$]::text[]),
($ml$9edd91cd-94f5-50f1-8dff-0ec583412faa$ml$::uuid, $ml$web3$ml$, 25, 1, $ml${"id": "web3-d25-c1", "title": "A letter asking for your 24 words", "lessonTitle": "The words that hold your crypto", "slot": 1, "type": "apply", "brief": {"headline": "In April 2025, Ledger confirmed that scammers were mailing physical letters with its logo, asking hardware wallet owners to scan a QR code and enter their recovery phrase.", "kicker": "Apply day 25: whoever has your seed words has your crypto.", "fullText": "The letters demanded a \"mandatory wallet validation\" and warned that failure could restrict access to funds. Ledger said it will never call, message or ask for a customer's 24-word phrase.\n\nIn a July 2020 breach, data on more than 273,000 Ledger customers was later leaked. Ledger did not confirm how scammers got the addresses.\n\nThrough the day 25 lens: a seed phrase can restore a wallet on any compatible device, so sharing it hands over the funds.", "sources": [{"url": "https://www.theblock.co/news/ecosystems/2025-04-30-ledger-confirms-physical-scam-letters-requesting-seed-phrase-352479", "label": "The Block, Ledger confirms physical scam letters asking for seed phrases, Apr 2025"}, {"url": "https://trezor.io/learn/advanced/what-is-bip39", "label": "Trezor, what is BIP39?"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the scam in order.", "steps": ["Customer data leaks in a 2020 breach", "Scammers mail letters with a wallet logo", "A QR code leads to a fake page", "The victim types in the recovery phrase", "The scammer restores the wallet and moves funds"], "explanation": "The phrase restores the wallet anywhere, so typing it in gives the funds away."}, "numbers": {"kind": "numberSense", "prompt": "Data on more than how many thousand Ledger customers leaked after the 2020 breach?", "min": 0, "max": 600, "value": 273, "explanation": "More than 273,000 customers.", "unit": "K"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview for a crypto security role. They ask what the letters show.", "prompt": "Which answer is strongest?", "options": ["Hardware wallets can be hacked by mail", "Paper letters are always genuine", "Attackers target seed words, not the device"], "correctIndex": 2, "consequences": ["The device was not hacked.", "These letters were fake.", "The phrase restores funds anywhere."], "explanation": "The device stayed secure. The scam tried to get the phrase, which controls the funds."}, "proReasoning": "Strong candidates point to the weakest link: people.", "commonMistake": "Thinking hardware alone protects funds.", "mentalModel": "Words, not devices."}, "invest": {"call": {"kind": "theCall", "situation": "A client with a hardware wallet gets one of these letters.", "prompt": "What do you tell them?", "options": ["Never enter the phrase; Ledger will not ask", "Scan the code quickly to avoid lockout", "Send the phrase to support by email"], "correctIndex": 0, "consequences": ["Ledger said it never asks.", "That is the scam.", "No genuine support asks."], "explanation": "No real company asks for your recovery phrase. The letter is the attack."}, "proReasoning": "Advisers train clients on social engineering.", "commonMistake": "Trusting a letter because it looks official.", "mentalModel": "Never share it."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes a wallet app.", "prompt": "Which feature helps most against this scam?", "options": ["A QR code that asks for the phrase", "A warning never to share the phrase", "A box to email your phrase to us"], "correctIndex": 1, "consequences": ["That copies the scam.", "Users learn the rule early.", "That copies the scam."], "explanation": "Teach users that no one legitimate asks for the phrase."}, "proReasoning": "Founders design against known scams.", "commonMistake": "Building flows that look like scams.", "mentalModel": "Teach the rule."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend got a letter asking for their wallet words.", "prompt": "What's the best answer?", "options": ["Reply fast before the deadline", "Share only half the words with them to be safe", "Ignore it; anyone with the words takes the funds"], "correctIndex": 2, "consequences": ["The deadline is pressure.", "Partial words still help attackers.", "The words restore the wallet anywhere."], "explanation": "Your words are the wallet. No company will ask for them."}, "proReasoning": "Like a stranger asking for your house key by mail.", "commonMistake": "Acting fast because a letter sounds urgent.", "mentalModel": "Ignore and keep."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:57f85e34a933$ml$]::text[]),
($ml$96f690ce-d8fe-521f-865c-614ad1cdb6f1$ml$::uuid, $ml$web3$ml$, 25, 2, $ml${"id": "web3-d25-c2", "title": "The key behind the words", "lessonTitle": "The words that hold your crypto", "slot": 2, "type": "connect", "brief": {"headline": "A private key signs every transaction. A BIP39 seed phrase of 12 to 24 words encodes the secret that generates those keys, so it can restore a wallet on any compatible device.", "kicker": "Connect day 5 and day 25: the words are the key in human form.", "fullText": "Day 5 showed that a private key controls funds. If it is stolen, the network accepts the thief's signatures, as Bybit's $1.5 billion loss showed.\n\nDay 25 showed BIP39, from 2013. Each word comes from a list of 2,048 and carries 11 bits, with a checksum to catch typos. Twelve to 24 words encode 128 to 256 bits, enough to recreate every key.", "sources": [{"url": "https://bitpay.com/blog/what-are-public-and-private-keys/", "label": "BitPay, public and private keys"}, {"url": "https://trezor.io/learn/advanced/what-is-bip39", "label": "Trezor, what is BIP39?"}]}, "evidence": {"kind": "multipleChoice", "prompt": "How many words are in the BIP39 word list?", "options": ["24", "2,048", "256"], "correctIndex": 1, "explanation": "Each word comes from a list of 2,048, so each carries 11 bits."}, "numbers": {"kind": "numberSense", "prompt": "Each BIP39 word carries how many bits?", "min": 0, "max": 40, "value": 11, "explanation": "Eleven bits, since the list has 2,048 words.", "unit": "bits"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks why seed phrases need such care.", "prompt": "Which answer leads?", "options": ["They recreate every key in the wallet", "They only open the device lock screen", "They expire after one year of use"], "correctIndex": 0, "consequences": ["That is how restore works.", "A PIN does that.", "They do not expire."], "explanation": "The words are the master secret. Whoever has them controls the keys."}, "proReasoning": "Security teams treat the phrase as the key itself.", "commonMistake": "Treating the phrase like a password reset.", "mentalModel": "Words equal keys."}, "invest": {"call": {"kind": "theCall", "situation": "You assess how a firm backs up its wallet.", "prompt": "What do you check?", "options": ["Whether the wallet came in a nice gift box", "Where the seed words are kept and who sees them", "The color of the hardware wallet case"], "correctIndex": 1, "consequences": ["That would be a major risk.", "Storage decides theft risk.", "Color is not risk."], "explanation": "The phrase can restore the wallet anywhere. Its storage is the real security."}, "proReasoning": "Auditors follow the secret, not the device.", "commonMistake": "Checking the device but not the words.", "mentalModel": "Follow the secret."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup designs wallet recovery.", "prompt": "Which design is sound?", "options": ["A custom phrase only your app can read", "No backup, to keep it simple", "Standard BIP39 so users can restore anywhere"], "correctIndex": 2, "consequences": ["Users would be locked in.", "Lost devices mean lost funds.", "Any compatible wallet can restore it."], "explanation": "BIP39 is a standard. Users can recover even if your app disappears."}, "proReasoning": "Founders follow standards that protect users.", "commonMistake": "Locking users into a private format.", "mentalModel": "Use the standard."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how 12 words can hold a whole wallet.", "prompt": "What's the best answer?", "options": ["They encode the secret that makes every key", "Each word stores one coin", "The words are a list of separate passwords"], "correctIndex": 0, "consequences": ["Twelve words carry 128 bits.", "Words do not store coins.", "They form one secret."], "explanation": "Words are a readable way to write down a very large secret number."}, "proReasoning": "Like a combination written as words.", "commonMistake": "Thinking the words hold the coins.", "mentalModel": "A secret in words."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6d4ee962bef5$ml$]::text[]),
($ml$d82725a6-1f4c-59e1-9e84-9a0f2cdcd333$ml$::uuid, $ml$web3$ml$, 25, 3, $ml${"id": "web3-d25-c3", "title": "How should a small firm store its seed phrase?", "lessonTitle": "The words that hold your crypto", "slot": 3, "type": "decide", "brief": {"headline": "You manage crypto for a small company. Its wallet uses a 24-word BIP39 phrase, and any compatible wallet can restore the funds from those words.", "kicker": "Decide how to store the recovery phrase.", "fullText": "BIP39 phrases run 12 to 24 words, encoding 128 to 256 bits, with a checksum. Whoever holds the words can move the funds from any compatible wallet.\n\nThe company needs to recover if a device is lost, without letting one person or one leak take everything.", "sources": [{"url": "https://trezor.io/learn/advanced/what-is-bip39", "label": "Trezor, what is BIP39?"}, {"url": "https://www.theblock.co/news/ecosystems/2025-04-30-ledger-confirms-physical-scam-letters-requesting-seed-phrase-352479", "label": "The Block, Ledger confirms physical scam letters asking for seed phrases, Apr 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this make the phrase safer or riskier?", "buckets": ["Safer", "Riskier"], "items": [{"text": "Writing it offline and storing it securely", "bucket": 0}, {"text": "Keeping it in a cloud notes app", "bucket": 1}, {"text": "Sharing it with support when asked", "bucket": 1}, {"text": "Limiting who knows where it is", "bucket": 0}, {"text": "Photographing it on a phone", "bucket": 1}], "explanation": "Keep the words offline, limited and never shared."}, "numbers": {"kind": "numberSense", "prompt": "A 24-word phrase encodes up to how many bits?", "min": 0, "max": 400, "value": 256, "explanation": "Up to 256 bits; 12 words encode 128.", "unit": "bits"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CFO asks for a storage plan.", "prompt": "What do you propose?", "options": ["A photo saved in the company drive", "Offline copies with limited, logged access", "A shared document the whole team can edit"], "correctIndex": 1, "consequences": ["Cloud files can leak.", "Offline and controlled.", "Anyone with access could steal."], "explanation": "The words are the funds. Store them offline and limit who can reach them."}, "proReasoning": "Treasury leads treat the phrase like vault keys.", "commonMistake": "Storing the phrase where many people can see it.", "mentalModel": "Offline and limited."}, "invest": {"call": {"kind": "theCall", "situation": "You review a firm that keeps its phrase in email.", "prompt": "What do you flag?", "options": ["Email is the safest place for it", "Nothing, since emails are always private", "Anyone who gets into email gets the funds"], "correctIndex": 2, "consequences": ["Email can be breached.", "Accounts get hacked.", "The words restore anywhere."], "explanation": "If email is breached, the attacker can restore the wallet."}, "proReasoning": "Auditors check where secrets live.", "commonMistake": "Trusting online accounts with the master secret.", "mentalModel": "Check where it lives."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds tools for company wallets.", "prompt": "Which feature fits?", "options": ["Offline backup guidance with access logs", "Auto-upload of phrases to the cloud", "A feature that emails phrases daily"], "correctIndex": 0, "consequences": ["Helps firms store safely.", "Increases leak risk.", "Creates copies to steal."], "explanation": "Firms need safe storage habits, not more copies."}, "proReasoning": "Founders reduce copies of secrets.", "commonMistake": "Adding convenience that leaks secrets.", "mentalModel": "Fewer copies."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks where to keep their seed words.", "prompt": "What's the best answer?", "options": ["In an email they send to themselves", "Offline and private, never typed online", "In a note on their phone"], "correctIndex": 1, "consequences": ["Email can be breached.", "Anyone with the words takes the funds.", "Phones get lost or hacked."], "explanation": "Keep the words offline. Anyone who sees them can take the funds."}, "proReasoning": "Treat it like the key to a safe.", "commonMistake": "Saving the words where hackers can reach them.", "mentalModel": "Offline only."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a07bccca4076$ml$]::text[]),
($ml$3bcafbee-a8a0-5d36-8a81-24f10796d85f$ml$::uuid, $ml$web3$ml$, 26, 1, $ml${"id": "web3-d26-c1", "title": "A crypto custodian lists on the NYSE", "lessonTitle": "The wallet maker eyeing Wall Street", "slot": 1, "type": "apply", "brief": {"headline": "In January 2026, BitGo priced its US IPO at $18 a share, above its $15 to $17 range, raising about $212.8 million and valuing the company at over $2 billion.", "kicker": "Apply day 26: crypto security firms are turning to public markets.", "fullText": "BitGo, founded in 2013, began trading on the New York Stock Exchange as BTGO on January 22, 2026. It provides custody, wallets, staking and settlement, and received approval for a US banking charter in December 2025.\n\nGoldman Sachs and Citigroup led the offering.\n\nThrough the day 26 lens: Ledger, which makes hardware wallets, was reported to be exploring a New York IPO at over $4 billion. Firms that hold or protect crypto keys are seeking public investors.", "sources": [{"url": "https://www.theblock.co/news/business/2026-01-21-bitgo-prices-us-ipo-386629", "label": "The Block, BitGo prices its US IPO above range, Jan 2026"}, {"url": "https://www.theblock.co/news/business/2026-01-23-ledger-mulls-new-york-ipo-386810", "label": "The Block, Ledger mulls New York IPO at over $4 billion valuation"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["BitGo priced above its expected range", "BitGo trades on the NYSE as BTGO", "BitGo makes consumer hardware wallets like Ledger"], "fakeIndex": 2, "explanation": "BitGo provides custody, wallets, staking and settlement for institutions. Ledger makes hardware wallets."}, "numbers": {"kind": "numberSense", "prompt": "BitGo raised about how many million dollars in its IPO?", "min": 0, "max": 500, "value": 213, "explanation": "About $212.8 million, at $18 a share.", "unit": "M"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a crypto custodian. They ask what BitGo's IPO signals.", "prompt": "Which answer is strongest?", "options": ["Public investors were willing to fund crypto custody", "Custody firms no longer need any regulators", "Every crypto firm will list on an exchange this year"], "correctIndex": 0, "consequences": ["It priced above its range.", "BitGo sought a banking charter.", "One IPO does not predict all."], "explanation": "Pricing above range showed demand for a regulated custody business."}, "proReasoning": "Strong answers read the signal without overreaching.", "commonMistake": "Turning one IPO into a trend for every firm.", "mentalModel": "Read the signal."}, "invest": {"call": {"kind": "theCall", "situation": "You read BitGo's IPO coverage for a research note.", "prompt": "Which point belongs in the note?", "options": ["It holds more bitcoin than any single ETF", "It priced above range and sought a bank charter", "Its shares are certain to rise from here"], "correctIndex": 1, "consequences": ["That was not reported.", "Both are reported facts.", "No one can promise that."], "explanation": "Stick to reported facts. Price direction is not a fact."}, "proReasoning": "Researchers separate facts from forecasts.", "commonMistake": "Writing a forecast as if it were news.", "mentalModel": "Facts, not forecasts."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells security tools to custodians.", "prompt": "What does the IPO change for you?", "options": ["Custodians will stop buying security tools", "Custody firms will ignore compliance now", "Listed custodians face more audits and checks"], "correctIndex": 2, "consequences": ["They need more, not less.", "Public status raises the bar.", "Public firms need strong controls."], "explanation": "Public companies face disclosure and audit duties. They need tools that prove controls."}, "proReasoning": "Founders sell to customers whose obligations just grew.", "commonMistake": "Missing that a listing raises a buyer's needs.", "mentalModel": "Bigger duties, bigger needs."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what BitGo does.", "prompt": "What's the best answer?", "options": ["It holds crypto safely for big clients", "It mines bitcoin in large warehouses", "It runs a popular crypto meme coin"], "correctIndex": 0, "consequences": ["Custody is its core service.", "It is not a miner.", "It is a custody business."], "explanation": "BitGo stores and moves crypto for institutions, like a vault service."}, "proReasoning": "Like a bank vault for digital assets.", "commonMistake": "Confusing custodians with miners or coins.", "mentalModel": "A vault for big clients."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:de8f2729ad09$ml$]::text[]),
($ml$5ccdb685-954d-58fe-b905-6b6bab31d37b$ml$::uuid, $ml$web3$ml$, 26, 2, $ml${"id": "web3-d26-c2", "title": "From 24 words to a $4 billion company", "lessonTitle": "The wallet maker eyeing Wall Street", "slot": 2, "type": "connect", "brief": {"headline": "Ledger, founded in 2014, makes hardware wallets that keep seed words offline. In January 2026, it was reported to be exploring a New York IPO at a valuation above $4 billion.", "kicker": "Connect day 25 and day 26: protecting seed words became a business.", "fullText": "Day 25 showed that a 12 to 24 word BIP39 phrase can restore every key in a wallet. Hardware wallets keep those secrets off internet-connected devices.\n\nDay 26 showed Ledger's reported IPO plans, at more than double its 2023 valuation of $1.5 billion. Its 2025 revenue was in the \"triple-digit million-euro range,\" and its reported advisers were Goldman Sachs, Barclays and Jefferies.", "sources": [{"url": "https://trezor.io/learn/advanced/what-is-bip39", "label": "Trezor, what is BIP39?"}, {"url": "https://www.theblock.co/news/business/2026-01-23-ledger-mulls-new-york-ipo-386810", "label": "The Block, Ledger mulls New York IPO at over $4 billion valuation"}]}, "evidence": {"kind": "faceOff", "prompt": "What does a hardware wallet mainly protect?", "left": {"name": "The secret behind the seed words", "note": "Kept offline, away from hackers"}, "right": {"name": "The price of the coins inside", "note": "Shields holders from market drops"}, "correctIndex": 0, "explanation": "A hardware wallet protects keys. It does nothing about prices."}, "numbers": {"kind": "numberSense", "prompt": "Ledger's reported IPO valuation was above how many billion dollars?", "min": 0, "max": 10, "value": 4, "explanation": "Above $4 billion, more than double its 2023 valuation.", "unit": "B"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks what Ledger's business rests on.", "prompt": "Which answer is best?", "options": ["Interest on customer deposits", "People paying to keep their keys offline", "Fees on every crypto trade worldwide"], "correctIndex": 1, "consequences": ["It does not hold deposits.", "That is the hardware wallet model.", "Ledger is not an exchange."], "explanation": "Ledger sells devices that keep seed secrets offline. Demand follows self-custody."}, "proReasoning": "Analysts tie revenue to the problem a product solves.", "commonMistake": "Confusing wallet makers with exchanges.", "mentalModel": "Selling safe keys."}, "invest": {"call": {"kind": "theCall", "situation": "You read reports on Ledger's possible IPO.", "prompt": "What would you want to see in a filing?", "options": ["Whether its logo will change after listing", "Whether it will make a meme coin", "How revenue moves with crypto activity"], "correctIndex": 2, "consequences": ["Branding is not the key risk.", "That is not the business.", "Device sales may swing with markets."], "explanation": "Its revenue was in the \"triple-digit million-euro range.\" Filings would show how steady that is."}, "proReasoning": "Investors look at how cyclical revenue is.", "commonMistake": "Judging a company on headlines, not revenue.", "mentalModel": "Read the revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds a self-custody product.", "prompt": "What lesson does Ledger offer?", "options": ["People will pay to protect their seed words", "Users prefer to store words in the cloud", "Self-custody has no paying customers"], "correctIndex": 0, "consequences": ["Ledger built a large business on it.", "Security buyers avoid that.", "Ledger shows otherwise."], "explanation": "Protecting keys is a problem people pay to solve."}, "proReasoning": "Founders pick problems with proven willingness to pay.", "commonMistake": "Assuming crypto users will not pay for security.", "mentalModel": "Security sells."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a wallet company could be worth billions.", "prompt": "What's the best answer?", "options": ["It prints new coins for its owners each year", "Many people pay to keep their crypto keys safe", "It owns the coins its users keep"], "correctIndex": 1, "consequences": ["It does not create coins.", "Devices protect the seed secret.", "Users keep their own coins."], "explanation": "Ledger sells devices, not coins. Its value comes from people paying for security."}, "proReasoning": "Like a company that makes safes, not the gold inside.", "commonMistake": "Thinking the company owns its users' crypto.", "mentalModel": "Safes, not gold."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:258b620b5a86$ml$]::text[]),
($ml$61e55fb7-db93-5ac0-ad00-742f9628c594$ml$::uuid, $ml$web3$ml$, 26, 3, $ml${"id": "web3-d26-c3", "title": "Go public now or stay private?", "lessonTitle": "The wallet maker eyeing Wall Street", "slot": 3, "type": "decide", "brief": {"headline": "You are CFO of a crypto wallet maker. Ledger was reported to be exploring an IPO above $4 billion, and your board asks whether you should list too.", "kicker": "Decide how to prepare for a possible IPO.", "fullText": "Ledger, founded in 2014, reported 2025 revenue in the \"triple-digit million-euro range\" and was valued at $1.5 billion in 2023. Its reported advisers were Goldman Sachs, Barclays and Jefferies.\n\nListing brings capital and public reporting duties. Device sales can swing with crypto activity.", "sources": [{"url": "https://www.theblock.co/news/business/2026-01-23-ledger-mulls-new-york-ipo-386810", "label": "The Block, Ledger mulls New York IPO at over $4 billion valuation"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this point toward listing soon or waiting?", "buckets": ["List soon", "Wait"], "items": [{"text": "Revenue is steady across market cycles", "bucket": 0}, {"text": "Audited accounts are ready", "bucket": 0}, {"text": "Sales swing hard with crypto prices", "bucket": 1}, {"text": "Controls are not yet audit-ready", "bucket": 1}, {"text": "You need capital to expand", "bucket": 0}], "explanation": "Steady revenue and ready controls support listing. Volatile sales and weak controls argue for waiting."}, "numbers": {"kind": "numberSense", "prompt": "How many banks were reported as Ledger's IPO advisers?", "min": 0, "max": 10, "value": 3, "explanation": "Three: Goldman Sachs, Barclays and Jefferies.", "unit": "banks"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your board asks for a recommendation.", "prompt": "What do you propose?", "options": ["List next month because Ledger might", "Never list, since crypto is volatile", "Get audit-ready first, then choose timing"], "correctIndex": 2, "consequences": ["Copying a rival is not a plan.", "That rules out real capital.", "Readiness gives you options."], "explanation": "Be ready to list when it suits you, not when a rival does."}, "proReasoning": "CFOs build readiness before picking a window.", "commonMistake": "Letting a competitor set your timing.", "mentalModel": "Ready first."}, "invest": {"call": {"kind": "theCall", "situation": "A wallet maker you follow files to go public.", "prompt": "What do you check first?", "options": ["How revenue holds up in weak markets", "Whether the CEO posts often online", "Whether its devices come in new colors"], "correctIndex": 0, "consequences": ["Device sales can be cyclical.", "Posts are not results.", "Colors are not risk."], "explanation": "Wallet sales may rise and fall with crypto activity. Check the down years."}, "proReasoning": "Investors test revenue in bad markets.", "commonMistake": "Judging a filing by a strong year alone.", "mentalModel": "Test the down years."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells to wallet makers.", "prompt": "What do they need before an IPO?", "options": ["Fewer security checks on devices", "Audit-ready supply chains and controls", "More meme coin partnerships"], "correctIndex": 1, "consequences": ["Security is the product.", "Public firms face audits.", "That does not prepare a filing."], "explanation": "Pre-IPO firms need controls that pass audits."}, "proReasoning": "Founders sell to a customer's next milestone.", "commonMistake": "Pitching features that add risk.", "mentalModel": "Sell readiness."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a company would want to go public.", "prompt": "What's the best answer?", "options": ["To stop sharing financial results", "To avoid all government rules", "To raise money from many investors"], "correctIndex": 2, "consequences": ["Public firms must report results.", "Public firms face more rules.", "Public markets offer capital."], "explanation": "An IPO raises money but adds reporting and rules."}, "proReasoning": "Like opening a shop to more partners who all see the books.", "commonMistake": "Thinking a listing means fewer rules.", "mentalModel": "Money plus reporting."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ff989431aaea$ml$]::text[]),
($ml$da66c785-7649-53fe-80ea-b9095ff37d2c$ml$::uuid, $ml$web3$ml$, 27, 1, $ml${"id": "web3-d27-c1", "title": "BlackRock adds a second custodian", "lessonTitle": "One custodian for most bitcoin ETFs", "slot": 1, "type": "apply", "brief": {"headline": "In April 2025, BlackRock added Anchorage Digital Bank as an additional custodian for its bitcoin and ether ETFs, IBIT and ETHA. Coinbase had been the only one.", "kicker": "Apply day 27: a backup custodian reduces reliance on one firm.", "fullText": "BlackRock said it had no current plans to move any bitcoin or ether, and cited its \"ongoing risk management approach.\" At the time, IBIT held about $45.1 billion and ETHA about $1.8 billion.\n\nAdding a custodian gives an issuer an option if one provider has problems.\n\nThrough the day 27 lens: Coinbase's CEO later said Coinbase holds more than 80% of US bitcoin ETF custody. One firm still holds most of it.", "sources": [{"url": "https://www.etf.com/sections/news/blackrock-adds-new-digital-asset-custodian", "label": "ETF.com, BlackRock adds a new digital asset custodian, Apr 2025"}, {"url": "https://bitcoinmagazine.com/news/coinbase-ceo-addresses-paper-bitcoin", "label": "Bitcoin Magazine, Coinbase CEO addresses paper bitcoin concerns"}]}, "evidence": {"kind": "buildChain", "prompt": "Trace why an issuer adds a custodian.", "steps": ["One custodian holds all the fund's coins", "That firm becomes a single point of failure", "The issuer adds a second custodian", "Coins can move if the first has trouble", "Reliance on one firm falls"], "explanation": "A second custodian gives the fund somewhere to go."}, "numbers": {"kind": "numberSense", "prompt": "IBIT held about how many billion dollars at the time?", "min": 0, "max": 100, "value": 45, "explanation": "About $45.1 billion, ETF.com reported.", "unit": "B"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at an ETF issuer. They ask why BlackRock added Anchorage.", "prompt": "Which answer is strongest?", "options": ["To move all its coins out at once", "To have a backup and cut reliance on one firm", "Because Coinbase lost the fund's bitcoin"], "correctIndex": 1, "consequences": ["It had no current plans to move coins.", "BlackRock cited risk management.", "Nothing like that was reported."], "explanation": "An additional custodian is insurance against one provider failing."}, "proReasoning": "Strong answers stay within what the issuer said.", "commonMistake": "Inventing a crisis to explain a routine step.", "mentalModel": "A backup, not a crisis."}, "invest": {"call": {"kind": "theCall", "situation": "You review custody risks for spot crypto ETFs.", "prompt": "What does the Anchorage move show?", "options": ["All ETF coins left Coinbase in 2025", "Custody no longer matters for ETFs", "Issuers can add custodians to spread risk"], "correctIndex": 2, "consequences": ["It had no plans to move coins.", "Custody is central to these funds.", "BlackRock added one."], "explanation": "Spreading custody lowers the risk from a single provider."}, "proReasoning": "Analysts track custody arrangements across funds.", "commonMistake": "Assuming custody is a solved issue.", "mentalModel": "Spread the risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers crypto custody.", "prompt": "What opening does this show?", "options": ["Large issuers want second custodians", "Issuers will drop custody entirely", "Only one custodian will ever exist"], "correctIndex": 0, "consequences": ["BlackRock added Anchorage.", "Spot funds must hold coins.", "There are now at least two."], "explanation": "Big issuers may add backups. A credible custodian can win that role."}, "proReasoning": "Founders aim for the backup slot first.", "commonMistake": "Trying to replace the leader before earning trust.", "mentalModel": "Win the backup slot."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a fund would use two vaults.", "prompt": "What's the best answer?", "options": ["To pay twice the fees for fun", "So one failure does not trap all the coins", "Because one vault was robbed last year"], "correctIndex": 1, "consequences": ["It is about risk.", "That is the risk logic.", "No robbery was reported."], "explanation": "Two custodians mean the fund is not stuck if one has trouble."}, "proReasoning": "Like keeping a spare key with a second neighbor.", "commonMistake": "Assuming a backup means something went wrong.", "mentalModel": "A spare key."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:75057e1a64b8$ml$]::text[]),
($ml$940a41a7-537c-58ec-940e-aaaa1d00aca0$ml$::uuid, $ml$web3$ml$, 27, 2, $ml${"id": "web3-d27-c2", "title": "Funds grow, custody concentrates", "lessonTitle": "One custodian for most bitcoin ETFs", "slot": 2, "type": "connect", "brief": {"headline": "US spot bitcoin ETFs held about 1.25 million bitcoin in July 2025, and IBIT held over 700,000. In February 2026, Coinbase's CEO said it holds over 80% of US bitcoin ETF custody.", "kicker": "Connect day 8 and day 27: big funds, one main vault.", "fullText": "Day 8 showed how fast spot bitcoin ETFs grew, with IBIT becoming BlackRock's third-highest revenue ETF out of 1,197.\n\nDay 27 showed where those coins sit. Brian Armstrong said Coinbase holds more than 80% of US bitcoin ETF custody and dismissed \"paper bitcoin\" worries. Issuers can verify holdings on-chain, but client addresses are not published.", "sources": [{"url": "https://www.theblock.co/amp/post/361525/blackrocks-spot-bitcoin-etf-ibit-surpasses-700000-btc-assets-under-management", "label": "The Block, BlackRock's IBIT surpasses 700,000 BTC"}, {"url": "https://bitcoinmagazine.com/news/coinbase-ceo-addresses-paper-bitcoin", "label": "Bitcoin Magazine, Coinbase CEO addresses paper bitcoin concerns"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What can ETF issuers do to check their custodied bitcoin?", "options": ["Ask the SEC to count it", "Check the coin price daily", "Verify holdings on-chain"], "correctIndex": 2, "explanation": "Issuers can verify holdings on-chain, though client addresses are not published."}, "numbers": {"kind": "numberSense", "prompt": "Coinbase said it holds over what percent of US bitcoin ETF custody?", "min": 0, "max": 100, "value": 80, "explanation": "Over 80%, Brian Armstrong said in February 2026.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks for the biggest structural risk in bitcoin ETFs.", "prompt": "Which answer leads?", "options": ["ETFs hold no real bitcoin at all", "Fund fees are always zero", "Most coins sit with one custodian"], "correctIndex": 2, "consequences": ["Spot funds hold real coins.", "Funds charge fees.", "Coinbase holds over 80%."], "explanation": "Concentration means one firm's problem could touch most funds."}, "proReasoning": "Analysts name concentration risks plainly.", "commonMistake": "Missing a single point of failure.", "mentalModel": "Name the concentration."}, "invest": {"call": {"kind": "theCall", "situation": "You compare bitcoin ETFs.", "prompt": "What do you look up?", "options": ["Who custodies each fund's coins", "Which fund has the shortest name", "Which ticker sounds best"], "correctIndex": 0, "consequences": ["Custody is a key risk.", "Names do not change risk.", "Tickers do not change risk."], "explanation": "Most funds share one custodian. Check whether yours has a backup."}, "proReasoning": "Investors read the custody section.", "commonMistake": "Assuming all funds carry different risks.", "mentalModel": "Read custody."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds proof-of-reserves tools.", "prompt": "What need does this point to?", "options": ["Tools that move coins without records", "Clear, verifiable reporting of ETF holdings", "Hiding which custodian holds coins"], "correctIndex": 1, "consequences": ["That removes trust.", "Client addresses are not published.", "That adds doubt."], "explanation": "Issuers can verify on-chain. Tools that make this clearer meet a real need."}, "proReasoning": "Founders build where trust gaps remain.", "commonMistake": "Ignoring the verification question.", "mentalModel": "Close the gap."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if bitcoin ETFs really hold bitcoin.", "prompt": "What's the best answer?", "options": ["No, they only hold IOUs from other firms", "Only on weekends, when markets close", "Yes, mostly held by Coinbase as custodian"], "correctIndex": 2, "consequences": ["Armstrong dismissed that worry.", "Holdings do not change by day.", "Issuers can verify on-chain."], "explanation": "Spot funds hold real coins, mostly with one custodian."}, "proReasoning": "Like gold funds that keep bars in a vault.", "commonMistake": "Believing rumors over what can be checked.", "mentalModel": "Real coins, one vault."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d36a91684597$ml$]::text[]),
($ml$cc8915ed-3db3-5b9c-8f6c-fb3d3f5183ef$ml$::uuid, $ml$web3$ml$, 27, 3, $ml${"id": "web3-d27-c3", "title": "One custodian or two?", "lessonTitle": "One custodian for most bitcoin ETFs", "slot": 3, "type": "decide", "brief": {"headline": "You are launching a spot bitcoin ETF. Coinbase holds more than 80% of US bitcoin ETF custody, according to its CEO, and issuers can verify holdings on-chain.", "kicker": "Decide how to set up custody for your fund.", "fullText": "Using the leading custodian is familiar to investors and regulators. But most bitcoin ETFs then share the same single point of failure.\n\nClient addresses are not published, so investors rely on the issuer and custodian for assurance.", "sources": [{"url": "https://bitcoinmagazine.com/news/coinbase-ceo-addresses-paper-bitcoin", "label": "Bitcoin Magazine, Coinbase CEO addresses paper bitcoin concerns"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this point toward one custodian or two?", "buckets": ["One custodian", "Two custodians"], "items": [{"text": "You want the simplest setup at launch", "bucket": 0}, {"text": "Your fund grows very large", "bucket": 1}, {"text": "Investors ask about single points of failure", "bucket": 1}, {"text": "Fees for a second custodian are high", "bucket": 0}, {"text": "Your board wants a backup plan", "bucket": 1}], "explanation": "Small funds may start simple. Large ones and cautious boards favor a backup."}, "numbers": {"kind": "numberSense", "prompt": "Coinbase holds over what percent of US bitcoin ETF custody?", "min": 0, "max": 100, "value": 80, "explanation": "Over 80%, per its CEO in February 2026.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your board asks for a custody plan.", "prompt": "What do you propose?", "options": ["Start with one, line up a backup custodian", "Hold the bitcoin on staff laptops", "Pick the cheapest firm with no checks"], "correctIndex": 0, "consequences": ["Simple now, safer later.", "That is not custody.", "Cheap custody can be costly."], "explanation": "A primary custodian plus a backup limits single-provider risk."}, "proReasoning": "Leaders plan for provider failure.", "commonMistake": "Treating custody as a cost to minimize.", "mentalModel": "Primary plus backup."}, "invest": {"call": {"kind": "theCall", "situation": "A new bitcoin ETF uses only one custodian.", "prompt": "What do you ask?", "options": ["Why does it hold real bitcoin?", "Is there a plan if that custodian fails?", "Why is the ticker four letters long?"], "correctIndex": 1, "consequences": ["Spot funds must hold bitcoin.", "Concentration is the key risk.", "Tickers do not matter."], "explanation": "One custodian is common. The question is what happens if it has trouble."}, "proReasoning": "Investors ask about contingency plans.", "commonMistake": "Ignoring custody because everyone uses it.", "mentalModel": "Ask about the backup."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup is a smaller custodian.", "prompt": "How do you pitch ETF issuers?", "options": ["As cheaper because you skip audits", "As a firm that will hide holdings", "As a backup that cuts concentration risk"], "correctIndex": 2, "consequences": ["No issuer wants that.", "That destroys trust.", "Issuers want backups."], "explanation": "Most coins sit with one firm. A trusted backup solves a real issuer worry."}, "proReasoning": "Founders position against the leader's weak point.", "commonMistake": "Competing on price by cutting safety.", "mentalModel": "Be the backup."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why it matters who holds ETF bitcoin.", "prompt": "What's the best answer?", "options": ["If that firm fails, many funds feel it", "It does not matter at all", "Custodians set the bitcoin price"], "correctIndex": 0, "consequences": ["Over 80% sits with one firm.", "Custody is central to the fund.", "Markets set prices."], "explanation": "When one firm holds most coins, its problems become everyone's."}, "proReasoning": "Like many shops keeping cash in one vault.", "commonMistake": "Assuming the holder is irrelevant.", "mentalModel": "One vault, many shops."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a16946ef9b4d$ml$]::text[]),
($ml$5cd0c352-325b-58c2-ab27-3f202212ca98$ml$::uuid, $ml$web3$ml$, 28, 1, $ml${"id": "web3-d28-c1", "title": "When thieves come to the door", "lessonTitle": "The everyday wallet thefts", "slot": 1, "type": "apply", "brief": {"headline": "CertiK counted 72 verified \"wrench attacks\" in 2025, physical attacks to force victims to hand over crypto, up 75% from the year before, Decrypt reported. Losses topped $40.9 million.", "kicker": "Apply day 28: wallet theft is not only online.", "fullText": "Europe accounted for over 40% of incidents, up from 22%, with France at 19 cases and the US at 8. Kidnapping was the most common method, and physical assaults rose 250%.\n\nIn January 2025, a Ledger co-founder was kidnapped in France, with a ransom of €10 million demanded; ten people were arrested.\n\nCertiK suggested decoy wallets, seed phrases kept apart from devices, multisig and time locks. Through the day 28 lens: personal wallets are a growing target.", "sources": [{"url": "https://decrypt.co/356604/41m-in-losses-as-crypto-wrench-attacks-hit-record-high-in-2025", "label": "Decrypt, crypto wrench attacks hit a record high in 2025, citing CertiK"}, {"url": "https://www.theblock.co/post/382477/crypto-hack-2025-chainalysis", "label": "The Block, crypto hacks hit $3.4 billion in 2025: Chainalysis"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Wrench attacks rose 75% in 2025", "Europe had over 40% of incidents", "The US had more incidents than France"], "fakeIndex": 2, "explanation": "France had 19 incidents and the US had 8."}, "numbers": {"kind": "numberSense", "prompt": "CertiK counted how many verified wrench attacks in 2025?", "min": 0, "max": 200, "value": 72, "explanation": "72, up 75% from the year before.", "unit": "attacks"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview for a security role at a crypto firm. They ask about wrench attacks.", "prompt": "Which answer is strongest?", "options": ["Only online hackers threaten crypto", "Strong passwords stop all wrench attacks", "Physical threats need defenses like multisig"], "correctIndex": 2, "consequences": ["Physical attacks rose 75%.", "Force bypasses passwords.", "CertiK listed multisig and time locks."], "explanation": "If one person can move funds alone, they become a target. Spread control."}, "proReasoning": "Strong candidates cover physical and digital security.", "commonMistake": "Ignoring threats outside the screen.", "mentalModel": "Spread control."}, "invest": {"call": {"kind": "theCall", "situation": "A client with large crypto holdings asks about safety.", "prompt": "What do you suggest they look into?", "options": ["Multisig, time locks and keeping a low profile", "Posting their holdings online for clarity", "Keeping seed words next to their device"], "correctIndex": 0, "consequences": ["CertiK suggested these defenses.", "That draws attention.", "CertiK advised keeping them apart."], "explanation": "Making sure no single person can move everything lowers the payoff of force."}, "proReasoning": "Advisers think about personal safety, not just markets.", "commonMistake": "Advertising wealth online.", "mentalModel": "Lower the payoff."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds wallet software.", "prompt": "Which feature responds to wrench attacks?", "options": ["A public page showing user balances", "Time-locked withdrawals for large amounts", "One-tap transfer of the whole balance"], "correctIndex": 1, "consequences": ["That exposes users.", "Delays reduce the value of force.", "That helps attackers."], "explanation": "Time locks mean an attacker cannot get everything at once."}, "proReasoning": "Founders design for the threats users actually face.", "commonMistake": "Optimizing speed over safety.", "mentalModel": "Slow down large moves."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what a \"wrench attack\" is.", "prompt": "What's the best answer?", "options": ["A bug that breaks a smart contract online", "A sudden, fast drop in coin prices", "Forcing someone in person to give up crypto"], "correctIndex": 2, "consequences": ["That is a hack.", "That is a crash.", "Kidnapping was the most common method."], "explanation": "It means using force or threats in person to get someone's crypto."}, "proReasoning": "The name comes from the idea that a wrench beats encryption.", "commonMistake": "Thinking crypto risk is only digital.", "mentalModel": "Force beats code."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ab317412df4a$ml$]::text[]),
($ml$cb2be739-8116-51d7-b0ee-4ff764d663fb$ml$::uuid, $ml$web3$ml$, 28, 2, $ml${"id": "web3-d28-c2", "title": "One heist, a record year", "lessonTitle": "The everyday wallet thefts", "slot": 2, "type": "connect", "brief": {"headline": "In February 2025, hackers stole about $1.5 billion from Bybit, which the FBI attributed to North Korea. Chainalysis said North Korea stole at least $2.02 billion in 2025.", "kicker": "Connect day 5 and day 28: stolen keys at scale and at home.", "fullText": "Day 5 showed that whoever controls the private keys controls the funds, and Bybit's loss showed it at huge scale.\n\nDay 28 showed the full year: about $3.41 billion stolen, with North Korea taking at least $2.02 billion, $681 million more than in 2024. Personal wallet thefts fell to about $713 million, but hit at least 80,000 people.", "sources": [{"url": "https://www.ic3.gov/PSA/2025/PSA250226", "label": "FBI IC3, Bybit theft alert"}, {"url": "https://www.theblock.co/post/382477/crypto-hack-2025-chainalysis", "label": "The Block, crypto hacks hit $3.4 billion in 2025: Chainalysis"}]}, "evidence": {"kind": "faceOff", "prompt": "Which loss made up most of North Korea's 2025 total?", "left": {"name": "The Bybit theft", "note": "About $1.5 billion in one attack"}, "right": {"name": "Personal wallet thefts", "note": "About $713 million across many people"}, "correctIndex": 0, "explanation": "Bybit alone was about $1.5 billion of North Korea's $2.02 billion or more."}, "numbers": {"kind": "numberSense", "prompt": "North Korea stole at least about how many billion dollars in 2025?", "min": 0, "max": 6, "value": 2, "explanation": "At least $2.02 billion, Chainalysis said.", "unit": "B"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks for the key theme in 2025 crypto theft.", "prompt": "Which answer leads?", "options": ["A few huge key thefts drove most losses", "Thefts stopped after new rules", "Only small wallets were targeted that year"], "correctIndex": 0, "consequences": ["Bybit was about $1.5 billion.", "Thefts totaled about $3.41 billion.", "Exchanges were hit hardest."], "explanation": "One theft dwarfed the rest. Key control at large firms is the top risk."}, "proReasoning": "Analysts look at how losses are distributed.", "commonMistake": "Averaging away the biggest event.", "mentalModel": "A few giant losses."}, "invest": {"call": {"kind": "theCall", "situation": "You assess an exchange's security.", "prompt": "What do you focus on?", "options": ["How bright and modern its app looks", "How it controls the keys to its wallets", "How many coins it lists for trading"], "correctIndex": 1, "consequences": ["Design is not security.", "Bybit lost funds through keys.", "Listings are not security."], "explanation": "Large thefts came through key control. That is what to examine."}, "proReasoning": "Investors ask how keys are stored and approved.", "commonMistake": "Judging security by features.", "mentalModel": "Follow the keys."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells security to exchanges.", "prompt": "What does the 2025 data suggest?", "options": ["Attacks are fading away year after year", "Only individuals need protection from attacks", "Exchanges face skilled, well-funded attackers"], "correctIndex": 2, "consequences": ["Losses rose in 2025.", "Exchanges suffered the largest loss.", "North Korea took over $2 billion."], "explanation": "State-backed groups target large key holders. Defenses must match."}, "proReasoning": "Founders size the threat before designing.", "commonMistake": "Underestimating attacker skill.", "mentalModel": "Match the threat."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how one hack can steal $1.5 billion.", "prompt": "What's the best answer?", "options": ["The attackers got control of the keys", "They guessed the coin price right", "They printed extra bitcoin"], "correctIndex": 0, "consequences": ["Keys move funds.", "Prices do not move funds.", "No one can print bitcoin."], "explanation": "Whoever controls the keys can move the funds, no matter who owns them."}, "proReasoning": "Like stealing the master key to a vault.", "commonMistake": "Thinking the blockchain itself was broken.", "mentalModel": "The master key."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b141b9547630$ml$]::text[]),
($ml$f9366e10-b2c5-5a8c-abd5-579836d6d2ba$ml$::uuid, $ml$web3$ml$, 28, 3, $ml${"id": "web3-d28-c3", "title": "Protecting customers from everyday wallet theft", "lessonTitle": "The everyday wallet thefts", "slot": 3, "type": "decide", "brief": {"headline": "You run security for a consumer wallet app. Chainalysis counted 158,000 personal wallet compromises in 2025, hitting at least 80,000 people and taking about $713 million.", "kicker": "Decide where to put your security budget.", "fullText": "Personal wallet losses fell from $1.5 billion in 2024 to about $713 million in 2025, but many more people were affected.\n\nTotal crypto theft was about $3.41 billion. Your users are mostly individuals with modest balances.", "sources": [{"url": "https://www.theblock.co/post/382477/crypto-hack-2025-chainalysis", "label": "The Block, crypto hacks hit $3.4 billion in 2025: Chainalysis"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is this a likely threat to your users, or mostly a risk for big platforms?", "buckets": ["Likely for your users", "Mostly big platforms"], "items": [{"text": "Phishing links that drain wallets", "bucket": 0}, {"text": "Seed phrases leaked by scams", "bucket": 0}, {"text": "State-backed attacks on exchange keys", "bucket": 1}, {"text": "Malicious approvals signed by mistake", "bucket": 0}, {"text": "Billion-dollar exchange hacks", "bucket": 1}], "explanation": "Individuals face phishing, scams and bad approvals. Giant heists target platforms."}, "numbers": {"kind": "numberSense", "prompt": "About how many thousand personal wallet compromises happened in 2025?", "min": 0, "max": 400, "value": 158, "explanation": "About 158,000, hitting at least 80,000 people.", "unit": "K"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO asks where to spend.", "prompt": "What do you recommend?", "options": ["Marketing that promises zero theft", "Warnings on risky signatures and scams", "Only harder server encryption"], "correctIndex": 1, "consequences": ["No one can promise that.", "That fits everyday threats.", "Most losses come at the user end."], "explanation": "Personal thefts mostly start with users being tricked. Defend that moment."}, "proReasoning": "Leaders spend where losses actually happen.", "commonMistake": "Defending against the wrong threat.", "mentalModel": "Defend the moment."}, "invest": {"call": {"kind": "theCall", "situation": "A wallet app highlights its \"bank-grade servers.\"", "prompt": "What do you ask?", "options": ["How many servers it runs", "Which colors the app uses on screen", "How it protects users from scams"], "correctIndex": 2, "consequences": ["Servers matter less here.", "Colors are not security.", "Scams drive personal theft."], "explanation": "Most personal losses come from tricks, not server breaches."}, "proReasoning": "Investors test security claims against real losses.", "commonMistake": "Accepting marketing claims as protection.", "mentalModel": "Ask about scams."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup could add one feature this quarter.", "prompt": "Which helps most?", "options": ["Simulating transactions before signing", "A new coin swap screen for traders", "A dark mode theme for night use"], "correctIndex": 0, "consequences": ["Users see what they approve.", "Nice, but not protection.", "Nice, but not protection."], "explanation": "Showing what a signature will do stops many drains."}, "proReasoning": "Founders fix the biggest source of user losses first.", "commonMistake": "Shipping features while losses continue.", "mentalModel": "Show before signing."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how most people lose crypto.", "prompt": "What's the best answer?", "options": ["Banks freezing their wallets at will", "Being tricked into signing or sharing keys", "Blockchains randomly deleting their coins"], "correctIndex": 1, "consequences": ["Self-custody has no bank.", "Scams drive personal losses.", "Blockchains do not do that."], "explanation": "Most personal theft starts with a scam. Slow down before signing."}, "proReasoning": "Like a con artist, not a safecracker.", "commonMistake": "Thinking only hackers with code are the danger.", "mentalModel": "A con, not a crack."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:87daeca339b2$ml$]::text[]),
($ml$49879062-94e7-5465-b0bd-884b3da0b6a6$ml$::uuid, $ml$web3$ml$, 29, 1, $ml${"id": "web3-d29-c1", "title": "A big bank resumes bitcoin custody", "lessonTitle": "The accounting rule that kept banks out", "slot": 1, "type": "apply", "brief": {"headline": "In September 2025, U.S. Bank said it had resumed bitcoin custody for institutional investment managers, a service it first announced in 2021, and added support for bitcoin ETFs.", "kicker": "Apply day 29: banks returned to crypto custody after the rule changed.", "fullText": "U.S. Bank uses NYDIG as sub-custodian. It said: \"Following greater regulatory clarity, we've expanded our offering to include bitcoin ETFs.\" The bank reported $11.7 trillion in assets under custody and administration.\n\nIts announcement did not name a specific rule.\n\nThrough the day 29 lens: the SEC rescinded SAB 121 in January 2025. That guidance had required firms to record crypto held for clients as a liability at fair value.", "sources": [{"url": "https://ir.usbank.com/news-events/news/news-details/2025/U-S--Bank-Resumes-Bitcoin-Cryptocurrency-Custody-Services-for-Institutional-Investment-Managers/default.aspx", "label": "U.S. Bank, resumes bitcoin custody for institutional investment managers, Sep 2025"}, {"url": "https://www.withum.com/resources/sec-issues-sab-122-officially-rescinding-sab-121/", "label": "Withum, SEC issues SAB 122 rescinding SAB 121"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the events in order.", "steps": ["The bank first announces crypto custody", "SAB 121 guidance is issued", "The SEC rescinds SAB 121", "The bank resumes bitcoin custody", "It adds support for bitcoin ETFs"], "explanation": "2021, March 2022, January 2025, then September 2025."}, "numbers": {"kind": "numberSense", "prompt": "About how many months after SAB 121 was rescinded did U.S. Bank resume custody?", "min": 0, "max": 24, "value": 8, "explanation": "From January to September 2025 is about 8 months, by our count.", "unit": "months"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a bank's custody unit. They ask what U.S. Bank's move shows.", "prompt": "Which answer is strongest?", "options": ["Large banks are returning to crypto custody", "Banks are leaving crypto entirely", "Custody no longer needs sub-custodians"], "correctIndex": 0, "consequences": ["It resumed and expanded custody.", "It did the opposite.", "It uses NYDIG."], "explanation": "A major bank resumed custody and cited greater regulatory clarity."}, "proReasoning": "Strong candidates quote what the bank said.", "commonMistake": "Claiming a cause the bank did not state.", "mentalModel": "Quote, do not guess."}, "invest": {"call": {"kind": "theCall", "situation": "You write a note on banks and crypto.", "prompt": "How do you describe the link to SAB 121?", "options": ["There is no rule history to mention", "The timing follows it; the bank cited clarity", "The bank said SAB 121 alone caused the move"], "correctIndex": 1, "consequences": ["The rescission is relevant.", "Accurate and careful.", "The release did not say that."], "explanation": "Report the timing and the bank's words. Do not invent a cause."}, "proReasoning": "Analysts separate timing from causation.", "commonMistake": "Stating causation without evidence.", "mentalModel": "Timing, not cause."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers custody technology.", "prompt": "What does this suggest?", "options": ["Banks will build every part of it alone", "Custody demand is shrinking", "Banks may need partners to offer custody"], "correctIndex": 2, "consequences": ["It relies on a sub-custodian.", "It expanded the service.", "It relies on NYDIG as sub-custodian."], "explanation": "Banks entering custody may partner with specialists, as U.S. Bank did."}, "proReasoning": "Founders look for partners in new bank services.", "commonMistake": "Assuming banks never partner.", "mentalModel": "Partner with banks."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a bank would hold bitcoin for clients.", "prompt": "What's the best answer?", "options": ["Clients want a trusted firm to guard it", "Banks must own some bitcoin by federal law", "To mine bitcoin inside its branches"], "correctIndex": 0, "consequences": ["Custody is a service.", "No such law exists.", "Custody is not mining."], "explanation": "Big investors want regulated firms to hold assets for them."}, "proReasoning": "Like a bank safe-deposit box for digital assets.", "commonMistake": "Thinking custody means the bank owns it.", "mentalModel": "A safe-deposit box."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2017c729888e$ml$]::text[]),
($ml$53ca54e1-b273-502f-8e0a-6dd9e9bc1e80$ml$::uuid, $ml$web3$ml$, 29, 2, $ml${"id": "web3-d29-c2", "title": "Why one firm held most ETF bitcoin", "lessonTitle": "The accounting rule that kept banks out", "slot": 2, "type": "connect", "brief": {"headline": "Coinbase holds more than 80% of US bitcoin ETF custody, its CEO said in February 2026. From March 2022 to January 2025, SAB 121 made crypto custody costly for banks.", "kicker": "Connect day 27 and day 29: an accounting rule shaped who holds the coins.", "fullText": "Day 27 showed custody concentration: most US bitcoin ETF coins sit with Coinbase.\n\nDay 29 showed SAB 121, which required firms holding crypto for clients to record a liability at fair value. For banks, that made custody expensive. SAB 122 rescinded it in January 2025, returning firms to standard accounting rules. It was described as removing \"non-technology-neutral barriers.\"", "sources": [{"url": "https://bitcoinmagazine.com/news/coinbase-ceo-addresses-paper-bitcoin", "label": "Bitcoin Magazine, Coinbase CEO addresses paper bitcoin concerns"}, {"url": "https://www.withum.com/resources/sec-issues-sab-122-officially-rescinding-sab-121/", "label": "Withum, SEC issues SAB 122 rescinding SAB 121"}, {"url": "https://www.cliffordchance.com/briefings/2025/01/sec-rescinds-2022-accounting-guidance-regarding-crypto-assets-un.html", "label": "Clifford Chance, SEC rescinds 2022 crypto custody accounting guidance"}]}, "evidence": {"kind": "faceOff", "prompt": "What did SAB 121 require firms holding crypto for clients to do?", "left": {"name": "Record a liability at fair value", "note": "Put client crypto on their own books"}, "right": {"name": "Stop holding crypto entirely", "note": "Ban all crypto custody services"}, "correctIndex": 0, "explanation": "SAB 121 required a liability at fair value, which made custody costly for banks."}, "numbers": {"kind": "numberSense", "prompt": "About how many months was SAB 121 in force?", "min": 0, "max": 60, "value": 34, "explanation": "From March 2022 to January 2025 is about 34 months, by our count.", "unit": "months"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks why banks were slow to offer crypto custody.", "prompt": "Which answer leads?", "options": ["Bitcoin cannot be held by any bank", "SAB 121 made it costly to hold client crypto", "Banks were banned from touching crypto"], "correctIndex": 1, "consequences": ["Banks can hold it.", "A fair-value liability weighed on books.", "It was guidance, not a ban."], "explanation": "An accounting rule raised the cost of custody for banks."}, "proReasoning": "Analysts look for rules behind market structure.", "commonMistake": "Missing how accounting shapes behavior.", "mentalModel": "Rules shape markets."}, "invest": {"call": {"kind": "theCall", "situation": "You consider custody concentration in ETFs.", "prompt": "What may change after SAB 122?", "options": ["Coinbase must give up all of its custody", "ETFs must stop using custodians", "More banks could compete to hold ETF coins"], "correctIndex": 2, "consequences": ["No such rule exists.", "Custody is required.", "The barrier was removed."], "explanation": "With the barrier gone, banks can compete. Concentration could ease."}, "proReasoning": "Investors watch rule changes that reshape competition.", "commonMistake": "Assuming market shares are fixed.", "mentalModel": "Watch new entrants."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup serves banks entering custody.", "prompt": "Why is timing good now?", "options": ["SAB 122 removed an accounting barrier", "Banks are now forced to offer custody", "Crypto no longer needs custody"], "correctIndex": 0, "consequences": ["Banks can now compete.", "Nothing forces them.", "Custody is still needed."], "explanation": "A rule that kept banks out is gone. Banks need help to enter."}, "proReasoning": "Founders time products to regulatory openings.", "commonMistake": "Missing a window that just opened.", "mentalModel": "Use the opening."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how an accounting rule kept banks out of crypto.", "prompt": "What's the best answer?", "options": ["It forced banks to sell all their bitcoin", "It made client crypto count against their books", "It made holding crypto illegal for banks"], "correctIndex": 1, "consequences": ["It did not force sales.", "A liability at fair value.", "It was not a ban."], "explanation": "Booking client crypto as a liability made custody costly."}, "proReasoning": "Like counting a stored package as your own debt.", "commonMistake": "Thinking only laws, not accounting, shape markets.", "mentalModel": "Accounting matters."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:50a574062da2$ml$]::text[]),
($ml$5b8e85dc-9282-5f5c-8bec-7e128eb50529$ml$::uuid, $ml$web3$ml$, 29, 3, $ml${"id": "web3-d29-c3", "title": "Should your bank offer crypto custody now?", "lessonTitle": "The accounting rule that kept banks out", "slot": 3, "type": "decide", "brief": {"headline": "You lead custody at a mid-sized bank. SAB 121, issued in March 2022, was rescinded on January 23, 2025, and SAB 122 returned firms to standard accounting rules.", "kicker": "Decide whether and how to enter crypto custody.", "fullText": "SAB 121 had required a liability at fair value for crypto held for clients. Its rescission removed what SAB 122 called \"non-technology-neutral barriers.\"\n\nYour clients ask about bitcoin ETFs and direct holdings. Building custody needs secure key management, or a specialist partner.", "sources": [{"url": "https://www.withum.com/resources/sec-issues-sab-122-officially-rescinding-sab-121/", "label": "Withum, SEC issues SAB 122 rescinding SAB 121"}, {"url": "https://www.cliffordchance.com/briefings/2025/01/sec-rescinds-2022-accounting-guidance-regarding-crypto-assets-un.html", "label": "Clifford Chance, SEC rescinds 2022 crypto custody accounting guidance"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this point toward partnering or building in-house?", "buckets": ["Partner first", "Build in-house"], "items": [{"text": "You need to launch within months", "bucket": 0}, {"text": "Your team lacks key-management experience", "bucket": 0}, {"text": "You expect huge volumes for years", "bucket": 1}, {"text": "You want full control over every step", "bucket": 1}, {"text": "You want to test client demand first", "bucket": 0}], "explanation": "Partners speed entry. Building pays off at scale with strong expertise."}, "numbers": {"kind": "numberSense", "prompt": "SAB 121 was issued in which month of 2022?", "min": 0, "max": 12, "value": 3, "explanation": "March 2022, month 3.", "unit": "month"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO asks how to enter custody.", "prompt": "What do you recommend?", "options": ["Build everything in-house before asking clients", "Wait for SAB 121 to come back", "Start with a specialist partner, then decide"], "correctIndex": 2, "consequences": ["Slow and costly.", "It was rescinded.", "Fast, lower risk."], "explanation": "A partner lets you test demand. Build later if volumes justify it."}, "proReasoning": "Leaders sequence entry to manage risk.", "commonMistake": "Overbuilding before testing demand.", "mentalModel": "Partner, then decide."}, "invest": {"call": {"kind": "theCall", "situation": "A bank announces crypto custody.", "prompt": "What do you check?", "options": ["Who manages the keys and how", "How many branches it has", "Its logo redesign"], "correctIndex": 0, "consequences": ["Key management is the risk.", "Branches do not hold keys.", "Logos do not hold keys."], "explanation": "Custody quality rests on key management."}, "proReasoning": "Investors ask who holds and approves keys.", "commonMistake": "Judging custody by bank size.", "mentalModel": "Check the keys."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup provides custody to banks.", "prompt": "Who is your best first customer?", "options": ["Banks waiting for SAB 121 to return", "Mid-sized banks that want to launch fast", "Banks that refuse to touch crypto"], "correctIndex": 1, "consequences": ["It was rescinded.", "They need speed and skill.", "They are not buying."], "explanation": "Banks that want quick entry without building are the best fit."}, "proReasoning": "Founders sell to buyers who are ready now.", "commonMistake": "Chasing customers who are not interested.", "mentalModel": "Sell to the ready."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why banks are only now offering crypto.", "prompt": "What's the best answer?", "options": ["Bitcoin was illegal in the US until 2025", "Banks only just heard of bitcoin this decade", "An accounting rule that made it costly was dropped"], "correctIndex": 2, "consequences": ["It was not illegal.", "Banks knew of it.", "SAB 121 was rescinded in 2025."], "explanation": "A rule made custody expensive. Its removal opened the door."}, "proReasoning": "Like a fee that kept shops from opening until it was scrapped.", "commonMistake": "Assuming banks were banned.", "mentalModel": "The fee was scrapped."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:194b481d7484$ml$]::text[]),
($ml$40780d1a-bc94-5946-bd83-3719993b70b4$ml$::uuid, $ml$web3$ml$, 30, 1, $ml${"id": "web3-d30-c1", "title": "August's phishing wave", "lessonTitle": "Smart wallets and their new risks", "slot": 1, "type": "apply", "brief": {"headline": "In August 2025, crypto phishing drained more than $12 million from over 15,000 wallets, according to Scam Sniffer data reported by BeInCrypto. Losses rose 72% from July.", "kicker": "Apply day 30: new wallet features can be turned into new tricks.", "fullText": "The number of victims rose 67%. Scam Sniffer said EIP-7702 was the main tool in August's attacks.\n\nEIP-7702, added in the Pectra upgrade, lets an ordinary wallet delegate to smart contract code. That enables features like batching, but a single tricked signature can hand control to an attacker's contract.\n\nThrough the day 30 lens: smart wallets bring new conveniences and new risks.", "sources": [{"url": "https://beincrypto.com/crypto-phishing-scams-rise-in-august-2025", "label": "BeInCrypto, crypto phishing losses rise in August 2025, citing Scam Sniffer"}, {"url": "https://cointelegraph.com/news/wintermute-crimeenjoyor-flags-malicious-ethereum-contracts", "label": "Cointelegraph, Wintermute's CrimeEnjoyor flags malicious Ethereum contracts"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Phishing drained over $12 million in August", "Losses rose 72% from July", "EIP-7702 played no part in the attacks"], "fakeIndex": 2, "explanation": "Scam Sniffer said EIP-7702 was the main tool in August's attacks."}, "numbers": {"kind": "numberSense", "prompt": "Phishing hit over how many thousand wallets in August 2025?", "min": 0, "max": 40, "value": 15, "explanation": "Over 15,000 wallets.", "unit": "K"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a wallet company. They ask about EIP-7702 risks.", "prompt": "Which answer is strongest?", "options": ["It only affects hardware wallets", "One bad signature can delegate a wallet to attackers", "EIP-7702 makes every wallet impossible to phish"], "correctIndex": 1, "consequences": ["It affects ordinary wallets.", "That is how August's attacks worked.", "Losses rose in August."], "explanation": "Delegation is powerful. Tricking a user into it hands over control."}, "proReasoning": "Strong candidates explain both the feature and its abuse.", "commonMistake": "Treating new features as purely good.", "mentalModel": "Power cuts both ways."}, "invest": {"call": {"kind": "theCall", "situation": "You assess wallet security trends.", "prompt": "What does August show?", "options": ["Phishing is slowly disappearing", "Only exchanges face phishing attacks", "Attackers adapt quickly to new features"], "correctIndex": 2, "consequences": ["Losses rose 72%.", "Over 15,000 wallets were hit.", "EIP-7702 was the main tool."], "explanation": "New features create new attack paths within months."}, "proReasoning": "Investors watch how fast threats follow upgrades.", "commonMistake": "Assuming upgrades only reduce risk.", "mentalModel": "Threats follow features."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds a smart wallet.", "prompt": "What do you add before launch?", "options": ["Clear warnings before any delegation", "Silent delegation to save a tap", "Auto-approval of every request"], "correctIndex": 0, "consequences": ["Users see what they approve.", "That helps attackers.", "That helps attackers."], "explanation": "Make delegation visible and deliberate."}, "proReasoning": "Founders design for misuse.", "commonMistake": "Hiding powerful actions to cut friction.", "mentalModel": "Make it visible."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a wallet gets drained by phishing.", "prompt": "What's the best answer?", "options": ["Their phone battery runs out mid-transfer", "They sign something that hands over control", "The blockchain makes a random mistake"], "correctIndex": 1, "consequences": ["Battery has no effect.", "Signatures authorize actions.", "The chain does what is signed."], "explanation": "Phishing tricks people into signing approvals that let attackers move funds."}, "proReasoning": "Like signing a blank check.", "commonMistake": "Thinking the blockchain itself failed.", "mentalModel": "A blank check."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4b80c8744c9e$ml$]::text[]),
($ml$4d631d16-fcd0-538e-9514-86cb19da6f24$ml$::uuid, $ml$web3$ml$, 30, 2, $ml${"id": "web3-d30-c2", "title": "From seed words to signatures", "lessonTitle": "Smart wallets and their new risks", "slot": 2, "type": "connect", "brief": {"headline": "A seed phrase restores every key in a wallet, so guarding it was the main rule. Since Pectra in May 2025, EIP-7702 lets wallets delegate to code, and over 97% of early delegations went to the same sweeper contract.", "kicker": "Connect day 25 and day 30: a wallet can be lost without sharing its words.", "fullText": "Day 25 showed that whoever holds the seed words controls the funds.\n\nDay 30 showed a new path. With EIP-7702, one signature can delegate a wallet to a contract. Wintermute found over 97% of early delegations went to the same sweeper contract, which drains funds. One user lost $146,550. The seed words stayed secret, but the signature gave control away.", "sources": [{"url": "https://trezor.io/learn/advanced/what-is-bip39", "label": "Trezor, what is BIP39?"}, {"url": "https://cointelegraph.com/news/wintermute-crimeenjoyor-flags-malicious-ethereum-contracts", "label": "Cointelegraph, Wintermute's CrimeEnjoyor flags malicious Ethereum contracts"}]}, "evidence": {"kind": "multipleChoice", "prompt": "How did early EIP-7702 victims lose funds?", "options": ["By posting their seed words online", "By losing their hardware device", "By signing a delegation to a sweeper"], "correctIndex": 2, "explanation": "They signed delegations to a sweeper contract. Seed words were not needed."}, "numbers": {"kind": "numberSense", "prompt": "Over what percent of early delegations went to the same sweeper contract?", "min": 0, "max": 100, "value": 97, "explanation": "Over 97%, Wintermute found.", "unit": "%"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks how wallet security advice must change.", "prompt": "Which answer leads?", "options": ["Seed words no longer matter at all", "Signatures can never move funds", "Guard signatures as well as seed words"], "correctIndex": 2, "consequences": ["Words still restore wallets.", "Delegations moved funds.", "Delegation can drain a wallet."], "explanation": "The old rule still holds. A new one joins it: check what you sign."}, "proReasoning": "Security teams update advice when features change.", "commonMistake": "Teaching only last year's threat.", "mentalModel": "Two rules now."}, "invest": {"call": {"kind": "theCall", "situation": "You review a wallet provider.", "prompt": "What do you check?", "options": ["How it warns users about delegations", "Whether it shows seed words on screen", "How many coins it supports"], "correctIndex": 0, "consequences": ["Delegation is the new risk.", "That would be a flaw.", "Coins do not affect this risk."], "explanation": "Providers must help users spot dangerous delegations."}, "proReasoning": "Investors check whether products keep up with threats.", "commonMistake": "Assuming seed safety covers everything.", "mentalModel": "Check delegations."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup teaches wallet safety.", "prompt": "What lesson do you add?", "options": ["Approve requests quickly to save gas", "Read what a signature authorizes", "Share seed words with trusted apps"], "correctIndex": 1, "consequences": ["Speed helps attackers.", "Delegations can drain wallets.", "Never share seed words."], "explanation": "Users need to know signatures can hand over control."}, "proReasoning": "Founders teach the newest scams.", "commonMistake": "Leaving signature risks out of training.", "mentalModel": "Read before signing."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how they could lose crypto without sharing their words.", "prompt": "What's the best answer?", "options": ["They cannot lose it that way, not ever", "Only if the blockchain shuts down", "By signing a request that gives control away"], "correctIndex": 2, "consequences": ["Victims lost funds that way.", "Chains kept running.", "EIP-7702 delegations did that."], "explanation": "A signature can authorize code to move your funds."}, "proReasoning": "Like signing over power of attorney by mistake.", "commonMistake": "Thinking seed words are the only risk.", "mentalModel": "Power of attorney."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9f77377e9d3f$ml$]::text[]),
($ml$08fb8b9b-8dc5-5482-b2ae-15aa22299cce$ml$::uuid, $ml$web3$ml$, 30, 3, $ml${"id": "web3-d30-c3", "title": "Ship smart wallet features or wait?", "lessonTitle": "Smart wallets and their new risks", "slot": 3, "type": "decide", "brief": {"headline": "You run product at a wallet app. Pectra's EIP-7702 lets wallets delegate to smart contract code, and Fusaka added support for passkey signatures through secp256r1.", "kicker": "Decide how to roll out smart wallet features.", "fullText": "Passkeys let users sign with a phone's built-in security instead of managing seed words. EIP-7702 allows batching and other features.\n\nBut Wintermute found over 97% of early 7702 delegations went to one sweeper contract, and one user lost $146,550.", "sources": [{"url": "https://cointelegraph.com/news/wintermute-crimeenjoyor-flags-malicious-ethereum-contracts", "label": "Cointelegraph, Wintermute's CrimeEnjoyor flags malicious Ethereum contracts"}, {"url": "https://blog.ethereum.org/2025/11/06/fusaka-mainnet-announcement", "label": "Ethereum Foundation blog, Fusaka mainnet announcement"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this make smart wallet features safer or riskier?", "buckets": ["Safer", "Riskier"], "items": [{"text": "Showing clear delegation warnings", "bucket": 0}, {"text": "Allowing only audited contracts", "bucket": 0}, {"text": "Delegating silently in the background", "bucket": 1}, {"text": "Letting any site request delegation", "bucket": 1}, {"text": "Passkeys backed by device security", "bucket": 0}], "explanation": "Clear warnings, audited contracts and passkeys help. Silent, open delegation hurts."}, "numbers": {"kind": "numberSense", "prompt": "Pectra went live in which month of 2025?", "min": 0, "max": 12, "value": 5, "explanation": "May 2025, month 5.", "unit": "month"}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO asks whether to ship.", "prompt": "What do you recommend?", "options": ["Ship with audited contracts and clear warnings", "Ship with silent delegation to make it easier", "Never ship smart wallet features"], "correctIndex": 0, "consequences": ["Benefits with guardrails.", "Silent delegation helps attackers.", "You lose the benefits."], "explanation": "Smart wallets help users. Guardrails keep delegation from becoming a trap."}, "proReasoning": "Product leaders ship features with safety rails.", "commonMistake": "Choosing between all or nothing.", "mentalModel": "Ship with rails."}, "invest": {"call": {"kind": "theCall", "situation": "A wallet app launches 7702 features.", "prompt": "What do you look for?", "options": ["Whether it has a new logo to match the launch", "Limits on which contracts users can pick", "How fast it added the new feature"], "correctIndex": 1, "consequences": ["Logos are not safety.", "Limits reduce sweeper risk.", "Speed is not safety."], "explanation": "Most early delegations went to one sweeper. Limits matter."}, "proReasoning": "Investors check guardrails on risky features.", "commonMistake": "Praising speed over safety.", "mentalModel": "Check guardrails."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup could lead with passkeys.", "prompt": "Why is that appealing?", "options": ["Passkeys remove every bit of phishing risk", "Passkeys need no device at all", "Users sign with device security, not words"], "correctIndex": 2, "consequences": ["Phishing still exists.", "They use the device.", "Fusaka added secp256r1 support."], "explanation": "Passkeys make signing easier. Phishing still needs guarding."}, "proReasoning": "Founders pair convenience with clear warnings.", "commonMistake": "Selling passkeys as total protection.", "mentalModel": "Easier, not immune."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if smart wallets are safer.", "prompt": "What's the best answer?", "options": ["Easier to use, with new risks to watch", "Totally safe, nothing to worry about", "Always more dangerous than old wallets"], "correctIndex": 0, "consequences": ["Delegation scams rose.", "Over 97% of early delegations hit one sweeper.", "Passkeys can help."], "explanation": "Smart wallets add features and new ways to be tricked."}, "proReasoning": "Like a smart lock: handy, but guard the app.", "commonMistake": "Assuming new means safe or new means bad.", "mentalModel": "Handy, with care."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:66fe8042e97e$ml$]::text[])
